      "path": "src/host/intent-journal.ts",
      "content": "/**\n * dsh-recall-plugin — 操作意图 journal（A2，吸收 U4 留痕职能）\n *\n * 堵 execute both 分支的崩溃窗口：安全快照 → rollbackFor → rescue 中途断电\n * 时，安全快照 tag 已在磁盘而没有任何记录指向它——用户不知道工作区可能半\n * 回退，也不知道救援锚点存在。纪律：**先落意图再动磁盘，启动预热 / init\n * 时续做（recover）**。\n *\n * 判定顺序（stale journal 防线）：有记录先做幂等判定——工作区与目标\n * snap-<messageId> 一致说明回退实际已完成（clear 失败留下的残留记录），\n * 只清记录不 reset；否则残留记录会被误救援、把已完成的回退撤销回安全快照\n * （plan-quality-hardening A2，单测钉死该路径）。\n *\n * 写入走 writeTextViaShell（tmp+rename 原子写）；清空 = 写空串（不引入删除\n * 命令——读侧空串按「无记录」处理，同 format marker 语义）。journal 写失败\n * 只 recordError 告警、不阻断主流程（U4 纪律）。\n */\n\nimport type { StoreInfo } from '../types/state.js'\nimport type { RecallIntent } from '../types/payloads.js'\nimport type { PwshScripts, PosixScripts } from '../types/scripts.js'\n\nexport interface IntentJournalDeps {\n  runShell(cmd: string, opts?: { timeoutMs?: number; stdoutMaxBytes?: number }): Promise<string>\n  writeTextViaShell(file: string, text: string): Promise<void>\n  scripts: PwshScripts | PosixScripts\n  isWin: boolean\n  recordError(text: string): void\n  // ---- 恢复期动作注入（复用既有机制，不在本模块复制实现）----\n  // 幂等判定：工作区与 snap-<messageId> 一致（diff 无差异）即回退已完成\n  workspaceMatchesTag(messageId: string): Promise<boolean>\n  // H1 救援的同款 reset（rescueScript + RESCUE_OK 哨兵），true = 已复位\n  resetToSafety(store: StoreInfo, safetyId: string, root: string): Promise<boolean>\n  // execute P0-1 同款护栏：工作区有 agent 在跑时不动文件\n  agentBusy(root: string): boolean\n}\n\nexport interface IntentJournal {\n  begin(store: StoreInfo, root: string, fields: { messageId: string; safetyId: string; safetyOk: boolean }): Promise<void>\n  advance(store: StoreInfo, phase: 'rollback' | 'rescue'): Promise<void>\n  clear(store: StoreInfo): Promise<void>\n  read(store: StoreInfo): Promise<RecallIntent | null>\n  file(store: StoreInfo): string\n  recover(store: StoreInfo): Promise<boolean>\n}\n\nconst INTENT_VERSION = 1\n\n// 意图摘要（告警文案用）：不嵌长路径，只给定位所需的最小信息\nfunction describeIntent(intent: RecallIntent): string {\n  return 'message=' + intent.messageId + ', phase=' + intent.phase + ', safety=snap-' + intent.safetyId\n}\n\nexport function createIntentJournal(deps: IntentJournalDeps): IntentJournal {\n  // 已判定过的 store 去重（预热 + init 双挂载点幂等）：同进程内不重复判定/\n  // 告警。「读取命令失败」不入集——留给下一次 init 重试（瞬态 shell 故障\n  // 不得吞掉恢复时机）\n  const handled = new Set<string>()\n\n  function intentFile(store: StoreInfo): string {\n    return store.dir + (deps.isWin ? '\\\\' : '/') + 'recall-intent.json'\n  }\n\n  // 内部读：区分「定论（无记录/损坏）」与「读取命令失败」——前者可以入\n  // handled 集，后者必须留给下一次 init 重试\n  async function readRaw(store: StoreInfo): Promise<{ ok: boolean; intent: RecallIntent | null }> {\n    let raw = ''\n    try {\n      raw = deps.scripts.stripBom(await deps.runShell(deps.scripts.fileReadCmd(intentFile(store)), { timeoutMs: 30000, stdoutMaxBytes: 65536 })).trim()\n    } catch (error) {\n      // 读取失败静默（不刷错误环）：恢复时机由下一次 init 续上\n      return { ok: false, intent: null }\n    }\n    if (!raw) return { ok: true, intent: null } // 缺席 / 已清空（写空串）\n    try {\n      const obj = JSON.parse(raw) as Record<string, unknown>\n      if (!obj || obj.v !== INTENT_VERSION || obj.op !== 'execute'\n        || typeof obj.messageId !== 'string' || !obj.messageId\n        || typeof obj.safetyId !== 'string' || !obj.safetyId\n        || (obj.phase !== 'rollback' && obj.phase !== 'rescue')) {\n        // 形状不符按无处理：本地小文件，损坏不阻断启动（读取侧宽松纪律）\n        return { ok: true, intent: null }\n      }\n      return {\n        ok: true,\n        intent: {\n          v: INTENT_VERSION,\n          op: 'execute',\n          messageId: obj.messageId,\n          root: typeof obj.root === 'string' ? obj.root : '',\n          safetyId: obj.safetyId,\n          safetyOk: obj.safetyOk !== false,\n          phase: obj.phase,\n          time: typeof obj.time === 'number' ? obj.time : 0,\n        },\n      }\n    } catch (error) {\n      // JSON 解析失败（原子写承诺下只可能是人为编辑/磁盘故障）按无处理\n      return { ok: true, intent: null }\n    }\n  }\n\n  async function write(store: StoreInfo, text: string): Promise<void> {\n    try {\n      await deps.writeTextViaShell(intentFile(store), text)\n    } catch (error) {\n      // U4 纪律：写失败只告警、不阻断主流程（execute 照常回退）\n      deps.recordError('recall intent journal write failed: ' + String(error))\n    }\n  }\n\n  function read(store: StoreInfo): Promise<RecallIntent | null> {\n    return readRaw(store).then((r) => r.intent)\n  }\n\n  async function begin(store: StoreInfo, root: string, fields: { messageId: string; safetyId: string; safetyOk: boolean }): Promise<void> {\n    const intent: RecallIntent = {\n      v: INTENT_VERSION,\n      op: 'execute',\n      messageId: fields.messageId,\n      root,\n      safetyId: fields.safetyId,\n      safetyOk: fields.safetyOk,\n      phase: 'rollback',\n      time: Date.now(),\n    }\n    await write(store, JSON.stringify(intent))\n  }\n\n  async function advance(store: StoreInfo, phase: 'rollback' | 'rescue'): Promise<void> {\n    const cur = await read(store)\n    // 无记录（begin 写失败/已被清）时不凭空造记录——推进只是「改写已有意图」\n    if (cur) await write(store, JSON.stringify(Object.assign({}, cur, { phase })))\n  }\n\n  function clear(store: StoreInfo): Promise<void> {\n    return write(store, '')\n  }\n\n  // 崩溃恢复：无记录 → 空操作；有记录 → 先幂等判定再动作（见文件头注释）\n  async function recover(store: StoreInfo): Promise<boolean> {\n    if (handled.has(store.dir)) return false\n    const got = await readRaw(store)\n    if (!got.ok) return false // 读取失败：不入集，下次 init 重试\n    const intent = got.intent\n    if (!intent) {\n      handled.add(store.dir) // 无记录：定论，本轮不再查\n      return false\n    }\n    // 幂等判定先行（stale journal 防线）：一致 = 回退实际已完成，只清记录\n    if (await deps.workspaceMatchesTag(intent.messageId)) {\n      await clear(store)\n      handled.add(store.dir)\n      return true\n    }\n    // safetyOk=false 即「需救援但无救援点」（安全快照当时就失败）——保留\n    // 记录 + fail-loud，等下次启动重试（不能自动 reset：没有可复位目标）\n    if (!intent.safetyOk) {\n      deps.recordError('recall interrupted rollback detected, no safety snapshot: ' + describeIntent(intent) + '（记录保留于 ' + intentFile(store) + '）')\n      handled.add(store.dir)\n      return true\n    }\n    // P0-1 同款护栏：agent 在跑时不动工作区；不进程内重试（延后到下次 init）\n    if (deps.agentBusy(intent.root)) {\n      deps.recordError('recall interrupted rollback deferred (agent busy): ' + describeIntent(intent))\n      return false\n    }\n    const reset = await deps.resetToSafety(store, intent.safetyId, intent.root)\n    if (!reset) {\n      // 复位失败（tag 被手工删除 / git 环境故障）：保留记录 + fail-loud，\n      // 下次启动重试；同进程不循环写工作区\n      deps.recordError('recall interrupted rollback rescue failed: ' + describeIntent(intent) + '（记录保留于 ' + intentFile(store) + '）')\n      handled.add(store.dir)\n      return true\n    }\n    await clear(store)\n    handled.add(store.dir)\n    deps.recordError('recovered interrupted rollback: ' + describeIntent(intent) + ' — 工作区已复位到安全快照')\n    return true\n  }\n\n  return { begin, advance, clear, read, file: intentFile, recover }\n}"
    },
    {
      "path": "src/host/maintenance.ts",
      "content": "/**\n * dsh-recall-plugin — 快照维护（ctx 绑定的工厂，无模块级副作用）\n *\n * 职责：磁盘占用治理，两件事——\n * 1. 定期 git gc：全量保留策略下把 loose 对象压 pack + 跨版本 delta，\n *    无损（所有 tag 可达对象一个不丢），通常省一半以上空间；\n * 2. 会话删除联动清理：会话日志已从磁盘消失时，删除该会话全部快照 tag\n *    并重写索引，空间由紧随的同一次 gc --prune=now 真正释放。\n *\n * 触发点在每条用户消息快照之后的同一条串行队列里（见 index.js 的事件\n * 接线），因此 gc/清理与快照天然互斥，不存在 git 锁竞态。\n */\n\n// gc 节流阈值来自 config 域（设置页「插件配置」卡片可实时改写 cfg，\n// 因此这里按调用时取值而不是工厂创建时快照；环境变量\n// DSH_RECALL_GC_SNAPS/GC_HOURS 仍最高优先，见 config.js）：\n// 每 gcSnaps 条快照或距上次 gc gcHours 小时，先到先触发。默认「50 条或\n// 24 小时」——重活（gc）一天至多一次的量级，轻会话用户也不会等太久。\n\n// gc 失败重试退避（毫秒）：失败（超时/磁盘/杀软）只把 gcLastAt 回拨到\n// 「此刻 - gcHours + 退避」，让下一轮在退避窗口后自动重试，而不是推进完整\n// gcHours 周期。实测教训：失败推进整天周期会让对象库滚雪球——每次 gc 都更\n// 重、更容易超时，最终永远完不成（数 GB loose、in-pack 恒 0）。退避期间\n// gcCount 条数门槛照常生效，不会退化成「每条消息都重试」。\n// 与 GC_TIMEOUT_MS 同属内部策略常量，不走 Config：回拨量由「gcHours − 退避」\n// 决定，退避单开成字段就能配出「退避长于周期」（gcLastAt 落到未来、永不重试）\n// 这类无意义组合；同类先例见 scripts.posix.js 的 STALE_LOCK_MIN、snapshots.js\n// 的 FUSE_AFTER（合规清单 #3 的豁免面）。\nconst GC_RETRY_BACKOFF_MS = 1800000\n\n// 单次 gc 超时（毫秒）：GB 级 loose 对象库 repack 可超 10 分钟，被杀的 gc\n// 永远完不成；30 分钟给大库足够余量。gc 与快照同在串行队列，只影响维护节奏。\n// 此处是把原先内联的 timeoutMs: 600000 具名化，不是新增可调参数；不走 Config\n// 的定性同 GC_RETRY_BACKOFF_MS——要改 gc 节奏的用户改 gcHours 即可，超时是被\n// 动兜底而非节流旋钮。\nconst GC_TIMEOUT_MS = 1800000\n\nimport type { Runtime, StoreInfo, SnapshotInfo } from '../types/state.js'\nimport type { HostContext, SessionQueryEngine } from '../types/dsh-contract.js'\nimport type { ResolvedConfig } from '../types/config.js'\nimport type { SnapshotsApi } from './snapshots.js'\nimport type { StoreDumpInfo } from './dump-parse.js'\n\n// P1-3 纯逻辑：按 root 分组选出超限部分的最旧快照（time 升序，time=0 孤儿\n// 最旧优先），模块级导出供 tests/unit 直接钉边界；工厂内 enforceLimits 复用。\nexport interface SnapshotLite {\n  id: string\n  time: number\n}\nexport function selectOverLimitVictims(snapshots: Map<string, SnapshotInfo>, limit: number): Map<string, SnapshotLite[]> {\n  if (!limit || limit <= 0) return new Map() // 0 或负值 = 不限制\n  const byRoot = new Map<string, SnapshotLite[]>()\n  for (const [id, s] of snapshots.entries()) {\n    if (!s || !s.root) continue\n    // get-or-create 守卫（A6）：替代原 `get(...)!` 非空断言——断言靠的是\n    // 上一行的 has/set，类型层不可见；显式分支让两条路径都自证非空。\n    const list = byRoot.get(s.root)\n    if (list) list.push({ id, time: s.time })\n    else byRoot.set(s.root, [{ id, time: s.time }])\n  }\n  const victims = new Map<string, SnapshotLite[]>()\n  for (const [root, list] of byRoot) {\n    if (list.length <= limit) continue\n    const excess = list.length - limit\n    // 按时间升序排：time=0 最旧，优先清；同时间保插入序（先入先出）\n    list.sort((a, b) => (a.time || 0) - (b.time || 0))\n    victims.set(root, list.slice(0, excess))\n  }\n  return victims\n}\n\n// S2-3 按时间保留的纯逻辑：retentionDays <= 0 不启用；按 root 分组，\n// 命中「time > 0 且早于 cutoff」的入选（time=0 孤儿视为最旧，一并最先\n// 清——与 selectOverLimitVictims 同构）。模块级导出供单测钉边界。\nexport function selectExpiredVictims(snapshots: Map<string, SnapshotInfo>, retentionDays: number, now: number): Map<string, SnapshotLite[]> {\n  if (!retentionDays || retentionDays <= 0) return new Map()\n  const cutoff = (typeof now === 'number' ? now : Date.now()) - retentionDays * 86400000\n  const byRoot = new Map<string, SnapshotLite[]>()\n  for (const [id, s] of snapshots.entries()) {\n    if (!s || !s.root) continue\n    // time=0 孤儿（rebuildOrphans 重建）无真实时间，视为最旧列入\n    if (s.time > 0 && s.time >= cutoff) continue\n    if (!byRoot.has(s.root)) byRoot.set(s.root, [])\n    byRoot.get(s.root)!.push({ id, time: s.time })\n  }\n  return byRoot\n}\n\nexport interface MaintenanceApi {\n  maybeMaintain(sessionId: string): Promise<void>\n  runGc(sessionId: string, force: boolean): Promise<boolean>\n  runGcAll(): Promise<boolean>\n  enforceLimits(): Promise<number>\n  enforceRetention(): Promise<number>\n  sweepDeletedSessions(): Promise<void>\n}\n\n// M3（issue #18 收尾）：磁盘 store 全集的来源。index.ts 的 dumpStores 一条\n// shell 出「容器子目录 + 降级候选目录」的 root.txt/index.json；缺省（单测、\n// 无容器）时退化为「只用内存缓存」，磁盘覆盖与空仓回收都不生效——保持旧行为。\nexport interface MaintenanceDeps {\n  dumpStores?: () => Promise<Map<string, StoreDumpInfo>>\n}\n\nexport function createMaintenance(ctx: HostContext, rt: Runtime, snaps: SnapshotsApi, config: ResolvedConfig, deps: MaintenanceDeps = {}): MaintenanceApi {\n  const sessions = ctx.sessions\n  const state = rt.state\n  // 平台选择的脚本模板（gc/purge 两套模板同名导出）\n  const S = rt.scripts\n\n  // 删除一个会话的全部快照：按 root 分组（同一会话可能换过工作目录），\n  // tag 分块删除规避命令行长度上限，索引重写交给 snaps.saveIndex。\n  // best-effort：单块失败只记日志，剩余块继续；tag 残留由下次清理幂等收尾。\n  async function purgeSession(sessionId: string): Promise<number> {\n    const byRoot = new Map<string, string[]>()\n    for (const [id, s] of state.snapshots.entries()) {\n      if (!s || s.sessionId !== sessionId) continue\n      // get-or-create 守卫（A6）：替代 `get(...)!` 断言，两条路径各自自证非空\n      const list = byRoot.get(s.root)\n      if (list) list.push(id)\n      else byRoot.set(s.root, [id])\n    }\n    let purged = 0\n    for (const [root, ids] of byRoot) {\n      let store: StoreInfo | null = state.stores.get(root) || null\n      if (!store) {\n        // 冷启动时 store 缓存可能还没建：现场解析一次而不是直接跳过——\n        // 跳过会让该 root 的快照永远清不掉（sweep 每轮都 miss）\n        try { store = await rt.resolveStore(root) } catch (error) { store = null }\n      }\n      if (!store || !state.gitExe) continue\n      // A3：格式守卫——拒写态下不删 tag（tag 删了而索引写被拒会留下失配状态；\n      // 告警由 guard 侧节流 recordError，不中断宿主）\n      if (!(await snaps.guardStoreFormat(store))) continue\n      try {\n        for (let i = 0; i < ids.length; i += 100) {\n          await rt.runShell(S.purgeTagsScript(store, state.gitExe, ids.slice(i, i + 100).map((id) => 'snap-' + id)), { timeoutMs: 120000, stdoutMaxBytes: 4096 })\n        }\n        for (const id of ids) state.snapshots.delete(id)\n        await snaps.saveIndex(root, sessionId)\n        purged += ids.length\n      } catch (error) {\n        // 已告警；单个会话清理失败不阻断其余（purged 照常累计已成功的）\n        rt.recordError('recall purge session failed: ' + String(error))\n      }\n    }\n    if (purged > 0) console.error('recall purged snapshots of deleted session:', sessionId, purged)\n    return purged\n  }\n\n  // 扫描索引里出现过的全部会话：不在 sessions 注册表、也不在磁盘会话目录\n  // 里的，才认定「已删除」。\n  // PF-7：一次 listSessions 建 id 集合替代逐会话 readSession 冷读——后者\n  // 对每个非 live 会话解压全量日志且跑在串行队列里，会话多的老工作区 gc\n  // 一到就把后续快照/撤回全堵在队尾；listSessions 是「目录级 header 枚举、\n  // 不触碰全量日志」（I8：记录 id 在 header.id），一次调用即得全部磁盘\n  // 会话 id 集。判定语义与旧「readSession 成败」等价且更保守：归档会话\n  // 日志仍在磁盘（集合中保留，不被误清——旧路径同样靠这一点）、日志损坏\n  // 但文件在的也保留（purge 不可逆，宁可少清）。\n  // 保守闸门保持：sessionQuery 服务（或 listSessions）不存在、枚举抛异常\n  // 时整体跳过——无法枚举就无法区分「已删除」和「只是冷着」，误删快照\n  // 不可逆，宁可不清理。\n  // titles 半项（PF-7 原案）：探针（tests/probe/api-surface.test.js）确认\n  // SessionHeader 无 title 字段（标题住在事件日志里）→ 冷标题无法走\n  // listSessions，titles 冷读维持 readSession 现状。\n  async function sweepDeletedSessions(): Promise<void> {\n    const ids = new Set<string>()\n    for (const s of state.snapshots.values()) {\n      if (s && s.sessionId) ids.add(s.sessionId)\n    }\n    if (!ids.size) return\n    const query = ctx.get<SessionQueryEngine>('sessionQuery')\n    if (!query || typeof query.listSessions !== 'function') return\n    let diskIds: Set<string>\n    try {\n      diskIds = new Set(((await query.listSessions()) || [])\n        .map((r) => r && r.header && r.header.id)\n        .filter((v): v is string => Boolean(v)))\n    } catch (error) {\n      // 枚举失败整体跳过（宁可不清理，论证见上方注释）\n      return\n    }\n    for (const id of ids) {\n      if (sessions.get(id)) continue\n      if (diskIds.has(id)) continue\n      await purgeSession(id)\n    }\n  }\n\n  // 存储总量上限（P1-3）：按 root 分组统计，超限按 time 升序删最旧。\n  // 调用点（runGc/runGcAll）都在串行队列里，与快照互斥，无 git 锁竞态。\n  // 删除前 console.error 留痕（静默删历史撤回点必须可追溯，与 purgeSession\n  // 同款）；删除后重写索引。time=0 的孤儿条目（rebuildOrphans 重建）视为\n  // 最旧优先清理——它们没有真实时间，先于有时间的快照被清。\n  // 分组与选中逻辑在模块级 selectOverLimitVictims（单测直接钉边界）。\n  async function enforceLimits() {\n    const victimsMap = selectOverLimitVictims(state.snapshots, config.maxSnapshotsPerWorkspace)\n    if (!victimsMap.size) return 0\n    let dropped = 0\n    for (const [root, victims] of victimsMap) {\n      let store: StoreInfo | null = state.stores.get(root) || null\n      if (!store) {\n        // 现场解析失败按无 store 跳过该 root（与 sweepDeletedSessions 同款理由）\n        try { store = await rt.resolveStore(root) } catch (error) { store = null }\n      }\n      if (!store || !state.gitExe) continue\n      // A3：格式守卫——拒写态下不删 tag（同 purgeSession 的理由）\n      if (!(await snaps.guardStoreFormat(store))) continue\n      try {\n        for (let i = 0; i < victims.length; i += 100) {\n          await rt.runShell(S.purgeTagsScript(store, state.gitExe, victims.slice(i, i + 100).map((v) => 'snap-' + v.id)), { timeoutMs: 120000, stdoutMaxBytes: 4096 })\n        }\n        for (const v of victims) state.snapshots.delete(v.id)\n        await snaps.saveIndex(root, null)\n        dropped += victims.length\n        console.error('recall enforceLimits dropped ' + victims.length + ' oldest snapshots for: ' + root + ' (max ' + config.maxSnapshotsPerWorkspace + ')')\n      } catch (error) {\n        // 已告警；单 root 失败继续下一个\n        rt.recordError('recall enforceLimits failed for ' + root + ': ' + String(error))\n      }\n    }\n    return dropped\n  }\n\n  // 按时间保留（S2-3）：对每个 root 清掉早于保留窗口的快照。结构与\n  // enforceLimits 同款（tag 分块删除 + saveIndex + 留痕），与条数上限\n  // 各自独立触发，在同一轮 gc 周期里先后执行。时间维度的删除同样\n  // 静默丢历史撤回点，故 console.error 留痕与 enforceLimits 一致。\n  async function enforceRetention(): Promise<number> {\n    const victimsMap = selectExpiredVictims(state.snapshots, config.retentionDays, Date.now())\n    if (!victimsMap.size) return 0\n    let dropped = 0\n    for (const [root, victims] of victimsMap) {\n      let store: StoreInfo | null = state.stores.get(root) || null\n      if (!store) {\n        // 现场解析失败按无 store 跳过该 root（与 enforceLimits 同款理由）\n        try { store = await rt.resolveStore(root) } catch (error) { store = null }\n      }\n      if (!store || !state.gitExe) continue\n      // A3：格式守卫——拒写态下不删 tag（同 purgeSession 的理由）\n      if (!(await snaps.guardStoreFormat(store))) continue\n      try {\n        for (let i = 0; i < victims.length; i += 100) {\n          await rt.runShell(S.purgeTagsScript(store, state.gitExe, victims.slice(i, i + 100).map((v) => 'snap-' + v.id)), { timeoutMs: 120000, stdoutMaxBytes: 4096 })\n        }\n        for (const v of victims) state.snapshots.delete(v.id)\n        await snaps.saveIndex(root, null)\n        dropped += victims.length\n        console.error('recall enforceRetention dropped ' + victims.length + ' expired snapshots for: ' + root + ' (retention ' + config.retentionDays + 'd)')\n      } catch (error) {\n        // 已告警；单 root 失败继续下一个\n        rt.recordError('recall enforceRetention failed for ' + root + ': ' + String(error))\n      }\n    }\n    return dropped\n  }\n\n  // 维护核心（节流判定 + 清理 + gc）：force 供设置页「立即 gc」手动触发，\n  // 跳过阈值检查但仍走同一条串行队列调用方——与快照天然互斥的约束不变。\n  // 失败不推进完整 gcHours 周期：只回拨到退避窗口后重试（GC_RETRY_BACKOFF_MS），\n  // 避免「失败→整天不重试→对象继续堆积→下次更易失败」的滚雪球；也不清空\n  // 时间戳——那会让后续每条消息都重试一次重量级 gc，把队列堵住。\n  async function runGc(sessionId: string, force: boolean): Promise<boolean> {\n    const root = await rt.resolveRoot(sessionId)\n    if (!root) return false\n    const store = state.stores.get(root)\n    if (!store || !state.gitExe) return false\n    const now = Date.now()\n    const last = state.gcLastAt.get(store.git) || 0\n    const count = (state.gcCount.get(store.git) || 0) + 1\n    state.gcCount.set(store.git, count)\n    if (!force && count < config.gcSnaps && now - last < config.gcHours * 3600000) return false\n    state.gcCount.set(store.git, 0)\n    let ok = false\n    try {\n      await sweepDeletedSessions()\n      // P1-3：总量上限清理（sweep 之后、gc 之前）——与快照在同一条串行\n      // 队列里，删除 tag 与 gc 互斥，无 git 锁竞态；best-effort，\n      // 自身失败不进 catch 的主错误路径（enforceLimits 内部已兜）。\n      await enforceLimits()\n      // S2-3：按时间保留清理（与条数上限维度各自独立，同条串行队列）\n      await enforceRetention()\n      await rt.runShell(S.gcScript(store, state.gitExe), { timeoutMs: GC_TIMEOUT_MS, stdoutMaxBytes: 4096 })\n      ok = true\n    } catch (error) {\n      // 已告警；失败不推进完整周期、按退避回拨（理由见函数头注释）\n      rt.recordError('recall maintenance failed: ' + String(error))\n    }\n    state.gcLastAt.set(store.git, ok ? Date.now() : Date.now() - config.gcHours * 3600000 + GC_RETRY_BACKOFF_MS)\n    return true\n  }\n\n  // 磁盘 store 全集（M3-1）：内存缓存只覆盖「启动预热与历次操作认识过」的\n  // 工作区；会话已删、或从未在本进程 init 过的仓库在磁盘上有、内存里没有——\n  // 它们恰好是 issue #18 的 GB 级残骸（refs 空 + index 伪可达），此前\n  // runGcAll 对它们完全无感。dump 失败按空处理并记错误（与 dumpStores 既有\n  // 语义一致：枚举失败不等于「没有数据」，但维护是 best-effort）。\n  async function dumpDiskStores(): Promise<Map<string, StoreDumpInfo>> {\n    if (typeof deps.dumpStores !== 'function') return new Map()\n    try {\n      return await deps.dumpStores()\n    } catch (error) {\n      // 已告警；枚举失败按空 Map 继续（维护 best-effort，见函数头注释）\n      rt.recordError('recall disk store dump failed: ' + String(error))\n      return new Map()\n    }\n  }\n\n  // 内存 + 磁盘并集，按 store.git 去重（同一仓库两来源的 git-dir 必然一致）\n  function mergeStores(disk: Map<string, StoreDumpInfo>): StoreInfo[] {\n    const byGit = new Map<string, StoreInfo>()\n    for (const store of state.stores.values()) {\n      if (store && store.git) byGit.set(store.git, store)\n    }\n    for (const dir of disk.keys()) {\n      if (!dir) continue\n      const store = rt.storeFromDir(dir, false)\n      if (store && store.git && !byGit.has(store.git)) byGit.set(store.git, store)\n    }\n    return Array.from(byGit.values())\n  }\n\n  // 该 store 目录是否还挂着内存快照：防「磁盘索引丢了/被隔离，内存却有条目」\n  // 这种极端组合被误删（root.txt 的 root 是权威映射，内存 stores 的表是补充）\n  function memorySnapshotCount(dir: string, root: string | null): number {\n    let n = 0\n    for (const snap of state.snapshots.values()) {\n      if (!snap) continue\n      const owner = state.stores.get(snap.root)\n      if ((owner && owner.dir === dir) || (root && snap.root === root)) n++\n    }\n    return n\n  }\n\n  // M3-2：整目录回收——M1 只清对象库（目录与 root.txt 还在），这一步把「确认\n  // 没有任何可回退数据」的空仓库目录整个删掉（issue #18 报告者手工做的那步）。\n  // 逐条保守判定，任一条不满足就留着：\n  //   * 「没有可回退数据」＝ 索引明确为空数组（拍过快照、后来删光了）**或**\n  //     indexState 为 absent（建过仓但从没拍过快照——issue #30 遗留的空壳）。\n  //     其余一律不删：present/quarantined 的 entries=null 是损坏/隔离现场（待\n  //     复查），unknown 是旧版脚本的输出（看不出形态），foreign 不是我们的目录；\n  //   * 任何 snap-* tag 存在即代表有可回退快照，不删（以磁盘真值二次确认）；\n  //   * 内存里还有该目录/该 root 的快照，不删。\n  // 删前留 console.error（不可逆操作必须可追溯，同 purgeSession 的纪律）；\n  // best-effort，单条失败只记错误继续。调用点在逐 store gc **之后**：先让 M1\n  // 的条件清理把那批伪可达对象回收掉，再删空壳，避免「刚删目录、gc 又对着它跑」。\n  async function reapEmptyStores(disk: Map<string, StoreDumpInfo>): Promise<number> {\n    if (!state.gitExe) return 0\n    let removed = 0\n    for (const [dir, info] of disk) {\n      if (!dir || !info) continue\n      const emptyIndex = Array.isArray(info.entries) && info.entries.length === 0\n      const neverCaptured = info.entries === null && info.indexState === 'absent'\n      if (!emptyIndex && !neverCaptured) continue\n      if (memorySnapshotCount(dir, info.root) > 0) continue\n      const store = rt.storeFromDir(dir, false)\n      try {\n        const tags = S.stripBom(await rt.runShell(S.listTagsScript(store, state.gitExe), { timeoutMs: 60000, stdoutMaxBytes: 4096 }))\n        if (String(tags).trim()) continue\n        await rt.runShell(S.legacyRmScript(dir), { timeoutMs: 120000, stdoutMaxBytes: 4096 })\n        // 内存侧同步摘除：后续操作不该再对着已删目录跑\n        for (const [root, st] of state.stores.entries()) {\n          if (st && st.dir === dir) state.stores.delete(root)\n        }\n        state.gcLastAt.delete(store.git)\n        state.gcCount.delete(store.git)\n        if (info.root) state.indexLoaded.delete(info.root)\n        console.error('recall reaped empty store:', dir)\n        removed++\n      } catch (error) {\n        // 已告警；单条目录失败继续下一条（best-effort，见函数头注释）\n        rt.recordError('recall reap store failed for ' + dir + ': ' + String(error))\n      }\n    }\n    return removed\n  }\n\n  // 全局 gc（设置卡片没有会话上下文）：清理扫描一次 + 逐 store gc（内存 ∪ 磁盘）\n  // + 空仓目录回收。逐个 best-effort，单个失败记错误继续。调用方（manage 端点）\n  // 把它排进同一条串行队列，与快照天然互斥，无 git 锁竞态。\n  async function runGcAll(): Promise<boolean> {\n    if (!state.gitExe) return false\n    const disk = await dumpDiskStores()\n    const stores = mergeStores(disk)\n    if (!stores.length) return false\n    try {\n      await sweepDeletedSessions()\n    } catch (error) {\n      // 已告警；清扫失败不阻断后续步骤（逐个 best-effort，见函数头注释）\n      rt.recordError('recall sweep failed: ' + String(error))\n    }\n    try {\n      // P1-3：全局清理一次（runGcAll 无会话上下文，enforceLimits 自身按\n      // root 遍历内存快照，天然覆盖全部已知工作区）\n      await enforceLimits()\n    } catch (error) {\n      // 已告警；该步失败不阻断后续步骤（逐个 best-effort）\n      rt.recordError('recall enforceLimits failed: ' + String(error))\n    }\n    try {\n      // S2-3：按时间保留全局清理一次\n      await enforceRetention()\n    } catch (error) {\n      // 已告警；该步失败不阻断后续步骤（逐个 best-effort）\n      rt.recordError('recall enforceRetention failed: ' + String(error))\n    }\n    let done = 0\n    for (const store of stores) {\n      try {\n        await rt.runShell(S.gcScript(store, state.gitExe), { timeoutMs: GC_TIMEOUT_MS, stdoutMaxBytes: 4096 })\n        done++\n        state.gcLastAt.set(store.git, Date.now())\n      } catch (error) {\n        // 已告警；失败按退避回拨重试窗口（与 runGc 同款），循环继续下一个 store\n        rt.recordError('recall gc failed for ' + (store && store.git) + ': ' + String(error))\n        state.gcLastAt.set(store.git, Date.now() - config.gcHours * 3600000 + GC_RETRY_BACKOFF_MS)\n      }\n      state.gcCount.set(store.git, 0)\n    }\n    await reapEmptyStores(disk)\n    return true\n  }\n\n  // 每条消息快照后串行调用（见 index.js 事件接线）\n  async function maybeMaintain(sessionId: string): Promise<void> {\n    await runGc(sessionId, false)\n  }\n\n  // 模块收敛：runGc/runGcAll 之外的内部步骤不对外暴露面；enforceLimits /\n  // sweepDeletedSessions 保留导出供单测以工厂形态驱动（注入假 rt/ctx 钉\n  // 执行链路；PF-7 sweep 判定矩阵依赖导出）。\n  return { maybeMaintain, runGc, runGcAll, enforceLimits, enforceRetention, sweepDeletedSessions }\n}\n"
    },
    {
      "path": "src/host/queues.ts",
      "content": "/**\n * dsh-recall-plugin — 按工作区隔离的任务队列（工厂，无模块级状态）\n *\n * 为什么按 root 分链：一条消息的快照可能要跑几十秒（大工作区首拍，或慢盘），\n * 此前全局单链会让**所有会话**的新快照排在它后面——别的项目连撤回按钮都\n * 出不来。同一 root 必须串行（快照/preview/回滚/删除都在写同一个 git index，\n * 并发就是 index.lock 竞态）；不同 root 之间没有共享写面，天然可以并行。\n *\n * key 归一：win32 路径大小写不敏感，同一仓库不能因 root 写法不同拿到两把锁；\n * POSIX 保持原样（大小写敏感）。\n */\n\nexport interface QueuesApi {\n  enqueueFor<T>(root: string | null | undefined, task: () => Promise<T>): Promise<T>\n  enqueueMany<T>(roots: Array<string | null | undefined>, task: () => Promise<T>): Promise<T>\n}\n\nexport function createQueues(isWin: boolean): QueuesApi {\n  // key -> 该链的尾部。尾部恒为 catch 过的 promise：一次失败不能让整条链\n  // 停在拒绝状态，后续任务只依赖排队关系、不依赖前一个任务的结果。\n  const tails = new Map<string, Promise<void>>()\n\n  const keyOf = (root: string | null | undefined): string => {\n    const k = String(root == null ? '' : root)\n    return k !== '' && isWin ? k.toLowerCase() : k\n  }\n\n  function tailFor(key: string): Promise<void> {\n    return tails.get(key) || Promise.resolve()\n  }\n\n  function enqueueFor<T>(root: string | null | undefined, task: () => Promise<T>): Promise<T> {\n    const key = keyOf(root)\n    const run = tailFor(key).then(task)\n    tails.set(key, run.catch(() => {}) as Promise<void>)\n    return run\n  }\n\n  // 跨工作区操作（全量删除 / 全局 gc）：等这些 root 的链尾全部落地再执行，\n  // 并把同一条链尾写回每个 key——与 per-root 任务互斥，又不阻塞无关 root。\n  // 空集合退化为单条全局链（'' key），对应「没有 root 可用」的场景。\n  function enqueueMany<T>(roots: Array<string | null | undefined>, task: () => Promise<T>): Promise<T> {\n    const keys = Array.from(new Set(roots.map(keyOf)))\n    if (keys.length === 0) keys.push('')\n    const run = Promise.all(keys.map(tailFor)).then(task)\n    const tail = run.catch(() => {}) as Promise<void>\n    for (const key of keys) tails.set(key, tail)\n    return run\n  }\n\n  return { enqueueFor, enqueueMany }\n}\n"
    },
    {
      "path": "src/host/routes-core.ts",
      "content": "/**\n * dsh-recall-plugin — 核心路由域（R2 从 index.js 拆出）\n *\n * init / snapshot-info / preview / execute / status / lineage-record 六个核心\n * 端点。依赖经 deps 注入（rt/snaps/state/cfg/enqueue/agentBusy/rescueRollback\n * 等），无模块级可变状态（HMR 假设）。preview/execute 内部跑 git add -A，\n * 经 enqueue 排进与快照/gc 同一条串行队列，避免 index.lock 竞态。\n */\n\nimport { ENV_HINTS } from './diagnostics.js'\nimport { parseTreeId } from './snapshots.js'\nimport { buildArtifactRootSegment, buildRootNotice } from './exclude-patterns.js'\nimport type { Runtime, SharedState, ErrorRecord, StoreInfo } from '../types/state.js'\nimport type { ResolvedConfig } from '../types/config.js'\nimport type { SnapshotsApi } from './snapshots.js'\n            import type { IntentJournal } from './intent-journal.js'\nimport type { EnvErrorKind } from './diagnostics.js'\nimport type { InitArgs, InitResponse, InitNotice, SnapshotInfoArgs, SnapshotInfoResponse, PreviewArgs, PreviewResponse, ExecuteArgs, ExecuteResponse, RecallScope, StatusArgs, StatusResponse, LineageRecordArgs, LineageRecordResponse, RecallNotifyArgs, RecallNotifyResponse, ErrBody } from '../types/api.js'\nimport type { RecallCompleteEvent, RecallFailedEvent } from '../types/events.js'\n\n// 撤回终态事件名（issue #19）：事件契约唯一事实源是 src/types/events.ts，\n// 但 build-host 逐文件转译只覆盖 src/host/（types/ 不落 lib/），host 产物\n// 运行时 import 它会 MODULE_NOT_FOUND——事件名在此按字面量声明、类型注解\n// 钉死，与契约文件的绑定由 tests/types/events-contract.test.ts 编译期双向\n// 赋值断言（漂移即 typecheck 红）。client 侧 bundle 打包不受此限，正常 import。\nexport const RECALL_EVENT_COMPLETE_HOST: 'dsh-recall/complete' = 'dsh-recall/complete'\nexport const RECALL_EVENT_FAILED_HOST: 'dsh-recall/failed' = 'dsh-recall/failed'\n\n// 端点依赖注入面（index.ts 装配时逐项提供；ctx 不解构的 A4 纪律见工厂注释）\nexport interface RoutesCoreDeps {\n  rt: Runtime\n  snaps: SnapshotsApi\n  // A2 操作意图 journal（init 端点是 recover 的第二挂载点；execute 三针写记录）\n  intentJournal: IntentJournal\n  state: SharedState\n  cfg: ResolvedConfig\n  supported: boolean\n  // 按工作区隔离的任务队列（queues.ts）：同 root 串行、跨 root 并行\n  enqueueFor<T>(root: string | null | undefined, task: () => Promise<T>): Promise<T>\n  enqueueMany<T>(roots: Array<string | null | undefined>, task: () => Promise<T>): Promise<T>\n  // issue #24：根就绪链（resolveStore/ensureGit/loadIndex/rebuild/recover）\n  // 与启动预热共享，in-flight 去重——每个恢复的会话各跑一遍会叠出数十条\n  // pwsh 并发。返回解析出的 store 供 init 计算降级 notice。\n  ensureRootReady(root: string, sessionId: string | null): Promise<StoreInfo | null>\n  agentBusy(sessionId: string | null, root: string | null): boolean\n  rescueRollback: typeof import('./snapshots.js').rescueRollback\n  E: typeof import('./errors.js')\n  // issue #19：撤回终态事件广播（index.ts 注入 (event, payload) => ctx.emit(event, payload)）。\n  // 经 deps 注入而非本域直接摸 ctx：工厂分层纪律（本域不持有 ctx）+ 单测可注入桩\n  emitEvent(event: string, payload: unknown): void\n}\n\nexport function createRoutesCore(deps: RoutesCoreDeps) {\n  // ctx 不解构（A4）：本域所有服务访问都已由 rt/snaps 封装，直接摸 ctx 会\n  // 绕过工厂分层——留空位只会诱导未来代码破坏依赖注入约定\n  const { rt, snaps, state, cfg, supported, enqueueFor, agentBusy, rescueRollback, intentJournal, ensureRootReady, emitEvent, E } = deps\n\n  return {\n    'init': async (args: InitArgs): Promise<InitResponse> => {\n      if (!supported) {\n        return { ok: false, root: null, notice: { unsupported: true } }\n      }\n      const sessionId = args && args.sessionId ? String(args.sessionId) : null\n      const root = await rt.resolveRoot(sessionId)\n      let notice: InitNotice | null = null\n      if (root) {\n        // issue #24：与启动预热共享同一条根就绪链（in-flight 去重）——同一\n        // root 在本进程内只跑一次 resolveStore/ensureGit/loadIndex/rebuild/\n        // recover。失败原样上抛（端点兜底转错误响应），与改造前语义一致。\n        const store = await ensureRootReady(root, sessionId)\n        // 降级状态随 init 下发，Client 弹一次性提示（每次页面加载各弹一次）：\n        // gitMissing=未检测到 git CLI（撤回按钮不出现）；homeFallback=home\n        // 不可写，快照降级存进项目内 .dsh-recall-snapshots。\n        notice = {\n          gitMissing: state.gitExe === '',\n          homeFallback: store ? !store.home : false\n        }\n        // issue #18：root 自身是构建产物目录时快照被停用（captureSnapshot 早退），\n        // 会话级说明一次——否则用户只会看到「撤回按钮不出现」而无从判断原因。\n        // A4：段名（artifactSeg）与拼好的中文文案（buildRootNotice）一并下发——\n        // client 优先按段名本地取词，中文字段保留一个版本周期\n        const artifactSeg = buildArtifactRootSegment(root, cfg.baseExcludes, rt.isWin)\n        if (artifactSeg) {\n          notice.buildRootArtifactSeg = artifactSeg\n          notice.buildRootNotice = buildRootNotice(artifactSeg)\n        }\n      }\n      // 顺带下发客户端行为开关（fillDraft 等）：Client 无须为读配置单开请求，\n      // init 是每会话必经的预热通道；A4 追加 locale（界面语言偏好）\n      return { ok: Boolean(root), root: root || null, notice, config: { refillDraft: cfg.refillDraft, archiveOriginal: cfg.archiveOriginal, editSubmitsImmediately: cfg.editSubmitsImmediately, locale: cfg.locale } }\n    },\n\n    'snapshot-info': async (args: SnapshotInfoArgs): Promise<SnapshotInfoResponse> => {\n      const id = args && args.messageId ? String(args.messageId) : ''\n      const snap = state.snapshots.get(id)\n      // 失败/跳过/熔断反馈（issue #7 失败可见性）：客户端轮询到 failed 即\n      // 终止轮询并 toast，不再空等 20 次；has 时附带 skipped 让用户知道\n      // fail-open 跳过了哪些路径\n      const feedback = await snaps.feedbackFor(args ? args.sessionId : null, id)\n      // issue #18：构建产物工作区根不会有快照（captureSnapshot 早退），客户端轮询\n      // 到 has:false 且无 failed 会静默放弃——补一条说明性 notice 让「按钮不出现」\n      // 有原因可查。root 解析走 state.roots 缓存，重复轮询不额外付费用。\n      const sroot = await rt.resolveRoot(args && args.sessionId ? String(args.sessionId) : null)\n      const artifactSeg = sroot ? buildArtifactRootSegment(sroot, cfg.baseExcludes, rt.isWin) : null\n      return {\n        has: Boolean(snap), time: snap ? snap.time : null, id, ...feedback,\n        // issue #31：按钮照常出现，但界面要知道这条没有文件树（隐藏范围单选）\n        files: snap ? snap.files !== false : undefined,\n        // A4：段名与中文 notice 并存下发（client 优先段名本地取词，见 init 同处注释）\n        notice: artifactSeg ? buildRootNotice(artifactSeg) : undefined,\n        artifactSeg: artifactSeg || undefined\n      }\n    },\n\n    'preview': async (args: PreviewArgs): Promise<PreviewResponse> => {\n      const id = args && args.messageId ? String(args.messageId) : ''\n      const sessionId = args && args.sessionId ? String(args.sessionId) : null\n      // P0-1：目标工作区 agent 运行中直接拒绝预览（避免用户确认时文件被\n      // agent 改动，预览清单与实际回退内容脱节）。同会话优先命中（最常见\n      // 场景），快照存在时叠加跨会话同工作区检查。\n      const snap = state.snapshots.get(id)\n      if (agentBusy(sessionId, snap ? snap.root : null)) return { ok: false, code: E.RECALL_AGENT_BUSY, message: 'Agent 正在运行中，请先停止后再撤回' }\n      // 只锁该快照所属工作区：别的项目的预览/快照不该排在同一个队列后面\n      const result = await enqueueFor(snap ? snap.root : null, () => snaps.diffFor(id))\n      if (result === null) return { ok: false, code: E.RECALL_NO_SNAPSHOT, message: '该消息没有可用的项目快照' }\n      const snap2 = state.snapshots.get(id)\n      const cutSeq = await snaps.resolveCutSeq(sessionId, id)\n      // PF-1：treeId 是 preview 时 add -A 后的 index 树指纹，Client 确认时\n      // 透传回 execute——Host 与安全快照指纹比对即可判定「预览后文件是否\n      // 变化」，省掉 execute 侧整条重复 diff。旧版 Client 不认识该字段，\n      // 无值时 execute 退回 previewTotal 校验（向后兼容）。\n      return { ok: true, changes: result.changes, total: result.total, truncated: result.truncated, treeId: result.treeId || null, time: snap2 ? snap2.time : null, root: snap2 ? snap2.root : null, cutSeq, counts: result.counts, files: snap2 ? snap2.files !== false : undefined }\n    },\n\n    'execute': async (args: ExecuteArgs): Promise<ExecuteResponse> => {\n      const id = args && args.messageId ? String(args.messageId) : ''\n      const sessionId = args && args.sessionId ? String(args.sessionId) : null\n      // scope 解析：缺省/非法值一律回落 both——老 Client 不发、直调 API 乱发都\n      // 落回现状链路；issue #31 的仅消息条目（files:false）另强制 session-only，\n      // 因为放行 both 会去打安全快照并 rollback 一个不存在的 tag，必然失败。\n      // session-only 走独立短路径：不进串行队列（队列是为 git 锁互斥而设，\n      // 本路径零 git 写操作，入队只添延迟）、跳过 STALE 校验/安全快照/\n      // rollbackFor/rescue 全链——无文件覆盖即无不可逆操作，无需救援锚点。\n      // 保留 NO_SNAPSHOT（快照存在性仍是消息归属的判定依据，且防御直调 API）\n      // 与 agentBusy 拦截（fork + 归档会把运行中的 agent 留在被归档的原会话里\n      // 继续写日志）；检查在队列外进行：无文件变更，P0-1「检查后紧接执行、\n      // 窗口为零」的动机不成立，检查退化为护栏而非不变量。\n      const entry = state.snapshots.get(id)\n      const scope: RecallScope = (args && args.scope === 'session-only') || (entry !== undefined && entry.files === false)\n        ? 'session-only'\n        : 'both'\n      if (scope === 'session-only') {\n        const snap = entry\n        if (!snap) return { ok: false, code: E.RECALL_NO_SNAPSHOT, message: '该消息没有可用的项目快照' }\n        if (agentBusy(sessionId, snap.root)) return { ok: false, code: E.RECALL_AGENT_BUSY, message: 'Agent 正在运行中，请先停止后再撤回' }\n        const cutSeq = await snaps.resolveCutSeq(sessionId, id)\n        // fork 仍会把切点窗口内的入队事件 seed 进子会话（与模式无关），清理链\n        // 照常走（both 分支下方的注释有完整说明）\n        const staleQueueItemIds = await snaps.resolveStaleQueueItemIds(sessionId, cutSeq)\n        // count 语义 = 回退文件数：session-only 恒为 0（done 面板本就不展示 count）\n        return { ok: true, count: 0, cutSeq, staleQueueItemIds }\n      }\n      // 队列 key 取快照所属工作区（入队前先查一次，仅用于选锁；真正的判定\n      // 仍在队列内——入队期间快照可能被删除，那时照样返回 NO_SNAPSHOT）\n      const initialSnap = state.snapshots.get(id)\n      const result = await enqueueFor(initialSnap ? initialSnap.root : null, async (): Promise<{ ok: true; count: number } | ErrBody> => {\n        const snap = state.snapshots.get(id)\n        if (!snap) return { ok: false, code: E.RECALL_NO_SNAPSHOT, message: '该消息没有可用的项目快照' }\n        const store = state.stores.get(snap.root)\n        if (!store) return { ok: false, code: E.RECALL_NO_STORE, message: '快照存储不可用' }\n        // A3：格式守卫（fail-closed）——安全快照打 tag 与工作区 reset 都是写\n        // 操作，高版本/损坏 store 拒执行；预览/列表等读路径不受影响\n        if (!(await snaps.guardStoreFormat(store))) {\n          return { ok: false, code: E.RECALL_FORMAT_BLOCKED, message: '磁盘格式不受支持，已停止写入；详见「最近错误」' }\n        }\n        // P0-1：队列内第一步——执行前再查一次 agent 状态。检查放在互斥\n        // 队列内，检查后紧接执行，中间不可能插进别的操作，窗口为零。\n        if (agentBusy(sessionId, snap.root)) return { ok: false, code: E.RECALL_AGENT_BUSY, message: 'Agent 正在运行中，请先停止后再撤回' }\n        // P0-3 / PF-1：preview→execute 失效校验，两代并存——\n        // - 新版 Client 透传 previewTreeId（preview 时 add -A 后的 index 树\n        //   指纹）：与下方安全快照输出的指纹比对，内容级一致判定，且免掉\n        //   一整条重复 diff 进程（一次撤回 4 条重进程 → 3 条）。\n        // - 旧版 Client 只带 previewTotal：退回条目总数校验（多付一次 diff，\n        //   同数不同文件的边缘情形由安全快照兜底）。\n        // - 都不带（直调 API）：不校验，与 P0-3 同款可选语义。\n        const previewTreeId = args && typeof args.previewTreeId === 'string' && args.previewTreeId ? args.previewTreeId : null\n        if (!previewTreeId && args && typeof args.previewTotal === 'number') {\n          const fresh = await snaps.diffFor(id)\n          if (!fresh || fresh.total !== args.previewTotal) {\n            return { ok: false, code: E.RECALL_STALE, message: '预览后项目文件发生了变化，请重新预览确认' }\n          }\n        }\n        // 回退前自动打安全快照：回退覆盖工作区且不回写 index（旧的\n        // 「当前状态」从此无任何快照可找回），用消息 ID 打 tag 会与该消息\n        // 的既有快照碰撞，故用独立前缀的时间戳 tag——不进 index.json\n        // （列表不展示），但孤儿重建/手动 git tag 仍能找到它，误回退后\n        // 用户可让插件从该 tag 恢复，堵住唯一的不可逆操作缺口。\n        // 失败时 safetyOk 置 false：后续回退若也失败将无救援点（H1），\n        // 行为退化为现状（fail-loud），不更差。\n        // PF-1：安全快照输出的树指纹就是「执行时刻的工作区状态」——与\n        // previewTreeId 不一致 → STALE（此时安全快照已打下，isSafetySnapshotId\n        // 让它不进索引，反而是额外的救援点）。安全快照失败时无指纹可比对，\n        // 跳过指纹校验继续回退（不阻断主流程的既有语义）。\n        const safetyId = 'pre-rollback-' + Date.now()\n        let safetyOk = false\n        let safetyTreeId = null\n        try {\n          const out = await rt.runShell(rt.scripts.snapshotScript(snap.root, store, state.gitExe || '', safetyId, cfg.baseExcludes), { timeoutMs: 600000, stdoutMaxBytes: 65536 })\n          safetyOk = true\n          safetyTreeId = parseTreeId(out)\n        } catch (error) {\n          // 安全快照失败不阻断回退本身：用户已确认覆盖，记录后照原计划执行\n          rt.recordError('recall safety snapshot failed: ' + String(error))\n        }\n        if (previewTreeId && safetyTreeId && safetyTreeId !== previewTreeId) {\n          return { ok: false, code: E.RECALL_STALE, message: '预览后项目文件发生了变化，请重新预览确认' }\n        }\n        // A2 针 1：安全快照后、动磁盘前落意图（回退中途断电时启动/init 的\n        // recover 据此续做；写失败只告警不阻断主流程——U4 纪律）\n        await intentJournal.begin(store, snap.root, { messageId: id, safetyId, safetyOk })\n        const rolled = await snaps.rollbackFor(id)\n        if (rolled.ok) {\n          // A2 针 2：回退成功清记录（残留会被下次启动误判为中断，见 recover）\n          await intentJournal.clear(store)\n          return rolled\n        }\n        // A2 针 3：救援也会写工作区（reset 到安全快照），先推进 phase 再执行；\n        // rescue 后无论成败都 clear——失败虽留下现场，但手动命令逃生门已在\n        // 结果面板给出：留着记录会让下次启动的自动 reset 覆盖用户按手动命令\n        // 恢复后的新改动（记录内容由下方提示的路径可查）。\n        // 回退失败（rollbackFor 返回 partial，工作区可能半回退）：用安全快照\n        // 救援（H1）。rescueRollback 是 snapshots.js 模块级纯逻辑，副作用经\n        // deps 注入，三分支（无救援点/救援成功/救援失败）单测直接钉。\n        await intentJournal.advance(store, 'rescue')\n        const rescueResult = await rescueRollback(\n          { runShell: rt.runShell, scripts: rt.scripts, gitExe: state.gitExe || '', recordError: rt.recordError },\n          { root: snap.root, store, safetyId, safetyOk, rollbackError: rolled.error }\n        )\n        await intentJournal.clear(store)\n        // U4 留痕：提示附意图文件路径（中断点记录位置，用户可精确知道恢复\n        // 到了哪一步、现场在哪）\n        if (rescueResult && rescueResult.message) rescueResult.message += '（中断点记录：' + intentJournal.file(store) + '）'\n        return rescueResult\n      })\n      if (!result.ok) return result\n      // 文件回退后再解析切点：切点只依赖会话日志，与快照是否删除无关（命中缓存，瞬时）\n      const cutSeq = await snaps.resolveCutSeq(sessionId, id)\n      // 顺带解析 fork 会带进子会话的残留排队项 id（见 snapshots.ts\n      // scanStaleQueueItemIds 的窗口说明）：Client 在 fork 出子会话后按 id 直删，\n      // 否则输入框上方会凭空多出一条被撤回消息的「排队消息」。\n      const staleQueueItemIds = await snaps.resolveStaleQueueItemIds(sessionId, cutSeq)\n      return { ok: true, count: result.count, cutSeq, staleQueueItemIds }\n    },\n\n    // 设置页排障：最近错误（Host 侧 console.error 的页面可见副本）。\n    // M1-D3/D5：条目自带 count/kind（recordError 富集）——count 在服务端\n    // 拼成「（×N）」展示文本，设置页按 message 渲染即显示重复计数，零\n    // Client 改动；hint 是分类后的可行动提示（API 自描述，本次无客户端\n    // 消费，设置页未来展示零成本）。storeBase（M2-D3）暴露快照存储根，\n    // 供设置页未来展示「快照存在哪里」，失败为 null。\n    'status': async (args: StatusArgs): Promise<StatusResponse> => {\n      const storeBase = await rt.resolveHomeContainer()\n      if (args && args.op === 'clear') {\n        state.errors.length = 0\n        return { ok: true, errors: [], storeBase }\n      }\n      const errors = state.errors.slice(-20).reverse().map((e: ErrorRecord) => ({\n        ...e,\n        message: e.message + (e.count > 1 ? '（×' + e.count + '）' : ''),\n        hint: e.kind ? ENV_HINTS[e.kind] : null\n      }))\n      return { ok: true, errors, storeBase }\n    },\n\n    // F1：client fork 成功后上报撤回链（childId ↔ parentId），Host 持久化到\n    // lineage.json 供快照管理树聚族展示「版本家族」。root 优先按 fork 源\n    // parentId 解析（fork 时它仍是 live 会话；归档只隐藏列表、对象在内存），\n    // 失败回退 childId。\n    'lineage-record': async (args: LineageRecordArgs): Promise<LineageRecordResponse> => {\n      const childId = args && args.childId ? String(args.childId) : ''\n      const parentId = args && args.parentId ? String(args.parentId) : ''\n      if (!childId || !parentId) return { ok: false, code: E.RECALL_BAD_TYPE, message: '缺少会话 ID' }\n      const root = (await rt.resolveRoot(parentId)) || (await rt.resolveRoot(childId))\n      if (!root) return { ok: false, code: E.RECALL_NO_ROOT, message: '无法解析工作区' }\n      let store: StoreInfo | null = state.stores.get(root) || null\n      if (!store) {\n        // 现场解析失败按无 store：下行 NO_STORE 响应\n        try { store = await rt.resolveStore(root) } catch (error) { store = null }\n      }\n      if (!store) return { ok: false, code: E.RECALL_NO_STORE, message: '快照存储不可用' }\n      await snaps.recordLineage(root, childId, parentId)\n      return { ok: true }\n    },\n\n    // issue #19：client 撤回终态上报 → cordis 事件广播（dsh-recall/complete\n    // | dsh-recall/failed）。不进串行队列（零 git 操作）、不依赖 store——\n    // lineage-record 的 NO_STORE 早退在这里是缺陷（原会话已归档时解析不到\n    // store 会吞掉事件），端点只做 enrich 与转发。恒 { ok: true }：事件\n    // 发送失败不影响撤回主流程（client 侧 fire-and-forget，连响应都不等）。\n    'notify': async (args: RecallNotifyArgs): Promise<RecallNotifyResponse> => {\n      const status = args && args.status\n      const sessionId = args && args.sessionId ? String(args.sessionId) : ''\n      const messageId = args && args.messageId ? String(args.messageId) : ''\n      // 复用 BAD_TYPE 不加新错误码：非法上报是插件版本错位/直调 API 的\n      // 编程错误，新码只会膨胀 client 词典；client 对响应本就不消费\n      if ((status !== 'complete' && status !== 'failed') || !sessionId || !messageId) {\n        return { ok: false, code: E.RECALL_BAD_TYPE, message: '撤回上报缺少必要参数' }\n      }\n      const scope: RecallScope = args && args.scope === 'session-only' ? 'session-only' : 'both'\n      const cutSeq = args && typeof args.cutSeq === 'number' ? args.cutSeq : null\n      // root enrich 尽力而为（Q3）：归档只隐藏列表、对象还在内存，大概率\n      // 成功；archiveOriginal 可关、resolveRoot 可返空——任一失败落 null，\n      // 不阻断事件（下游按 root 过滤的诉求退化为按 sessionId 过滤）\n      let root: string | null = null\n      try {\n        root = (await rt.resolveRoot(sessionId)) || null\n      } catch {\n        // 解析失败按无 root 继续发事件：事件可见性优先于 enrich 完整性，\n        // 抛错会让终态事件整条丢失（下游记忆清理漏做，比字段缺失更糟）\n        root = null\n      }\n      let eventName: string\n      let payload: RecallCompleteEvent | RecallFailedEvent\n      if (status === 'complete') {\n        eventName = RECALL_EVENT_COMPLETE_HOST\n        payload = {\n          version: 1,\n          sessionId,\n          childSessionId: args && args.childSessionId ? String(args.childSessionId) : null,\n          scope,\n          cutSeq,\n          messageId,\n          root,\n          count: args && typeof args.count === 'number' ? args.count : 0,\n          chatReverted: Boolean(args && args.chatReverted),\n          archiveRequested: Boolean(args && args.archiveRequested),\n          time: Date.now(),\n        }\n      } else {\n        eventName = RECALL_EVENT_FAILED_HOST\n        const code = args && typeof args.code === 'string' && args.code ? args.code : undefined\n        payload = {\n          version: 1,\n          stage: args && args.stage === 'fork' ? 'fork' : 'execute',\n          sessionId,\n          messageId,\n          scope,\n          cutSeq,\n          root,\n          ...(code ? { code } : {}),\n          error: args && typeof args.error === 'string' && args.error ? args.error : 'unknown recall failure',\n          time: Date.now(),\n        }\n      }\n      // queueMicrotask + try/catch 是硬要求（规格 §3.2）：同步 emit 时下游\n      // 监听器抛错/慢执行会直接反噬端点响应与撤回链路。emitEvent 本身抛错\n      // 与 microtask 内的异常同权吞掉——事件是尽力而为的旁路，失败只留痕\n      queueMicrotask(() => {\n        try {\n          emitEvent(eventName, payload)\n        } catch (error) {\n          rt.recordError('recall event emit failed: ' + String(error))\n        }\n      })\n      return { ok: true }\n    }\n  }\n}\n"
