    {
      "path": "src/host/scripts.posix.ts",
      "content": "/**\n * dsh-recall-plugin — bash 脚本模板（纯函数，无 ctx 依赖，POSIX 平台专用）\n *\n * 职责：Linux/macOS 下所有 shell 命令的 bash 脚本文本。与 scripts.pwsh.js\n * 导出同名接口，由 store.js 按 process.platform 选择。\n *\n * 硬约束（写每一段前先过一遍）：\n * - macOS 系统 bash 是 3.2：禁用 declare -A / mapfile / ${var,,} 等 bash 4\n *   特性；关联数组需求全部下沉给 awk（POSIX awk 自带），排序交给 sort。\n * - 与 PowerShell 版不同，bash 按行解析时不存在「NUL 丢弃」问题，ls-files\n *   可以用 -z——但 diff/回退的清单对比仍走临时文件 + awk（bash 3.2 无映射\n *   结构），行内路径含 TAB/换行的极端情形与 Windows 版同为已知限制。\n * - 文件名比较、哈希输入全部按字节处理（LC_ALL=C，见 POSIX_PRELUDE），\n *   与 Node 侧 UTF-8 解码各司其职：bash 不转码，字节原样通过。\n */\n\nimport type { ScriptStore } from '../types/scripts.js'\n\n// 单引号字面量转义：bash 单引号串里不能出现单引号，标准手法是\n// 关闭引号 + \\' 转义 + 重开（'…'\\''…'），杜绝变量展开与注入。\nexport function psq(value: string): string {\n  return \"'\" + String(value).replace(/'/g, \"'\\\\''\") + \"'\"\n}\n\n// POSIX 统一前导：LC_ALL=C 让 sort/awk 的路径排序按字节确定序（跨机器\n// 一致），也避免部分环境 locale 缺失时 git/perl 打 warning。bash 本身\n// 不转码 stdout，中文字节原样传给 Node 按 UTF-8 解码，无 Windows 侧\n// 的代码页问题。\nexport const UTF8_PRELUDE = 'export LC_ALL=C'\n\n// 超大文件跳过阈值（字节），默认值与 config.js 的 maxFileBytes 一致；\n// 实际生效值以 store.maxFileBytes（用户 config 可调）经 oversizeListBlock 注入为准。\n// issue #24 起默认 8MB（同 pwsh 侧，两套模板必须同值）。\nexport const MAX_FILE_BYTES = 8388608\n\n// 失败清扫的 stale 锁阈值（分钟，M3）：锁文件 mtime 超过该值才视为残留可清；\n// 更新的锁视为「有 git 操作正在进行」让路。本插件单条快照/回退的超时是\n// 10 分钟，阈值取其一半，保证本方超时遗留的锁（≥10 分钟）一定能被清。\n// 与 pwsh 版必须同值（scripts-contract 钉）；属内部安全策略常量，与\n// snapshots.js 的 FUSE_AFTER 同类，不走 Config。\nexport const STALE_LOCK_MIN = 5\n\n// 心跳文件有效窗口（秒，M3）：超过该时长的心跳视为失效实例（崩溃/重启\n// 遗留或长期空闲），不再阻止清扫。心跳随 ensureGit/快照刷新，活动中的\n// 实例窗口内必然有新心跳；长 git 操作（≤10 分钟）期间心跳写于操作开头，\n// 仍在窗口内。\nexport const HEARTBEAT_TTL_S = 900\n\n// 影子仓库 info/attributes 固化内容（issue #12 字节保真）：与 pwsh 版同名\n// 常量逐字同值（scripts-contract 钉），完整语义与逐项动机见 scripts.pwsh.js\n// 同名常量注释。一句话：git archive/add 都会应用快照树里项目自己的\n// .gitattributes（text=auto + 缺省 core.eol=native 的转换，仓库级\n// autocrlf=false 挡不住），info/attributes 优先级最高、对全部路径一票否决，\n// 快照 capture/restore 两侧逐字节保真。\nexport const FIDELITY_ATTRS = '* -text -filter -ident -export-ignore -export-subst -working-tree-encoding'\n\n// bash/cat 输出无 BOM；保留同名导出维持两套模板接口一致（幂等无害）\nexport function stripBom(text: string): string {\n  return text.replace(/^\\uFEFF/, '')\n}\n\n// 嵌套 git 仓库（工作区里的子项目自带 .git）会被 add -A 记成 gitlink\n// （160000）；gitlink 残留在 index 时 add -A 会 fatal，且对文件回退毫无\n// 意义——所以 add 前后各清一次，子仓库内容不进快照。\n// 依赖外层脚本已定义的 $git/$g；被 snapshot/diff/rollback 三处复用。\nfunction dropGitlinksBlock() {\n  return [\n    '\"$git\" --git-dir=\"$g\" ls-files -z --stage | while IFS= read -r -d \\'\\' e; do',\n    '  case \"$e\" in',\n    // --work-tree 不可省：影子仓库是 bare 仓库，裸 --git-dir 下 update-index 会\n    // fatal \"this operation must be run in a work tree\"，set -e 直接终止整条快照\n    \"    160000\\\\ *) p=${e#*$'\\\\t'}; \\\"$git\\\" --literal-pathspecs --git-dir=\\\"$g\\\" --work-tree=\\\"$root\\\" update-index --force-remove -- \\\"$p\\\" ;;\",\n    '  esac',\n    'done'\n  ].join('\\n')\n}\n\n// exclude 表 basename 形式 pattern（见 pwsh 版同注释）转 find 的目录剪枝前缀。\n// 只服务 oversizeListBlock：issue #28 起 limitScanBlock 的清单由 git 给，不再自己\n// 遍历工作区，也就不再需要这份剪枝数组。\n// 依赖前置的 excludeSyncBlock 定义的 $new_exc。\n// 括号是数组元素里的**数据**，不经过 shell 分词——写成 \"\\(\" 时 bash 不剥\n// 反斜杠，find 收到两字符 token \\( 直接报「paths must precede expression」\n// 退出 1，整条剔除被 2>/dev/null 与 || true 吞成静默空操作。killOrphansScript\n// 里的 \\( 是另一种东西：脚本源码内联写法，分词阶段就被剥掉，两者不可混用。\n// 外层 -type d：prune 只该剪目录，否则与排除目录同名的大文件（dist/target/\n// .git）会被 -name 一并剪掉；pwsh 侧只对 EnumerateDirectories 判名，两侧同语义。\nfunction dirPruneArgsBlock() {\n  return [\n    'oversize_args=()',\n    'while IFS= read -r line || [ -n \"$line\" ]; do',\n    \"  t=${line%$'\\\\r'}\",\n    '  t=\"${t#\"${t%%[![:space:]]*}\"}\"; t=\"${t%\"${t##*[![:space:]]}\"}\"',\n    '  if [ -z \"$t\" ]; then continue; fi',\n    '  case \"$t\" in \\\\#* | \\\\!*) continue ;; esac',\n    '  t=\"${t%/}\"',\n    '  case \"$t\" in *\\\\** | *\\\\?* | *\\\\[* | */*) continue ;; esac',\n    '  if [ ${#oversize_args[@]} -eq 0 ]; then oversize_args+=(-name \"$t\"); else oversize_args+=(-o -name \"$t\"); fi',\n    'done <<< \"$new_exc\"',\n    'oversize_prune=()',\n    \"if [ ${#oversize_args[@]} -gt 0 ]; then oversize_prune=('(' -type d '(' \\\"${oversize_args[@]}\\\" ')' ')' -prune -o); fi\",\n  ].join('\\n')\n}\n\n// 剔除超大文件：find -print0 + read -d '' 按字节安全遍历（文件名含换行\n// 也不怕）；2>/dev/null 容忍个别不可访问子目录（杀软锁定、异常 ACL），\n// 漏看个别文件是 fail-open，可接受——与 pwsh 版同策略。\n// 阈值按调用注入（store.maxFileBytes，config 可调），不读模块常量。\n// issue #29：改成「先出清单、再让 add 排除」——此前 add 先写全部大文件对象、\n// 之后才把条目移出 index，一个「小文件少 + 大文件多」的工作区能在预算通过后\n// 仍写满磁盘。清单双份：pathspec 版给 add（带 :(top) 前缀，见 add 前的 cd），\n// rel 版给 update-index 与降级兜底；空清单等价全量 add，故清单写失败也安全。\n// find 会多列被 .gitignore 排除的大文件：多排除几个 git 本来就不加的路径无害。\n// 依赖外层已定义的 $git/$g/$root 与 excludeSyncBlock 的 $new_exc。\n// PF-9 合批：xargs -0 自适应批次（规避 ARG_MAX）等价 win32 侧显式 100 条/批。\nfunction oversizeRemoveBlock(): string {\n  // --work-tree 不可省：bare 影子仓库下裸 update-index fatal（被 || true 吞掉\n  // 后大文件会静默留在 index 里），maxFileBytes 的承诺会形同虚设\n  return \"xargs -0 \\\"$git\\\" --literal-pathspecs --git-dir=\\\"$g\\\" --work-tree=\\\"$root\\\" update-index --force-remove -- < \\\"$oversize_r\\\" 2>/dev/null || true\"\n}\n\nfunction oversizeListBlock(maxBytes: number): string {\n  return [\n    dirPruneArgsBlock(),\n    'oversize_p=\"$g/oversize-pathspec.$$\"',\n    'oversize_r=\"$g/oversize-rel.$$\"',\n    ': > \"$oversize_p\"',\n    ': > \"$oversize_r\"',\n    'find \"$root\" \"${oversize_prune[@]}\" -type f -size +' + String(maxBytes || MAX_FILE_BYTES) + 'c -print0 2>/dev/null | while IFS= read -r -d \\'\\' f; do',\n    '  oversize_rel=\"${f#\"$root\"/}\"',\n    '  printf \\'%s\\\\0\\' \":(top,exclude,literal)$oversize_rel\" >> \"$oversize_p\"',\n    '  printf \\'%s\\\\0\\' \"$oversize_rel\" >> \"$oversize_r\"',\n    'done',\n    oversizeRemoveBlock(),\n  ].join('\\n')\n}\n\n// issue #29：add 前置（探测 + 切 cwd）收在一处——snapshot 与 collectLists 两处\n// add 共用同一形态，漏改一处就会让该链路重新写大文件。\n// 必须 cd 到 root：pathspec 的隐含全集会被 cwd 前缀裁切，:(top) 救不回来（实测），\n// 而脚本 cwd 是宿主工作目录（可能在工作区子目录里）。\n// 旧 git（<2.25）无 --pathspec-from-file：探测失败就不传该参数，退回裸 add——\n// 与现状同行为，总好过带未知选项让整条快照 fatal。探测结果缓存进 git-dir。\nfunction oversizeAddPrepBlock(): string {\n  return [\n    'pa_args=()',\n    'if [ -s \"$oversize_p\" ]; then',\n    '  if [ -f \"$g/pathspec-from-file.ok\" ] || \"$git\" add -h 2>&1 | grep -q -- \\'--pathspec-from-file\\'; then',\n    '    printf \\'1\\\\n\\' > \"$g/pathspec-from-file.ok\" 2>/dev/null || true',\n    '    pa_args=(--pathspec-from-file=\"$oversize_p\" --pathspec-file-nul)',\n    '  fi',\n    'fi',\n    'cd \"$root\"',\n  ].join('\\n')\n}\n\n// issue #24：快照前置护栏——统计「真正会进快照的文件总量」与耗时，任一超限即\n// 整体停用本次快照（输出 SNAP_LIMIT 后 exit 0），不执行 add。停用而非截断的\n// 理由、issue #28 的口径修正（清单由 git 给、-c/--exclude-standard 为何都必须\n// 带上）与 pwsh 版同名函数注释一致，此处不重复。\n// issue #29：统计失败改为 fail-closed——规模未知就不许 add。此前 fail-open 的\n// 取舍在 $HOME 级工作区上是灾难（ls-files 一失败，10 分钟 + 10 GB 的 add 照跑）。\n// 失败走哨兵 + exit 0 而非非零退出：没跑 add 就没有残骸，不该触发失败清扫与 prune；\n// stderr 随 SNAP_SCAN_ERR 回传，原文进「最近错误」供排障。\n// GNU find 有 -printf、macOS BSD find 没有：探测后二选一（只用来判别 stat 方言）。\n// 批量 stat 而非逐文件 fork——十万文件量级逐次 fork 会退化成十万次进程。\n// 预算只有秒精度（date +%s）：遍历中无法中断，事后比较已足够——超预算即停用，\n// 中途省下的遍历时间不是语义要求。\n// 依赖 $git/$g/$root 与前置 excludeSyncBlock（info/exclude 必须先是最新的，\n// 否则 --exclude-standard 读到的还是上一轮的排除表）。\nfunction limitScanBlock(maxBytes: number, fileMaxBytes: number, budgetMs: number): string {\n  const limit = maxBytes > 0 ? String(maxBytes) : '0'\n  const fileLimit = String(fileMaxBytes || MAX_FILE_BYTES)\n  const budgetS = budgetMs > 0 ? String(Math.ceil(budgetMs / 1000)) : '0'\n  return [\n    'limit_start=$(date +%s)',\n    'limit_tmp=\"$g/limit-scan.$$\"',\n    'limit_err=\"$g/limit-scan-err.$$\"',\n    // set -e：条件位置豁免，失败由 else 分支显式处理（不许穿透到 add）\n    'if \"$git\" -c core.quotePath=false --git-dir=\"$g\" --work-tree=\"$root\" ls-files -z -co --exclude-standard > \"$limit_tmp\" 2> \"$limit_err\"; then',\n    '  :',\n    'else',\n    '  limit_rc=$?',\n    // 压平成单行才能随哨兵回传；截 300 字符防一条巨长 stderr 撑爆错误环\n    '  limit_msg=$(head -c 300 \"$limit_err\" 2>/dev/null | tr \"\\\\n\\\\r\" \"  \")',\n    '  rm -f \"$limit_tmp\" \"$limit_err\"',\n    '  printf \\'SNAP_SCAN_FAIL %s\\\\n\\' \"$limit_rc\"',\n    '  printf \\'SNAP_SCAN_ERR %s\\\\n\\' \"$limit_msg\"',\n    '  exit 0',\n    'fi',\n    'rm -f \"$limit_err\"',\n    'limit_sizes=\"\"',\n    'if [ -s \"$limit_tmp\" ]; then',\n    // ls-files 输出相对 root 的路径，而脚本 cwd 是宿主工作目录：必须 cd 进去再 stat\n    '  if find \"$root\" -maxdepth 0 -printf \\'\\' >/dev/null 2>&1; then',\n    \"    limit_sizes=$(cd \\\"$root\\\" && xargs -0 stat -c '%s %F' -- < \\\"$limit_tmp\\\" 2>/dev/null || true)\",\n    '  else',\n    \"    limit_sizes=$(cd \\\"$root\\\" && xargs -0 stat -f '%z %HT' -- < \\\"$limit_tmp\\\" 2>/dev/null || true)\",\n    '  fi',\n    'fi',\n    'rm -f \"$limit_tmp\"',\n    // 目录条目（嵌套仓库在 ls-files 里输出 `dir/`）不计入：add 侧同样不纳入它\n    // 的内容（gitlink 被剔除 / 无提交时 unable to index）；越过单文件上限的也\n    // 不计入——oversizeListBlock 随后会把它移出 index\n    'limit_total=$(printf \\'%s\\\\n\\' \"$limit_sizes\" | awk -v lim=' + limit + ' -v flim=' + fileLimit + ' \\'{ if (tolower($0) ~ /directory/) next; if ($1 <= flim) { s += $1; if (lim > 0 && s > lim) { print \"OVER \" s; exit } } } END { if (lim <= 0 || s <= lim) print s }\\')',\n    'limit_elapsed=$(( $(date +%s) - limit_start ))',\n    'case \"$limit_total\" in',\n    '  OVER\\\\ *) echo \"SNAP_LIMIT bytes ${limit_total#OVER } ' + limit + '\"; exit 0 ;;',\n    'esac',\n    'if [ ' + budgetS + ' -gt 0 ] && [ \"$limit_elapsed\" -gt ' + budgetS + ' ]; then',\n    '  echo \"SNAP_LIMIT time $((limit_elapsed * 1000)) $(( ' + budgetS + ' * 1000 ))\"; exit 0',\n    'fi',\n  ].join('\\n')\n}\n\n// 用户自定义排除同步：基础排除表 + 用户 exclude.txt 合并重写 info/exclude，\n// 再用 ls-files -i -c --exclude-from 找出「已被跟踪但命中排除」的条目清掉。\n// 与 pwsh 版同语义：只用 --exclude-from，不引入项目 .gitignore（--exclude-standard）\n// 的语义；放在 add -A 之前让排除先生效。read 循环里做 trim + 注释过滤，\n// 兼容 Windows 上编辑带 CRLF 的 exclude.txt。\n// base 基础排除表按调用注入（config.baseExcludes 可调），不硬编码。\n// 依赖外层已定义的 $git/$g。\n// 平台差异（有意的不对称，勿「补平」）：pwsh 版在这里额外发现目录重解析点并并入\n// 排除表——git for Windows 把 NTFS junction 当普通目录递归，自引用 junction 会把\n// index 撑到 Windows 的 31 层重解析点上限（实测 1.24 万条 → 39.2 万条）。\n// POSIX 的 git 把指向目录的符号链接记成 120000 条目、不递归进目标，故本侧无事可做；\n// 若照搬该发现，反而会把本来就是合法快照内容的符号链接从快照里剔除（行为回归）。\n// POSIX 的 bind mount 环不覆盖，记为已知缺口。\n// - PF-9 条件化：新旧内容比对（命令替换对两侧同样剥尾随换行，比对稳定）\n//   相同则跳过重写**并跳过**清理循环（每条消息常态省 1 次 git 子进程 +\n//   1 次盘写）；语义安全论证见 pwsh 版同注释（exclude 未变时 index 已净，\n//   add -A 因排除先生效不会加回；「改排除即时生效」承诺不变）。\n// - PF-9 合批：ls-files -z 命中经 xargs -0 多路径合参——xargs 自适应批次\n//   本就是为规避 ARG_MAX 设计（等价 win32 侧显式 100 条/批的分块纪律），\n//   -0 保证空格/中文路径不分裂；空输入时 GNU xargs 空跑一次 update-index\n//   （usage 退出，2>/dev/null + || true 兜住，BSD xargs 空输入不执行）。\nfunction excludeSyncBlock(excludeFile: string, base: string[]): string {\n  // 兜底含两种存储目录名：降级为 .dsh-recall-snapshots/，home 存储为\n  // dsh-recall-snapshots/（root=HOME 时落入工作区，漏排除会自吞，issue #6）\n  const baseList = Array.isArray(base) && base.length ? base : ['.git', 'node_modules/', '.dsh-recall-snapshots/', 'dsh-recall-snapshots/']\n  const baseLines = baseList.join('\\n') + '\\n'\n  return [\n    'ex_file=' + psq(excludeFile),\n    'exc=\"$g/info/exclude\"',\n    'user_pats=\"\"',\n    'if [ -f \"$ex_file\" ]; then',\n    '  while IFS= read -r line || [ -n \"$line\" ]; do',\n    \"    t=${line%$'\\\\r'}\",\n    '    t=\"${t#\"${t%%[![:space:]]*}\"}\"; t=\"${t%\"${t##*[![:space:]]}\"}\"',\n    '    if [ -z \"$t\" ]; then continue; fi',\n    '    case \"$t\" in \\\\#*) continue ;; esac',\n    '    user_pats=\"$user_pats$t\\\\n\"',\n    '  done < \"$ex_file\"',\n    'fi',\n    \"new_exc=$(printf '\\\\n\" + baseLines.replace(/\\\\/g, '\\\\\\\\').replace(/%/g, '%%') + \"%b' \\\"$user_pats\\\")\",\n    'old_exc=$(cat \"$exc\" 2>/dev/null || true)',\n    'if [ \"$new_exc\" != \"$old_exc\" ]; then',\n    \"  printf '%s\\\\n' \\\"$new_exc\\\" > \\\"$exc\\\"\",\n    // 影子仓库是 bare：写 index 必须显式 --work-tree，否则 update-index fatal\n    // 并被 || true 吞成「排除对已跟踪条目从未生效」。ensureGitScript 也走本函数\n    // 但没有 root（建仓不遍历工作区），那时退回原调用（命中通常为空，fail-open）\n    '  if [ -n \"${root:-}\" ]; then',\n    '    \"$git\" -c core.quotePath=false --literal-pathspecs --git-dir=\"$g\" ls-files -i -c --exclude-from=\"$exc\" -z 2>/dev/null | xargs -0 \"$git\" --literal-pathspecs --git-dir=\"$g\" --work-tree=\"$root\" update-index --force-remove -- 2>/dev/null || true',\n    '  else',\n    '    \"$git\" -c core.quotePath=false --literal-pathspecs --git-dir=\"$g\" ls-files -i -c --exclude-from=\"$exc\" -z 2>/dev/null | xargs -0 \"$git\" --literal-pathspecs --git-dir=\"$g\" update-index --force-remove -- 2>/dev/null || true',\n    '  fi',\n    'fi',\n  ].join('\\n')\n}\n\n// 心跳写入（M3）：随 git 操作顺手把「宿主 PID + epoch 秒」写进 store 目录\n// （store.dir = git-dir 上两级），供对方实例的失败清扫判定「另一个 DSH 实例\n// 正在使用此快照库」。PID 在模板生成期取宿主进程的 process.pid，无需调用方\n// 传参。fail-open（|| true，set -e 下安全）：心跳写失败绝不能连累快照本身\n// ——最坏退化为无心跳，清扫只剩新锁分级保护。\n// 依赖外层已定义的 $g；被 ensureGitScript / snapshotScript 复用。\nfunction heartbeatBlock() {\n  return [\n    'hbf=\"$(dirname \"$(dirname \"$g\")\")/heartbeat\"',\n    'printf \\'%s %s\\\\n\\' ' + psq(String(process.pid)) + ' \"$(date +%s)\" > \"$hbf\" 2>/dev/null || true'\n  ].join('\\n')\n}\n\n// 解析 git 可执行文件路径：bash 从 PATH 找（POSIX 上 git 装了就在 PATH，\n// 没有 Windows 那种四类安装位置的散装问题）\nexport function resolveGitScript(): string {\n  return [\n    'p=$(command -v git 2>/dev/null || true)',\n    '[ -n \"$p\" ] && printf \\'%s\\\\n\\' \"$p\"',\n    'exit 0'\n  ].join('\\n')\n}\n\n// 探测 bash 侧的 home 基底：只回显 bash env 里的 $DSH_HOME（可能为空）。\n// 为什么不在这里回退 $HOME：DSH 的 bash 执行器会洗刷子进程的 DSH_* 变量\n// （dsh-subprocess scrubbedParentEnv），用户导出的 DSH_HOME 在 bash 里\n// 通常不可见——若在此回退 $HOME，Node 侧的字面量回退永远轮不到，\n// 「DSH_HOME 指到哪、快照就存哪」会失效。优先级与 pwsh 版对齐：\n// bash env 显式值 > Node 主进程 DSH_HOME > $HOME（os.homedir）。\nexport function probeHomeScript(): string {\n  return 'printf \\'%s\\' \"${DSH_HOME:-}\"'\n}\n\nexport function mkdirScript(dir: string): string {\n  return 'mkdir -p -- ' + psq(dir)\n}\n\n// 旧版迁移：把降级时代落在项目内的影子仓库整体搬回 home 并删源目录\nexport function migrateScript(src: string, dst: string): string {\n  return [\n    'set -e',\n    'src=' + psq(src),\n    'dst=' + psq(dst),\n    'if [ -e \"$src/git\" ]; then mv -f \"$src/git\" \"$dst/git\"; fi',\n    'if [ -e \"$src/index.json\" ]; then mv -f \"$src/index.json\" \"$dst/index.json\"; fi',\n    'rm -rf -- \"$src\"',\n    'echo MIGRATE_OK'\n  ].join('\\n')\n}\n\n// 旧快照容器一次性迁移（POSIX 专属，I24 漂移修复的存量数据兜底，输出四态\n// 由 store.js resolvePosixHomeBase 消费）：仅当「旧容器存在且新容器不存在」\n// 才整容器 mv——同卷（home 内部）rename 原子，无部分移动状态；容器级整移\n// 自然带上根级 exclude.txt，语义无损。BOTH_PRESENT（双容器并存）/MIGRATE_FAIL\n// 输出后不动任何数据。无 set -e（要靠分支输出状态而非中途退出）；if 条件\n// 内的 && 链豁免 I16 约束（该坑只针对循环体与裸列表）。非 git 命令，不适用\n// g= 赋值 / RECALL_CLEANUP 哨兵约定。\nexport function legacyHomeMigrateScript(homedir: string): string {\n  return [\n    'old=' + psq(homedir + '/dsh-recall-snapshots'),\n    'new=' + psq(homedir + '/.dsh/dsh-recall-snapshots'),\n    'if [ -d \"$old\" ] && [ ! -d \"$new\" ]; then',\n    '  if mkdir -p -- \"$(dirname \"$new\")\" && mv -f -- \"$old\" \"$new\"; then echo MIGRATE_OK',\n    '  else echo MIGRATE_FAIL; fi',\n    'elif [ -d \"$old\" ]; then echo BOTH_PRESENT',\n    'else echo OLD_ABSENT; fi'\n  ].join('\\n')\n}\n\n// 建立影子仓库 + 排除同步 + 回读 gc.stamp（语义与 pwsh 版一致，\n// 见 scripts.pwsh.js 同名函数注释）\nexport function ensureGitScript(store: ScriptStore, gitExe: string, base: string[]): string {\n  return [\n    'set -e',\n    'git=' + psq(gitExe),\n    'repo=' + psq(store.repo),\n    'g=' + psq(store.git),\n    heartbeatBlock(),\n    // 冷启动首消息快照与启动预热（或双实例）并发时，两个 git init 在空\n    // repo 目录同跑，输家报 fatal: cannot mkdir <git>: File exists——窗口\n    // 极小但首条消息的快照会因此丢失。git init 幂等：失败后 HEAD 已出现\n    // 即同伴建成，视同成功继续；HEAD 也没有才是真失败，带错误退出（诊断\n    // 不丢）。检查 HEAD 而非目录存在：半截目录也会被 init 补齐。pwsh 版\n    // 无需同款改动——native 非零退出不抛（I14），输家继续跑 config 时\n    // 同伴已建好 repo，竞态天然容忍，真失败由快照 add 的显式检查兜底。\n    'if [ ! -f \"$g/HEAD\" ]; then',\n    '  init_log=$(\"$git\" init \"$repo\" 2>&1) || {',\n    '    if [ ! -f \"$g/HEAD\" ]; then printf \\'%s\\\\n\\' \"$init_log\" >&2; exit 1; fi',\n    '  }',\n    'fi',\n    '\"$git\" --git-dir=\"$g\" config core.longpaths true',\n    '\"$git\" --git-dir=\"$g\" config core.autocrlf false',\n    '\"$git\" --git-dir=\"$g\" config advice.addEmbeddedRepo false',\n    // 属性固化（issue #12，内容见 FIDELITY_ATTRS）：info/ 由 git init 自带\n    // （info/exclude 模板，excludeSyncBlock 同样依赖），无需建目录；每次\n    // ensureGit 重写幂等，存量仓库升级后首次 init 自然补上。\n    'printf ' + psq(FIDELITY_ATTRS + '\\n') + ' > \"$g/info/attributes\"',\n    excludeSyncBlock(store.excludeFile, base),\n    'stamp=\"$g/gc.stamp\"',\n    'if [ -f \"$stamp\" ]; then printf \\'GIT_OK %s\\\\n\\' \"$(head -n1 \"$stamp\" 2>/dev/null)\"; else echo GIT_OK; fi'\n  ].join('\\n')\n}\n\n// 存量归一化迁移（issue #12，语义与动机详见 pwsh 版 attrsMigrateBlock 注释）：\n// 属性固化后旧索引条目仍指向归一化 blob（stat 缓存时序依赖地跳过重哈希），\n// --renormalize 按当前属性重哈希一次；无 pathspec 是空操作，必须带 ':(top)'\n// 顶层魔法 pathspec。标记文件每仓库至多跑一次；失败（老 git 无该选项等）\n// 只跳过标记下条消息重试，不连累快照主流程（set -e 下 || rc=$? 捕获）。\n// 依赖外层已定义的 $git/$g/$root；仅 snapshotScript 使用。\nfunction attrsMigrateBlock() {\n  return [\n    'mig_stamp=\"$g/attrs-v1.stamp\"',\n    'if [ ! -f \"$mig_stamp\" ]; then',\n    '  migrc=0',\n    '  \"$git\" --git-dir=\"$g\" --work-tree=\"$root\" add --renormalize --ignore-errors -- \\':(top)\\' >/dev/null 2>&1 || migrc=$?',\n    '  if [ \"$migrc\" -le 1 ]; then printf \\'1\\\\n\\' > \"$mig_stamp\" 2>/dev/null || true; fi',\n    'fi',\n  ].join('\\n')\n}\n\n// 快照：add -A → write-tree → commit-tree（孤儿提交）→ tag（语义同 pwsh 版）。\n// tag -f：事件重放/重发会产生重复 messageId，裸 tag 对已存在 tag fatal\n// 导致整条快照失败；-f 把 tag 指到最新提交，语义为「同一条消息取最新状态」。\nexport function snapshotScript(root: string, store: ScriptStore, gitExe: string, messageId: string, base: string[]): string {\n  return [\n    'set -e',\n    'git=' + psq(gitExe),\n    'g=' + psq(store.git),\n    'root=' + psq(root),\n    heartbeatBlock(),\n    dropGitlinksBlock(),\n    excludeSyncBlock(store.excludeFile, base),\n    // issue #24：总量/预算护栏先于 add——超限时连 add 都不跑\n    limitScanBlock(store.maxWorkspaceBytes, store.maxFileBytes, store.scanBudgetMs),\n    // issue #29：大文件清单先于 add——add 带 exclude 后不再为它们写对象\n    oversizeListBlock(store.maxFileBytes),\n    attrsMigrateBlock(),\n    oversizeAddPrepBlock(),\n    // fail-open add（issue #7 加固，语义见 pwsh 版同款注释）：--ignore-errors\n    // 下「无法索引的路径」以退出码 1 结束但索引已落盘；≥2 才是真 fatal，\n    // 显式退出让 runShell 抛错（set -e 对 add 非零本会终止，但 || rc=$?\n    // 捕获后必须自检，否则 tolerated/fatal 无法区分）。stderr 合并进变量\n    // 供 fatal 时带回诊断与 SNAP_SKIP 提取。\n    'addrc=0',\n    'add_log=$(\"$git\" --git-dir=\"$g\" --work-tree=\"$root\" add -A --ignore-errors \"${pa_args[@]}\" 2>&1) || addrc=$?',\n    'if [ \"$addrc\" -ge 2 ]; then printf \\'%s\\\\n\\' \"$add_log\" >&2; exit \"$addrc\"; fi',\n    \"printf '%s\\\\n' \\\"$add_log\\\" | sed -n -e \\\"s/^error: unable to index file '\\\\(.*\\\\)'$/\\\\1/p\\\" -e \\\"s/^error: unable to add '\\\\(.*\\\\)' to index$/\\\\1/p\\\" | sort -u | while IFS= read -r sk; do\",\n    // 循环体用 if/fi 而非 && 列表：&& 列表条件为假时整条管道退出码为 1，\n    // set -e 会把脚本杀掉（if 语句天然豁免）\n    '  if [ -n \"$sk\" ]; then printf \\'SNAP_SKIP %s\\\\n\\' \"$sk\"; fi',\n    'done',\n    dropGitlinksBlock(),\n    // 兜底：旧 git 走裸 add 时大文件仍会被重新索引，这里按清单再清一次\n    oversizeRemoveBlock(),\n    'rm -f \"$oversize_p\" \"$oversize_r\"',\n    'tree=$(\"$git\" --git-dir=\"$g\" --work-tree=\"$root\" write-tree)',\n    'commit=$(\"$git\" --git-dir=\"$g\" -c user.name=dsh-recall -c user.email=recall@dsh.local commit-tree \"$tree\" -m ' + psq('snapshot ' + messageId) + ')',\n    '\"$git\" --git-dir=\"$g\" tag -f ' + psq('snap-' + messageId) + ' \"$commit\" >/dev/null',\n    // PF-1：TREE 行随 SNAP_OK 回传 add -A 之后的 index 树指纹（语义见 pwsh 版\n    // 同名注释）——execute 与 preview 指纹比对判 STALE，免整条重复 diff\n    'echo \"TREE $tree\"',\n    'echo SNAP_OK'\n  ].join('\\n')\n}\n\n// 当前清单/目标树清单落临时文件：两处复用（diff 与 rollback）。\n// 关键前置链与 pwsh 版对齐——gitlink 清理 → 排除同步 → add -A → 再清\n// gitlink → 超大剔除——少了 add -A 的话 ls-files 读到的还是上一次快照的\n// 旧 index，「当前清单」永远等于目标 tag，diff 恒空（调试踩过的坑）。\n// 行格式：cur 为「mode sha stage<TAB>path」（取 sha=a[2]），target 为\n// 「mode type sha<TAB>path」（取 sha=a[3]）；grep 滤掉 gitlink（160000）行，\n// 无匹配时退出码 1，set -e 下统一 || true。\nfunction collectListsBlock(store: ScriptStore, gitExe: string, root: string, tag: string, base: string[]): string {\n  return [\n    'git=' + psq(gitExe),\n    'g=' + psq(store.git),\n    'root=' + psq(root),\n    dropGitlinksBlock(),\n    excludeSyncBlock(store.excludeFile, base),\n    // issue #29：与 snapshotScript 同形——大文件不进 add（否则 preview 一次\n    // 也要为它们写对象），清单随 add 后的兜底剔除一起收口\n    oversizeListBlock(store.maxFileBytes),\n    oversizeAddPrepBlock(),\n    // fail-open add（语义见 snapshotScript 同款注释）：diff/rollback 的当前\n    // 清单来自这次 add 后的索引——被跳过的路径不进清单，diff 不显示、\n    // rollback 删除清单也不会误删它们；≥2 显式退出防「旧索引假成功」\n    'addrc=0',\n    '\"$git\" --git-dir=\"$g\" --work-tree=\"$root\" add -A --ignore-errors \"${pa_args[@]}\" || addrc=$?',\n    '[ \"$addrc\" -le 1 ] || exit \"$addrc\"',\n    dropGitlinksBlock(),\n    oversizeRemoveBlock(),\n    'tmpc=' + psq(store.dir + '/diff-cur.$$'),\n    'tmpt=' + psq(store.dir + '/diff-tgt.$$'),\n    '\"$git\" -c core.quotePath=false --git-dir=\"$g\" --work-tree=\"$root\" ls-files --stage | grep -v \\'^160000 \\' > \"$tmpc\" || true',\n    '\"$git\" -c core.quotePath=false --git-dir=\"$g\" ls-tree -r ' + psq(tag) + ' | grep -v \\'^160000 \\' > \"$tmpt\" || true'\n  ].join('\\n')\n}\n\n// diff：awk 一趟对比 cur/target（cur 侧 \"mode sha<TAB>path\" 取 a[2]，\n// target 侧 \"mode type sha<TAB>path\" 取 a[3]），输出 TSV「kind<TAB>path」\n// 逐行打印，Node 侧解析（不在 bash 里拼 JSON——没有 jq 依赖、\n// 转义路径的坑也一并消失）。sort -k2 按 path 确定序，与 pwsh 版对齐。\n// PF-1：末尾追加 write-tree + TREE 行（add 后的 index 树指纹，语义见 pwsh\n// 版同注释）。POSIX 侧 TSV 文本轻、无 ConvertTo-Json 序列化开销，不做\n// TOTAL/截断——全量输出，截断仍由 JS 侧 slice（与既有语义一致）。\nexport function diffScript(root: string, store: ScriptStore, gitExe: string, tag: string, base: string[]): string {\n  return [\n    'set -e -o pipefail',\n    collectListsBlock(store, gitExe, root, tag, base),\n    \"trap 'rm -f \\\"$tmpc\\\" \\\"$tmpt\\\" \\\"$oversize_p\\\" \\\"$oversize_r\\\"' EXIT\",\n    'awk -F\\'\\\\t\\' -v OFS=\\'\\\\t\\' \\'',\n    '  FNR==1 { fidx++ }',\n    '  fidx==1 { split($1, a, \" \"); cur[$2]=a[2]; next }',\n    '  { split($1, a, \" \"); tgt[$2]=a[3] }',\n    '  END {',\n    '    for (p in cur) {',\n    '      if (p in tgt) { if (tgt[p] != cur[p]) print \"modified\", p }',\n    '      else print \"added\", p',\n    '    }',\n    '    for (p in tgt) if (!(p in cur)) print \"restored\", p',\n    '  }',\n    \"' \\\"$tmpc\\\" \\\"$tmpt\\\" | sort -t$'\\\\t' -k2,2\",\n    'tree=$(\"$git\" --git-dir=\"$g\" --work-tree=\"$root\" write-tree)',\n    'echo \"TREE $tree\"',\n    'exit 0'\n  ].join('\\n')\n}\n\n// 回退：恢复侧按 diff 变更集走 git archive | tar 直接管到工作区（无需 Windows\n// 的 zip 中转），删除侧按清单移除「当前有、目标无」的文件（awk 求差集）。\n// 变更集恢复（issue #22，旧版整树 archive）：旧版 restored 是目标树全量条数，\n// 改 1 个文件也把整棵快照树解包一遍（大工作区全树 IO；实机 39.2 万条幽灵条目\n// 时 pwsh 侧实测打出 5.11 GB zip），未变更文件 mtime 全变误触发构建增量/文件\n// 监听。现用 awk 求恢复集（目标有、当前无或 sha 不同，与 diffScript 的\n// modified+restored 同集合），git archive <tag> -- <paths> 分批（100/批，与\n// pwsh 侧同款纪律）只解变更项；restored 随之变成实际恢复条数，与 preview 的\n// diff 计数逐项相等（preview 的 added=本删除侧、modified+restored=本恢复侧）。\n// 变更过半（restored*2 ≥ total）时整树一遍更优（N/100 次 archive+tar 的启动\n// 开销超过单遍），回退旧路径。空恢复集跳过 archive，只执行删除。\n// pipefail 保证 git archive 失败时整条非零退出。\n// 删除侧失败必须响亮（F-G2）：set -e 豁免 if 条件内的 rm 失败——若写成\n// `rm ... && deleted++` 裸链，rm 失败（权限等）被静默跳过、脚本仍输出\n// ROLLBACK_OK，半回退报成功、救援永不触发；改为 if/fi + 失败显式 exit 1，\n// 与 pwsh 版「EAP=Stop 下 Remove-Item 抛终止错误」对齐「删除失败即失败」\n// 的语义（见 scripts.pwsh.js rollbackScript 同位置注释）。\nexport function rollbackScript(root: string, store: ScriptStore, gitExe: string, tag: string, base: string[]): string {\n  return [\n    'set -e -o pipefail',\n    collectListsBlock(store, gitExe, root, tag, base),\n    'tmpr=' + psq(store.dir + '/diff-restore.$$'),\n    \"trap 'rm -f \\\"$tmpc\\\" \\\"$tmpt\\\" \\\"$tmpr\\\" \\\"$oversize_p\\\" \\\"$oversize_r\\\"' EXIT\",\n    // 恢复集 = 目标有、当前无或 sha 不同（awk 结构与 diffScript 同款：\n    // cur 侧 \"mode sha stage<TAB>path\" 取 a[2]，target 侧 \"mode type sha<TAB>path\" 取 a[3]）\n    'awk -F\\'\\\\t\\' \\'',\n    '  FNR==1 { fidx++ }',\n    '  fidx==1 { split($1, a, \" \"); cur[$2]=a[2]; next }',\n    '  { split($1, a, \" \"); tgt[$2]=a[3] }',\n    '  END { for (p in tgt) if (!(p in cur) || cur[p] != tgt[p]) print p }',\n    \"' \\\"$tmpc\\\" \\\"$tmpt\\\" > \\\"$tmpr\\\"\",\n    'restored=$(wc -l < \"$tmpr\" | tr -d \\' \\')',\n    'total=$(wc -l < \"$tmpt\" | tr -d \\' \\')',\n    'if [ \"$restored\" -gt 0 ]; then',\n    '  if [ $((restored * 2)) -ge \"$total\" ]; then',\n    // -m（--touch，两处 tar 调用同款）：解包不恢复归档成员的 mtime（文件\n    // mtime = 解包时刻）。必须如此：tar 默认保留归档内 mtime，而快照→篡改→\n    // 回滚常在数秒内完成，恢复出的 mtime 可能与 index 里旧条目的 stat 记录\n    // 碰撞，下一次 add -A 的 stat 缓存误判「未变更」跳过 re-hash——工作区\n    // 内容与快照从此脱钩（实测解包出篡改前内容的间歇性失败）。Windows 逐条\n    // 解压也会显式 touch，两侧语义由各自的回退冒烟测试锁定。\n    '    \"$git\" --git-dir=\"$g\" archive ' + psq(tag) + ' | tar -x -m -C \"$root\"',\n    '  else',\n    '    batch=()',\n    '    while IFS= read -r p; do',\n    '      if [ -z \"$p\" ]; then continue; fi',\n    '      batch+=(\"$p\")',\n    '      if [ \"${#batch[@]}\" -ge 100 ]; then',\n    '        \"$git\" --literal-pathspecs --git-dir=\"$g\" archive ' + psq(tag) + ' -- \"${batch[@]}\" | tar -x -m -C \"$root\"',\n    '        batch=()',\n    '      fi',\n    '    done < \"$tmpr\"',\n    '    if [ \"${#batch[@]}\" -gt 0 ]; then',\n    '      \"$git\" --literal-pathspecs --git-dir=\"$g\" archive ' + psq(tag) + ' -- \"${batch[@]}\" | tar -x -m -C \"$root\"',\n    '    fi',\n    '  fi',\n    'fi',\n    'tmpd=' + psq(store.dir + '/diff-del.$$'),\n    \"trap 'rm -f \\\"$tmpc\\\" \\\"$tmpt\\\" \\\"$tmpr\\\" \\\"$tmpd\\\" \\\"$oversize_p\\\" \\\"$oversize_r\\\"' EXIT\",\n    'awk -F\\'\\\\t\\' \\'',\n    '  FNR==1 { fidx++ }',\n    '  fidx==1 { cur[$2]=1; next }',\n    '  { tgt[$2]=1 }',\n    '  END { for (p in cur) if (!(p in tgt)) print p }',\n    \"' \\\"$tmpc\\\" \\\"$tmpt\\\" > \\\"$tmpd\\\"\",\n    'deleted=0',\n    'while IFS= read -r p; do',\n    // 循环体禁裸 && 链（AGENTS.md 已知坑同款规矩）：&& 列表条件为假时整条\n    // 退出码为 1，set -e 会把脚本杀掉；if 语句天然豁免。rm 失败必须响亮\n    // exit 1——半回退假成功会让救援永不触发（F-G2）\n    '  if [ -z \"$p\" ]; then continue; fi',\n    '  if rm -f -- \"$root/$p\"; then deleted=$((deleted + 1)); else echo \"RM_FAILED $p\" >&2; exit 1; fi',\n    'done < \"$tmpd\"',\n    'echo \"ROLLBACK_OK $deleted $restored\"'\n  ].join('\\n')\n}\n\n// 回退失败救援（H1，语义见 pwsh 版同款注释）：reset --hard 回安全快照。\n// 入参 tag 是完整 tag 名（snap- 前缀由调用侧 rescueRollback 拼齐）。\n// set -e 下 git 非零退出自然终止脚本，与 pwsh 版 $LASTEXITCODE 显式自检\n// 对齐「失败即抛」语义。\nexport function rescueScript(root: string, store: ScriptStore, gitExe: string, tag: string): string {\n  return [\n    'set -e',\n    'git=' + psq(gitExe),\n    'g=' + psq(store.git),\n    'root=' + psq(root),\n    '\"$git\" --git-dir=\"$g\" --work-tree=\"$root\" reset --hard ' + psq(tag),\n    'echo RESCUE_OK'\n  ].join('\\n')\n}\n\nexport function listTagsScript(store: ScriptStore, gitExe: string): string {\n  return [\n    'set -e',\n    'git=' + psq(gitExe),\n    'g=' + psq(store.git),\n    // 仅创建过 store 目录、尚未产生过快照时没有 git/.git；把它视为\n    // 空快照仓库而非错误，全部删除仍可顺便清空其陈旧 index.json。\n    '[ -d \"$g\" ] || exit 0',\n    '\"$git\" --git-dir=\"$g\" tag -l \\'snap-*\\''\n  ].join('\\n')\n}\n\n// 孤儿重建用 tag 清单（带 creatordate）：rebuildOrphans 据此恢复快照\n// 时间——只列 tag 名会让重建条目 time=0，管理列表时间前缀缺失、\n// retention/limits 按「最旧」误清。lightweight tag 无 tag 对象，\n// creatordate 即指向 commit 的提交日期。输出每行「<tag名> <秒级时间戳>」。\nexport function listTagsWithTimeScript(store: ScriptStore, gitExe: string): string {\n  return [\n    'set -e',\n    'git=' + psq(gitExe),\n    'g=' + psq(store.git),\n    '[ -d \"$g\" ] || exit 0',\n    '\"$git\" --git-dir=\"$g\" for-each-ref --format=\\'%(refname:short) %(creatordate:unix)\\' \\'refs/tags/snap-*\\''\n  ].join('\\n')\n}\n\n// 定期 gc（语义同 pwsh 版）；date +%s 写秒级时间戳，JS 侧 ×1000。\n// refs 空 + index 非空 = 残骸仓库（无快照可回退），index 的伪可达性让 gc 回收\n// 不掉对象库——必须先清 index；动机、实测量级与安全性论证见 pwsh 版注释。\n// 两条查询命令空结果都退出 0，不触发 set -e。\nexport function gcScript(store: ScriptStore, gitExe: string): string {\n  return [\n    'set -e',\n    'git=' + psq(gitExe),\n    'g=' + psq(store.git),\n    'if [ -z \"$(\"$git\" --git-dir=\"$g\" for-each-ref --count=1 refs)\" ] && [ -n \"$(\"$git\" --git-dir=\"$g\" ls-files)\" ]; then',\n    '  \"$git\" --git-dir=\"$g\" read-tree --empty',\n    'fi',\n    '\"$git\" --git-dir=\"$g\" gc --quiet --prune=now',\n    'date +%s > \"$g/gc.stamp\"',\n    'echo GC_OK'\n  ].join('\\n')\n}\n\n// 快照失败后的残骸清理（语义同 pwsh 版，动机详见其注释）：prune 以\n// refs + 暂存 index 为根删无引用对象，只清失败 add 的残骸、不碰 tag 快照\nexport function pruneScript(store: ScriptStore, gitExe: string): string {\n  return [\n    'set -e',\n    'git=' + psq(gitExe),\n    'g=' + psq(store.git),\n    '\"$git\" --git-dir=\"$g\" prune',\n    'echo PRUNE_OK'\n  ].join('\\n')\n}\n\n// 失败后的孤儿进程清扫 + stale 锁清理（issue #7 兜底 + issue #11 根因治理）。\n// 三级出口（M3）：\n// 1. CLEANUP_OTHER_INSTANCE <pid>——心跳文件（宿主 PID + epoch 秒）显示另一\n//    个存活实例正在使用同一快照库：直接让路，不杀进程、不动锁。这是两个\n//    DSH 实例并发互踩（一方清扫误杀另一方活跃 git → 对方也失败 → 循环）的\n//    根治；心跳由 ensureGit/snapshotScript 随操作刷新，TTL 外视为失效。\n// 2. CLEANUP_SKIPPED_FRESH_LOCK——存在 STALE_LOCK_MIN 分钟内的新锁（疑似有\n//    git 操作正在进行）：同样让路，锁陈旧后下次失败自然进入第 3 级。\n// 3. CLEANUP_DONE——两级保护均未命中，按原有行为清孤儿进程与 stale 锁。\n// POSIX 版差异：pgrep -f 按扩展正则匹配整条命令行——路径元字符（[、+ 等）\n// 会让模式失配，清扫静默失效，属安全降级（等价于本兜底加入前的行为）；\n// 标记在运行期拼接，本脚本自身命令行里只有未展开的 $g 字面量，不会自杀。\n// 全程无 set -e + 逐步容错：清扫自身的失败不能抛。mtime 判定用 find -mmin\n// 而非 stat：GNU/BSD stat 参数不同（macOS bash 3.2 约束），find 的 -mmin\n// 两平台语义一致。\nexport function killOrphansScript(gitDir: string): string {\n  return [\n    '# RECALL_CLEANUP',\n    'g=' + psq(gitDir),\n    'hbf=\"$(dirname \"$(dirname \"$g\")\")/heartbeat\"',\n    'if [ -f \"$hbf\" ]; then',\n    '  hbl=$(head -n1 \"$hbf\" 2>/dev/null | tr -d \\'\\\\r\\')',\n    '  hbp=${hbl%% *}',\n    '  hbt=${hbl#* }',\n    \"  case \\\"$hbp\\\" in ''|*[!0-9]*) hbp='' ;; esac\",\n    \"  case \\\"$hbt\\\" in ''|*[!0-9]*) hbt=0 ;; esac\",\n    '  hbage=$(( $(date +%s) - hbt ))',\n    '  if [ -n \"$hbp\" ] && [ \"$hbp\" != ' + psq(String(process.pid)) + ' ] && [ \"$hbage\" -ge 0 ] && [ \"$hbage\" -lt ' + HEARTBEAT_TTL_S + ' ]; then',\n    '    if kill -0 \"$hbp\" 2>/dev/null; then',\n    '      echo \"CLEANUP_OTHER_INSTANCE $hbp\"',\n    '      exit 0',\n    '    fi',\n    '  fi',\n    'fi',\n    \"fresh=$(find \\\"$g\\\" -maxdepth 1 -type f \\\\( -name '*.lock' -o -name 'gc.pid' \\\\) -mmin -\" + STALE_LOCK_MIN + \" 2>/dev/null; find \\\"$g/refs\\\" -type f -name '*.lock' -mmin -\" + STALE_LOCK_MIN + ' 2>/dev/null)',\n    'if [ -n \"$fresh\" ]; then',\n    '  echo CLEANUP_SKIPPED_FRESH_LOCK',\n    '  exit 0',\n    'fi',\n    'marker=\"--git-dir=$g\"',\n    'for p in $(pgrep -f -- \"$marker\" 2>/dev/null); do',\n    '  [ \"$p\" = \"$$\" ] && continue',\n    '  kill \"$p\" 2>/dev/null || true',\n    'done',\n    // 锁清单对齐 pwsh 版：index.lock 是 add/checkout 持久锁，其余是\n    // gc/tag/pack 链路残留；refs 下 per-ref 锁用 find 兜底（只删陈旧锁，\n    // 新锁已被上方分级保护拦下）\n    'rm -f \"$g/index.lock\" \"$g/config.lock\" \"$g/HEAD.lock\" \"$g/gc.pid\" \"$g/packed-refs.lock\" \"$g/shallow.lock\" 2>/dev/null || true',\n    'find \"$g/refs\" -type f -name \"*.lock\" -mmin +' + STALE_LOCK_MIN + ' -delete 2>/dev/null || true',\n    'echo CLEANUP_DONE'\n  ].join('\\n')\n}\n\n// 删除指定快照 tag（会话已删联动清理用）：tag -d 对不存在 tag 非零退出，\n// || true 吞掉——best-effort，残留 tag 由下次清理幂等收尾（同 pwsh 版）\nexport function purgeTagsScript(store: ScriptStore, gitExe: string, tags: string[]): string {\n  return [\n    'git=' + psq(gitExe),\n    'g=' + psq(store.git),\n    '\"$git\" --git-dir=\"$g\" tag -d ' + tags.map((t) => psq(t)).join(' ') + ' >/dev/null 2>&1 || true',\n    'echo PURGE_DONE'\n  ].join('\\n')\n}\n\n// 原子 rename（H2，语义见 pwsh 版同款注释）：mv -f 同卷 move 为 O(1) 元\n// 数据操作；也用于 loadIndex 把损坏索引改名 .corrupt-<ts> 保留现场。\nexport function renameFileCmd(src: string, dst: string): string {\n  return 'mv -f -- ' + psq(src) + ' ' + psq(dst)\n}\n\n// 任意长度文本写入（PF-2，语义见 pwsh 版同名注释）：stdin 传全文 + 单进程\n// 落盘。POSIX 原本就直写 stdin（cat > tmp 此前内联在 store.js，PF-2 起迁进\n// 模板统一走同名导出），bash 无编码/长度问题，模板本体就是这条 cat。\nexport function fileWriteStdinCmd(file: string): string {\n  return 'cat > ' + psq(file)\n}\n\n// 索引读取（写入走 stdin：见 snapshots.js saveIndex 的 POSIX 分支，\n// 不经命令行传参，天然没有 32767/128KB argv 上限问题）\nexport function indexReadCmd(dir: string): string {\n  return 'cat ' + psq(dir + '/index.json') + ' 2>/dev/null || true'\n}\n\n// fork lineage 读取（F1，语义见 pwsh 版同款注释）：lineage.json 与 index.json\n// 同层、原子写；缺失文件输出空串。\nexport function lineageReadCmd(dir: string): string {\n  return 'cat ' + psq(dir + '/lineage.json') + ' 2>/dev/null || true'\n}\n\n// 通用小文件读取（A3 引入）：与 pwsh 版同名同语义——任意小文件走同一形态，\n// 缺席静默回空串（调用侧按「空 = 不存在或为空」处理）。POSIX 侧 `|| true`\n// 天然把缺席的退出码压成 0；win32 侧没有这个便利，必须用 Test-Path 分支\n// 显式构造（动机与实弹经过见 pwsh 版同名注释与 compat-audit I41）。\nexport function fileReadCmd(file: string): string {\n  return 'cat ' + psq(file) + ' 2>/dev/null || true'\n}\n\n// 旧版项目内 blobs 目录清理（仅 home 存储可用时调用）\nexport function legacyRmScript(path: string): string {\n  return 'rm -rf -- ' + psq(path)\n}\n\n// exclude.txt 原文读取（设置页编辑用）：缺失文件 cat 报错走 2>/dev/null ||\n// true 吞掉输出空串——与 pwsh 版同语义，按「尚未配置」处理；写入不走\n// 模板函数，调用方直接 cat > file + stdin（同 saveIndex 的 POSIX 分支）。\nexport function excludeReadCmd(file: string): string {\n  return 'cat ' + psq(file) + ' 2>/dev/null || true'\n}\n\n// 批量读全部 exclude 文件（PF-8，语义见 pwsh 版同注释）：内容 base64 单行\n// 输出（任意文本免疫定界混淆）。GNU base64 默认 76 字符折行、BSD（macOS）\n// 不折行且无 -w——统一 base64 | tr -d '\\n' 兼容两侧；读失败输出空段。\nexport function excludeDumpScript(files: string[]): string {\n  const lines = []\n  for (const f of files || []) {\n    const q = psq(f)\n    lines.push(\n      \"printf 'EXCLBEGIN %s\\\\n' \" + q,\n      'if [ -f ' + q + ' ]; then base64 ' + q + \" 2>/dev/null | tr -d '\\\\n'; fi\",\n      // issue #30 同族：tr -d '\\n' 之后内容没有行尾，直接 echo 会把 EXCLEND 粘在\n      // base64 尾上；payload 字节数为 3 的倍数（无 '=' padding）时这截尾巴会被一起\n      // 解码成垃圾字节，回显到设置页再写回就污染 exclude.txt。\n      'printf \"\\\\n\"',\n      \"echo 'EXCLEND'\"\n    )\n  }\n  return lines.join('\\n')\n}\n\n// 目录存在探测：YES/NO 定长标记与 pwsh 版逐字同语义（容器路径本身在\n// JS 侧解析，POSIX 不需要 homeContainerScript 的 shell 版）。\nexport function dirExistsScript(dir: string): string {\n  return '[ -d ' + psq(dir) + ' ] && echo YES || echo NO'\n}\n\n// 影子仓库磁盘占用（设置页快照管理卡片用，语义同 pwsh 版）\nexport function countObjectsScript(store: ScriptStore, gitExe: string): string {\n  return [\n    'git=' + psq(gitExe),\n    'g=' + psq(store.git),\n    '\"$git\" --git-dir=\"$g\" count-objects -v'\n  ].join('\\n')\n}\n\n// 目录总大小（字节）：du -sk 取 KiB 再 ×1024；macOS/BSD du 与 GNU du\n// 对 -sk 的输出格式一致（\"大小<TAB>路径\"），awk 取首列最稳。\nexport function diskUsageScript(dir: string): string {\n  return 'du -sk ' + psq(dir) + ' 2>/dev/null | awk \\'{print $1 * 1024}\\''\n}\n\n// 列目录下所有一级子目录全路径：manage/list 枚举 home 容器下的所有\n// 哈希子目录用（每个子目录是一个工作区的 store）。find -maxdepth 1\n// 限定深度避免递归，2>/dev/null 容忍个别不可读条目。\nexport function listSubdirsScript(dir: string): string {\n  return 'find ' + psq(dir) + ' -maxdepth 1 -mindepth 1 -type d 2>/dev/null'\n}\n\n// 批量 dump 全部 store 元数据（与 pwsh 版 storesDumpScript 同格式、\n// 同语义，见其注释）：一条 shell 拿全部目录的 STATE + root.txt + index.json +\n// lineage.json（PF-4；STATE 为 issue #30 遗留的空仓回收判据）。\n// bash 3.2 兼容：数组 + += 均可用，glob 无匹配时字面量经 [ -d ] 过滤。\n// root.txt 经 tr 去掉可能的 CRLF 再拼单行，防标记结构被打乱。\nexport function storesDumpScript(container: string, extraDirs: string[]): string {\n  const lines = ['set -e', 'dirs=()']\n  if (container) {\n    lines.push('base=' + psq(container))\n    lines.push('if [ -d \"$base\" ]; then')\n    lines.push('  for d in \"$base\"/*/; do')\n    // if 而不是 [ ] && ：glob 无匹配时条件为假，&& 链返回非零会触发 set -e\n    lines.push('    if [ -d \"$d\" ]; then dirs+=(\"${d%/}\"); fi')\n    lines.push('  done')\n    lines.push('fi')\n  }\n  for (const d of extraDirs || []) lines.push('dirs+=(' + psq(d) + ')')\n  lines.push(\n    'for d in \"${dirs[@]}\"; do',\n    '  [ -d \"$d\" ] || continue',\n    '  echo \"==DIR $d\"',\n    // STATE 供空仓回收判定（present/absent/quarantined/foreign）：判据留在\n    // 脚本侧是因为只有这里能看文件系统——absent 表示「从没拍过快照的真仓」\n    // （git/ 或 root.txt 在），foreign 表示不是我们的目录，两者不能混。\n    '  if [ -f \"$d/index.json\" ]; then',\n    \"    echo 'STATE present'\",\n    '  elif ls \"$d\"/index.json.corrupt-* >/dev/null 2>&1; then',\n    \"    echo 'STATE quarantined'\",\n    '  elif [ -d \"$d/git\" ] || [ -f \"$d/root.txt\" ]; then',\n    \"    echo 'STATE absent'\",\n    '  else',\n    \"    echo 'STATE foreign'\",\n    '  fi',\n    '  if [ -f \"$d/root.txt\" ]; then',\n    '    printf \"ROOT %s\\\\n\" \"$(cat \"$d/root.txt\" 2>/dev/null | tr -d \\'\\\\r\\\\n\\')\"',\n    '  else',\n    '    echo \"ROOT \"',\n    '  fi',\n    '  echo INDEXBEGIN',\n    // issue #30：这两个 json 是可选文件（刚建仓没拍过快照就没有），缺席必须放行——\n    // set -e 下裸 cat 会把「无文件」升级成整条 dump 失败。另外落盘内容无尾换行\n    // （writeTextViaShell = cat > file），cat 后紧接 echo 会把段尾标记粘到内容行尾，\n    // JS 侧按整行匹配 INDEXEND 就永远收不到段尾，所以内容后显式补一个换行。\n    '  cat \"$d/index.json\" 2>/dev/null || true',\n    '  printf \"\\\\n\"',\n    '  echo INDEXEND',\n    '  echo LINEAGEBEGIN',\n    '  cat \"$d/lineage.json\" 2>/dev/null || true',\n    '  printf \"\\\\n\"',\n    '  echo LINEAGEEND',\n    'done',\n    'exit 0'\n  )\n  return lines.join('\\n')\n}\n"
    },
    {
      "path": "src/host/snapshots.ts",
      "content": "/**\n * dsh-recall-plugin — 快照域（ctx 绑定的工厂，无模块级副作用）\n *\n * 职责：快照捕获（captureSnapshot）、索引落盘/载入/孤儿重建、\n * diff 清单（diffFor）、回退执行（rollbackFor）、会话切点解析\n * （resolveCutSeq）。依赖 store.js 的执行与存储层，脚本文本全部\n * 来自 rt.scripts（按平台选择的 scripts.pwsh.js / scripts.posix.js）。\n */\n\nimport * as E from './errors.js'\nimport { buildFeedbackError } from './diagnostics.js'\nimport { buildArtifactRootSegment } from './exclude-patterns.js'\nimport type { Runtime, StoreInfo, SnapshotInfo } from '../types/state.js'\nimport type { SnapshotFeedback, LineageEntry, IndexEntry } from '../types/payloads.js'\nimport type { HostContext, SessionEvent, SessionQueryEngine } from '../types/dsh-contract.js'\nimport type { ResolvedConfig } from '../types/config.js'\nimport type { ErrorCode, DiffChange } from '../types/api.js'\nimport type { PwshScripts, PosixScripts } from '../types/scripts.js'\n\n// ---- 纯逻辑（模块级导出，供 tests/unit 直接钉住；工厂内沿用同一实现）----\n\n// 脚本侧 fail-open 跳过的路径（--ignore-errors 下无法索引的目录，如无\n// 提交的嵌入式仓库）以「SNAP_SKIP <path>」行回传：这些路径不进快照，\n// 撤回时既不恢复也不会被删，用户应当知道快照少了什么。\nexport function parseSkipped(out: unknown): string[] {\n  const skipped: string[] = []\n  for (const line of String(out || '').split(/\\r?\\n/)) {\n    if (line.indexOf('SNAP_SKIP ') === 0) skipped.push(line.slice('SNAP_SKIP '.length))\n  }\n  return skipped\n}\n\n// issue #24：快照前置护栏标记。脚本在 add 之前遍历工作区统计「纳入总量」与\n// 耗时，任一超限输出「SNAP_LIMIT <bytes|time> <实测> <上限>」后退出（不建\n// 快照）。旧脚本无该行 → 返回 null，走原成功路径（升级期兼容）。\n// issue #29：'scan' 不是脚本的 SNAP_LIMIT 输出，而是 host 把「统计失败」\n// （SNAP_SCAN_FAIL）折成同一形状——两者都要走「停用该工作区 + 反馈」通道，\n// 共用 TTL/配置变化重试逻辑，value 此时是 git 退出码、limit 恒 0。\nexport interface SnapshotLimit {\n  kind: 'bytes' | 'time' | 'scan'\n  value: number\n  limit: number\n}\n\nexport function parseSnapshotLimit(out: unknown): SnapshotLimit | null {\n  for (const line of String(out || '').split(/\\r?\\n/)) {\n    if (line.indexOf('SNAP_LIMIT ') !== 0) continue\n    const parts = line.slice('SNAP_LIMIT '.length).trim().split(/\\s+/)\n    const kind = parts[0]\n    if (kind !== 'bytes' && kind !== 'time') continue\n    const value = parseInt(parts[1] ?? '', 10)\n    const limit = parseInt(parts[2] ?? '', 10)\n    if (!Number.isFinite(value) || !Number.isFinite(limit)) continue\n    return { kind, value, limit }\n  }\n  return null\n}\n\n// issue #29：预算扫描失败的哨兵（ls-files 非零退出）。与 SNAP_LIMIT 同为\n// 「本次不建快照」通道，区别是规模未知——一律按停用处理，绝不放行 add。\n// 旧脚本无这两行 → 返回 null，走原成功路径（升级期兼容）。\nexport interface ScanFail {\n  rc: number\n  message: string\n}\n\nexport function parseScanFail(out: unknown): ScanFail | null {\n  let rc: number | null = null\n  let message = ''\n  for (const line of String(out || '').split(/\\r?\\n/)) {\n    // 前缀长度含尾随空格：SNAP_SCAN_FAIL = 15、SNAP_SCAN_ERR = 14\n    if (line.indexOf('SNAP_SCAN_FAIL ') === 0) {\n      const n = parseInt(line.slice(15).trim(), 10)\n      if (Number.isFinite(n)) rc = n\n    } else if (line.indexOf('SNAP_SCAN_ERR ') === 0) {\n      message = line.slice(14).trim()\n    }\n  }\n  return rc === null ? null : { rc, message }\n}\n\n// 字节数的可读文本：≥1MB 用 MB，更小用 KB（避免「0 MB / 0 MB」这种\n// 测试态/小工作区下无信息的文案）\nfunction bytesText(bytes: number): string {\n  if (bytes >= 1048576) return Math.round(bytes / 1048576) + ' MB'\n  return Math.max(1, Math.round(bytes / 1024)) + ' KB'\n}\n\n// 停用说明（snapFeedback.error 直显 + 最近错误同文案）：≤140 字符、给出\n// 可行动的出口（调大对应上限或补充排除表），修好后下一次快照自动恢复。\n// 字节口径必须写明「已按 .gitignore 与排除表过滤」（issue #28）：不写会让人\n// 以为工作区真的这么大，进而去调大上限——那反而把 gitignore 里的垃圾真的收进\n// 对象库，与该护栏的初衷相反。\nexport function buildSnapshotLimitNotice(limit: SnapshotLimit): string {\n  if (limit.kind === 'scan') {\n    // 不嵌 stderr（含路径必被 140 字符截断成残句）：原因由「最近错误」承载\n    return '无法统计该工作区的快照范围（git 退出码 ' + limit.value + '），本次快照已跳过；该工作区暂停快照约 10 分钟，修复后自动恢复，详情见「最近错误」'\n  }\n  if (limit.kind === 'bytes') {\n    return '该工作区可纳入快照的文件总量超过上限（约 ' + bytesText(limit.value) + ' / ' + bytesText(limit.limit) + '，已按 .gitignore 与排除表过滤），已停用快照；可调大「工作区总量上限」或补充排除表后自动恢复'\n  }\n  return '快照前的文件扫描超过时间预算（约 ' + Math.max(1, Math.round(limit.value / 1000)) + ' 秒 / ' + Math.max(1, Math.round(limit.limit / 1000)) + ' 秒），已停用快照；可调大「扫描时间预算」或补充排除表后自动恢复'\n}\n\n// POSIX 侧 diff 输出是 TSV「kind<TAB>path」逐行（bash 模板不拼 JSON，\n// 避免 jq 依赖与转义坑）；win32 侧是 ConvertTo-Json。这里按平台分叉解析。\nexport function parseChanges(text: string, isWin: boolean): DiffChange[] {\n  if (isWin) {\n    const parsed = JSON.parse(text)\n    if (Array.isArray(parsed)) return parsed\n    if (parsed && typeof parsed === 'object') return [parsed]\n    return []\n  }\n  const out: DiffChange[] = []\n  for (const line of text.split(/\\r?\\n/)) {\n    if (!line) continue\n    const tab = line.indexOf('\\t')\n    if (tab < 0) continue\n    out.push({ kind: line.slice(0, tab), rel: line.slice(tab + 1) })\n  }\n  return out\n}\n\n// PF-1：snapshotScript 输出中的 TREE 行（add -A 后的 index 树指纹）。\n// execute 拿安全快照输出的指纹与 preview 指纹比对判 STALE；无该行的旧输出\n// （脚本/Host 版本错位的理论场景）返回 null，调用侧跳过指纹校验。\nexport function parseTreeId(out: unknown): string | null {\n  for (const line of String(out || '').split(/\\r?\\n/)) {\n    if (line.indexOf('TREE ') === 0) return line.slice(5).trim() || null\n  }\n  return null\n}\n\n// PF-1：diff 输出统一解析。脚本侧协议（见 scripts.*.js diffScript 注释）：\n// win32 输出「COUNTS m r a」/「TOTAL <n>」/「前 maxChanges 条 JSON」/「TREE」；\n// POSIX 输出 TSV 逐行 + 末行「TREE <hash>」。标记行必须先剥离再交给\n// parseChanges——win32 分支对整段文本 JSON.parse，标记行混入直接抛错。\n// total 语义不变（全量条数）：win32 由 TOTAL 行回传（截断前移脚本侧），\n// POSIX 无 TOTAL 行则取解析条数（不截断）。treeId 为 index 树指纹。\n// counts 必须覆盖全量：清单截断到 maxChanges 条，按清单统计的分类数会与\n// total 打架（实测 3054 条只报「修改 448」）。拿不到可信全量计数时置 null，\n// 面板据 null 隐去摘要——比展示一个错数字更诚实。\nexport interface DiffCounts {\n  modified: number\n  restored: number\n  added: number\n}\nexport interface DiffResult {\n  changes: DiffChange[]\n  total: number\n  truncated: boolean\n  treeId: string | null\n  counts: DiffCounts | null\n}\nfunction countChanges(list: DiffChange[]): DiffCounts {\n  const counts: DiffCounts = { modified: 0, restored: 0, added: 0 }\n  for (const c of list) {\n    if (c && Object.prototype.hasOwnProperty.call(counts, String(c.kind))) counts[c.kind as keyof DiffCounts]++\n  }\n  return counts\n}\n// COUNTS 行的三段必须都是非负整数才采信：任一损坏即视为缺席，避免把半截\n// 输出当计数（进而与 total 对不上）\nfunction parseCounts(line: string): DiffCounts | null {\n  const parts = line.trim().split(/\\s+/)\n  if (parts.length !== 3) return null\n  const m = parseInt(parts[0] ?? '', 10)\n  const r = parseInt(parts[1] ?? '', 10)\n  const a = parseInt(parts[2] ?? '', 10)\n  if (!Number.isFinite(m) || !Number.isFinite(r) || !Number.isFinite(a)) return null\n  if (m < 0 || r < 0 || a < 0) return null\n  return { modified: m, restored: r, added: a }\n}\nexport function parseDiffOutput(text: string, isWin: boolean, maxChanges: number): DiffResult {\n  const lines = String(text || '').split(/\\r?\\n/)\n  let total: number | null = null\n  let treeId: string | null = null\n  let counts: DiffCounts | null = null\n  const body: string[] = []\n  for (const line of lines) {\n    if (line.indexOf('TREE ') === 0) { treeId = line.slice(5).trim() || null; continue }\n    if (line.indexOf('COUNTS ') === 0) { counts = parseCounts(line.slice(7)); continue }\n    if (line.indexOf('TOTAL ') === 0) {\n      const n = parseInt(line.slice(6), 10)\n      if (Number.isFinite(n) && n >= 0) total = n\n      continue\n    }\n    body.push(line)\n  }\n  const raw = body.join('\\n').trim()\n  const all = raw ? parseChanges(raw, isWin) : []\n  const finalTotal = total !== null ? total : all.length\n  const changes = all.slice(0, maxChanges)\n  const truncated = finalTotal > changes.length\n  // 解析到的条数覆盖 total ⇒ 本地统计等价全量（POSIX 从不截断、win32 未超限）；\n  // 覆盖不了（win32 脚本侧已截断）就只有 COUNTS 行可信，缺席即 null\n  const complete = all.length >= finalTotal\n  return { changes, total: finalTotal, truncated, treeId, counts: counts || (complete ? countChanges(all) : null) }\n}\n\n// 扫描结果的完整形态：cut 为切点 seq，found 为事件序列里是否存在该消息。\n// 「消息不存在」（读取面缺了 fork 继承前缀等）与「消息在、但其前无 turn/end」\n// （真·首条）在数值上都折成 null；读取路径的降级判断必须区分二者，故单列 found。\nexport interface CutSeqScan {\n  cut: number | null\n  found: boolean\n}\n\n// 在事件序列里找“该消息之前最近一次 turn/end 的 seq”。\nexport function scanCutSeqDetail(events: SessionEvent[], messageId: string): CutSeqScan {\n  let anchor = -1\n  for (let i = 0; i < events.length; i++) {\n    const e = events[i]\n    if (e && e.type === 'user/message' && e.data && String(e.data.id) === String(messageId)) {\n      anchor = i\n      break\n    }\n  }\n  if (anchor < 0) return { cut: null, found: false }\n  for (let i = anchor - 1; i >= 0; i--) {\n    const e = events[i]\n    if (e && e.type === 'turn/end' && typeof e.seq === 'number') return { cut: e.seq, found: true }\n  }\n  return { cut: null, found: true }\n}\n\nexport function scanCutSeq(events: SessionEvent[], messageId: string): number | null {\n  return scanCutSeqDetail(events, messageId).cut\n}\n\n// 扫描 fork 切点窗口内入队的用户消息，取出其 item id。\n//\n// 官方 fork 的切点是「boundary 那条 turn/end 之后、下一个 turn/start 之前」\n// 的整段事件（routes-core 把 resolveCutSeq 的返回值当 atSeq 传下去）。一条\n// 排队投递的用户消息，其 inbox 入队事件必然落在「上一个 turn/end」与「领取\n// 它的那个 turn/start」之间——正好是这个窗口。于是这段入队记录被复制进子\n// 会话 seed，子会话重建 inbox 后输入框上方就多出一条本该被撤回掉的排队消息；\n// 子会话被驱动时该入队项还会被当作真实一轮消费。\n//\n// 取 item id 而非 rpcId：id 就是那条消息的 message id，也正是官方\n// updateQueue 的寻址键（0.1.5-rc.1 实测——直删返回 accepted，重复删返回\n// queue-item-not-found）。Client 拿到子会话 id 后按这些 id 直删，不读队列\n// 快照、不做匹配；rpcId 匹配依赖队列帧到达时机，实测 30 秒窗口内可整段落空。\nexport function scanStaleQueueItemIds(events: SessionEvent[], cutSeq: number | null): string[] {\n  if (!Array.isArray(events)) return []\n  if (typeof cutSeq !== 'number' || !Number.isFinite(cutSeq)) return []\n  const out: string[] = []\n  for (const e of events) {\n    if (!e || typeof e.seq !== 'number' || e.seq <= cutSeq) continue\n    // 窗口在下一个 turn/start 处闭合，与 fork 的 cut 推进规则一致；窗口内\n    // 没有 turn/start（切点之后就是末尾）时自然扫到事件结束。\n    if (e.type === 'turn/start') break\n    if (e.type !== 'agent/inbox/spliced') continue\n    const inserted = e.data && Array.isArray(e.data.inserted) ? e.data.inserted : []\n    for (const item of inserted) {\n      const source = item && item.source\n      if (!source || source.kind !== 'user') continue\n      const id = item.id\n      if (typeof id === 'string' && id !== '' && out.indexOf(id) < 0) out.push(id)\n    }\n  }\n  return out\n}\n\n// 读一个 live 会话的内存事件：0.1.5-rc.1 起会话对象暴露 snapshotEvents()，\n// events 是旧版字段。两者都探测，都拿不到返回 null——调用侧据此落磁盘降级链。\nfunction liveEventsOf(live: { snapshotEvents?(): SessionEvent[]; events?: SessionEvent[] } | undefined): SessionEvent[] | null {\n  if (!live) return null\n  if (typeof live.snapshotEvents === 'function') {\n    const events = live.snapshotEvents()\n    if (Array.isArray(events)) return events\n  }\n  return Array.isArray(live.events) ? live.events : null\n}\n\n// 释放 sessionQuery 观测租约。官方在租约对象上装 Symbol.dispose（prepared 缓存\n// 项靠它减引用，漏释放会卡住淘汰）；tsconfig 为 ES2022、无该符号的类型，运行时\n// 探测即可——旧版服务/旧 Node 无该符号时静默跳过。\nfunction disposeLease(lease: unknown): void {\n  const disposeSymbol = (Symbol as unknown as { dispose?: symbol }).dispose\n  if (!disposeSymbol || lease === null || typeof lease !== 'object') return\n  const dispose = (lease as Record<symbol, unknown>)[disposeSymbol]\n  if (typeof dispose === 'function') (dispose as () => void).call(lease)\n}\n\n// H1：回退失败后的救援编排（模块级纯逻辑，deps 注入副作用，供单测钉三分支）。\n// rollbackFor 失败（partial=true，工作区可能半回退）时，execute 已先打下\n// pre-rollback-<ts> 安全快照（见 index.js）；snapshotScript 打 tag 无条件加\n// snap- 前缀，实际 tag 名是 snap-pre-rollback-<ts>——这里在调用侧拼出完整\n// tag 再传给 rescueScript（F-S1：前缀知识留在唯一知道 safetyId 语义的编排\n// 层，rescueScript 保持通用只接受完整 tag 名）。rescue 本身幂等：即使\n// rollback 实际未动工作区，reset 到安全快照也只是把工作区恢复成回退前\n// （≈当前）状态。无安全快照（safety 快照当时失败）时退化为现状 fail-loud，\n// 不静默。\nexport interface RescueDeps {\n  runShell(cmd: string, opts?: { timeoutMs?: number; stdoutMaxBytes?: number }): Promise<string>\n  scripts: PwshScripts | PosixScripts\n  gitExe: string\n  recordError(text: string): void\n}\nexport interface RescueOpts {\n  root: string\n  store: StoreInfo\n  safetyId: string\n  safetyOk: boolean\n  rollbackError?: string\n}\nexport async function rescueRollback(deps: RescueDeps, opts: RescueOpts): Promise<{ ok: false; code: ErrorCode; message: string }> {\n  const { root, store, safetyId, safetyOk, rollbackError } = opts\n  const reason = String(rollbackError || '未知原因')\n  if (!safetyOk) {\n    deps.recordError('recall rollback failed, no rescue snapshot: ' + reason)\n    return { ok: false, code: E.RECALL_ROLLBACK_FAILED, message: '回退失败：' + reason + '（无可用安全快照，工作区可能处于半回退状态）' }\n  }\n  const tag = 'snap-' + safetyId\n  // 手动恢复命令供用户复制执行：路径加引号让含空格的工作区路径可直接跑，\n  // 目标与 rescueScript 同用完整 tag 名（两条路必须指向同一个快照）。\n  const manual = 'git --git-dir=\"' + store.git + '\" --work-tree=\"' + root + '\" reset --hard ' + tag\n  try {\n    const out = await deps.runShell(deps.scripts.rescueScript(root, store, deps.gitExe, tag), { timeoutMs: 600000, stdoutMaxBytes: 65536 })\n    // RESCUE_OK 哨兵校验（与 rollbackFor 的 ROLLBACK_OK 对称）：pwsh 对\n    // native 非零退出不抛，脚本模板里虽有 $LASTEXITCODE 显式 throw 兜底，\n    // 但「脚本跑完、git 静默未生效」的假成功只能靠哨兵识别——哨兵缺失按\n    // 救援失败处理，走手动命令分支，不静默。\n    if (String(out || '').indexOf('RESCUE_OK') < 0) throw new Error('rescue 脚本未输出 RESCUE_OK 哨兵')\n    deps.recordError('recall rollback failed, rescued to safety tag: ' + tag + ' — ' + reason)\n    return { ok: false, code: E.RECALL_ROLLBACK_FAILED, message: '回退失败：' + reason + '；已自动恢复到回退前的安全快照，请重新预览后重试' }\n  } catch (rescueError) {\n    // rescueError 是 catch 的 unknown，message 字段按 Error 形状断言读取\n    const re = rescueError as { message?: string } | null | undefined\n    const rescueReason = String(re && re.message ? re.message : rescueError)\n    deps.recordError('recall rollback failed and rescue failed: ' + tag + ' — ' + reason + ' | rescue: ' + rescueReason)\n    return { ok: false, code: E.RECALL_ROLLBACK_FAILED, message: '回退失败：' + reason + '；自动恢复也失败，请手动执行：' + manual }\n  }\n}\n\n// F-G1：safety 快照 id 识别（模块级纯逻辑，rebuildOrphans 与 manage list\n// 共用同一谓词）。安全 tag 是回退前自动打下的救援锚点（pre-rollback-<ts>，\n// 见 routes-core.js execute），不是消息快照——不进索引、不在列表展示。\n// 消息 ID 为系统生成 GUID，前缀碰撞概率为零（plan-competitor-fixes F-G1 风险节）。\nexport function isSafetySnapshotId(id: unknown): boolean {\n  return typeof id === 'string' && id.indexOf('pre-rollback-') === 0\n}\n\n// listTagsWithTimeScript 输出解析（模块级纯逻辑，便于单测）：每行\n// 「<tag名> <秒级时间戳>」，for-each-ref 的 refname 不含空格、时间戳\n// 恒为行尾整数。时间解析失败/缺省回退 null——调用方以 0 兜底（保留\n// 旧「无时间」行为），绝不因格式漂移丢 tag。\nexport function parseTagsWithTime(text: unknown): Array<{ name: string; time: number | null }> {\n  const out: Array<{ name: string; time: number | null }> = []\n  for (const line of String(text || '').split(/\\r?\\n/)) {\n    const t = line.trim()\n    if (!t) continue\n    const sp = t.lastIndexOf(' ')\n    const name = sp > 0 ? t.slice(0, sp) : t\n    const ts = sp > 0 ? parseInt(t.slice(sp + 1), 10) : NaN\n    out.push({ name, time: Number.isFinite(ts) && ts > 0 ? ts * 1000 : null })\n  }\n  return out\n}\n\n// A3 格式 marker 判定（纯逻辑，模块级导出供单测）：把 <store>/format 的\n// 原文（或读取失败）折成「放行/拒写 + 原因」。marker 语义：缺席（空串）视为\n// 1——历史 store 从未写过该文件；合法版本号从 1 起（「0」按损坏处理，格式号\n// 没有 0）；非整数内容与读取失败（raw 传 null）都按损坏：fail-closed，宁停\n// 勿混——旧代码把新格式 store 当旧格式重写即数据破坏。读取失败由调用侧\n// 「不缓存、每次重试」兜底，不会把环境性故障钉死成永久拒写。\nexport type StoreFormatReason = 'ok' | 'absent' | 'future' | 'corrupt' | 'unreadable'\nexport interface StoreFormatVerdict {\n  ok: boolean\n  v: number | null\n  reason: StoreFormatReason\n}\nexport function judgeStoreFormat(raw: unknown, supported: number): StoreFormatVerdict {\n  if (raw === null) return { ok: false, v: null, reason: 'unreadable' }\n  const t = String(raw == null ? '' : raw).trim()\n  let v: number\n  if (!t) {\n    v = 1 // 缺席 = 视为 v1\n  } else {\n    if (!/^\\d+$/.test(t)) return { ok: false, v: null, reason: 'corrupt' }\n    v = parseInt(t, 10)\n    if (v < 1) return { ok: false, v: null, reason: 'corrupt' }\n  }\n  if (v > supported) return { ok: false, v, reason: 'future' }\n  return { ok: true, v, reason: t ? 'ok' : 'absent' }\n}\n\n// ---- 配置工厂 ----\n\nexport interface SnapshotsApi {\n  saveIndex(root: string, sessionId: string | null): Promise<void>\n  loadIndex(root: string, sessionId: string | null): Promise<void>\n  readExclude(store: StoreInfo): Promise<string>\n  writeExclude(store: StoreInfo, text: string): Promise<void>\n  rebuildOrphans(root: string, sessionId: string | null): Promise<void>\n  captureSnapshot(sessionId: string, messageId: string, time?: number): Promise<void>\n  diffFor(messageId: string): Promise<DiffResult | null>\n  rollbackFor(messageId: string): Promise<RollbackResult>\n  resolveCutSeq(sessionId: string | null, messageId: string | null): Promise<number | null>\n  resolveStaleQueueItemIds(sessionId: string | null, cutSeq: number | null): Promise<string[]>\n  feedbackFor(sessionId: string | null | undefined, messageId: string): Promise<SnapshotFeedback | {}>\n  loadLineage(root: string): Promise<LineageEntry[]>\n  recordLineage(root: string, childId: string, parentId: string): Promise<void>\n  // A3 格式守卫：写路径统一先过它（execute/maintenance/manage 的删除流在\n  // 各自 tag 清理动作前调用；capture/loadIndex/saveIndex/recordLineage 内部已挂）\n  guardStoreFormat(store: StoreInfo): Promise<boolean>\n}\n\n// 回退结果判别联合：成功恒带 count；失败带 error（可能半回退 partial）\nexport type RollbackResult =\n  | { ok: true; count: number }\n  | { ok: false; error: string; partial?: boolean }\n\nexport function createSnapshots(ctx: HostContext, rt: Runtime, config: ResolvedConfig): SnapshotsApi {\n  const sessions = ctx.sessions\n  const state = rt.state\n  // 平台选择的脚本模板（rt.scripts = scripts.pwsh.js / scripts.posix.js）：\n  // 两套导出同名接口但实现分属 pwsh/bash，所有调用统一走 S.*\n  const S = rt.scripts\n  // 基础排除表随调用透传给脚本模板（用户 config 可调，即时生效）\n  // 运行时读取而非创建时快照：设置卡片热更新 baseExcludes 后，\n  // 下一次快照/diff/回退立即按新排除表执行\n  const BASE = (): string[] => config.baseExcludes\n\n  // 连续失败熔断（issue #7）：失败快照的重试既无谓地全量扫描工作区，\n  // 又持续写入无 tag 可达的残骸对象（实测一个下午 127GB）。连续\n  // FUSE_AFTER 次失败后按 BASE 起步、指数翻倍、CAP 封顶的退避跳过\n  // 快照——冷却期内的消息不产生快照点，换来磁盘与 CPU 止血；冷却期满\n  // 自动重试，成功一次即全部复位，用户修好环境（如补排除配置）后\n  // 无需任何手动干预。\n  const FUSE_AFTER = 3\n  const FUSE_BACKOFF_BASE_MS = 5 * 60 * 1000\n  const FUSE_BACKOFF_CAP_MS = 60 * 60 * 1000\n  // issue #29：分钟级失败视为「昂贵失败」——它多半是规模或环境问题而非偶发\n  // 抖动，免费重试两次的代价（每条消息再付分钟级 + GB 级写入）远超收益\n  const EXPENSIVE_FAIL_MS = 60 * 1000\n  const snapFailures = new Map()\n\n  // issue #24：护栏停用记录（root → 判定结果 + 触发时的配置值 + 时间）。\n  // 为什么要在 JS 侧短路：判定本身要全量遍历一次工作区，每条消息都付一次\n  // 就等于没修——停用期间直接跳过。失效条件有两条：配置值变化（用户调大\n  // 上限/预算）立即可重试；TTL 到期（用户靠补充 exclude.txt 修复时配置\n  // 值没变）最多 10 分钟自动重试一次，重试仍超限就重新记录。\n  const SNAP_LIMIT_RETRY_MS = 10 * 60 * 1000\n  const snapLimits = new Map<string, SnapshotLimit & { at: number; maxWorkspaceBytes: number; scanBudgetMs: number }>()\n  const limitBlockedAt = new Map<string, number>()\n\n  // 停用记录（超限/统计失败共用）：触发时的配置值一并存下，配置变化即可重试\n  function markSnapshotLimited(root: string, limit: SnapshotLimit): void {\n    snapLimits.set(root, { ...limit, at: Date.now(), maxWorkspaceBytes: config.maxWorkspaceBytes, scanBudgetMs: config.scanBudgetMs })\n  }\n\n  // 停用类 recordError 的 5 分钟节流：停用期内每条消息都走同一分支，\n  // 逐条记录会把最近错误环刷成同一条（与 quarantineErrorThrottled 同款纪律）\n  function noteSnapshotBlocked(root: string, detail: string): void {\n    const last = limitBlockedAt.get(root) || 0\n    if (Date.now() - last < 5 * 60 * 1000) return\n    limitBlockedAt.set(root, Date.now())\n    rt.recordError(detail)\n  }\n\n  // ---- A3：磁盘格式版本守卫 ----\n  // 补「新读旧」方向的防线：读取侧字段全部可选化只解决旧插件读新格式；\n  // 降级安装读到更高版本格式时行为未定义。per-store format marker：高版本/\n  // 损坏拒写放行读（fail-closed，宁停勿混），低版本（含缺席=1）照常读写。\n  const SUPPORTED_FORMAT = 1\n  // 确认缓存 TTL：marker 在场且为支持版本时短期免读（稳态零额外进程），\n  // 30s 对齐 index.ts excludeCache 的既有先例\n  const FORMAT_OK_TTL_MS = 30000\n  // store.dir -> 确认时刻：只记肯定结果（读到合法 marker），拒写/读失败/\n  // 缺席都不缓存 → 每次重试自愈（改回 marker 立即恢复，不等缓存过期）\n  const formatOkAt = new Map<string, number>()\n  // 拒写告警节流（每 store 5min 一条）：被拒的写路径每条消息都会经过，\n  // 不节流会把最近错误环刷满（与 quarantineErrorThrottled 同款纪律）\n  const formatBlockedAt = new Map<string, number>()\n\n  function formatFile(store: StoreInfo): string {\n    return store.dir + (rt.isWin ? '\\\\' : '/') + 'format'\n  }\n\n  // marker 读取：null 表示读命令失败（shell 未就绪等），交判据按不可读处理\n  async function readFormatRaw(store: StoreInfo): Promise<string | null> {\n    try {\n      return S.stripBom(await rt.runShell(S.fileReadCmd(formatFile(store)), { stdoutMaxBytes: 4096 }))\n    } catch (error) {\n      // 读失败按「不可读」交判据（fail-closed）；不缓存 → 下一条消息重试\n      return null\n    }\n  }\n\n  async function storeFormatVerdict(store: StoreInfo): Promise<StoreFormatVerdict> {\n    const at = formatOkAt.get(store.dir)\n    if (at !== undefined && Date.now() - at < FORMAT_OK_TTL_MS) return { ok: true, v: SUPPORTED_FORMAT, reason: 'ok' }\n    const verdict = judgeStoreFormat(await readFormatRaw(store), SUPPORTED_FORMAT)\n    // 只缓存「在场且受支持」；缺席留给补戳后再缓存（见 stampStoreFormat）\n    if (verdict.ok && verdict.reason === 'ok') formatOkAt.set(store.dir, Date.now())\n    return verdict\n  }\n\n  function formatBlockedThrottled(store: StoreInfo, verdict: StoreFormatVerdict): void {\n    const last = formatBlockedAt.get(store.dir) || 0\n    if (Date.now() - last < 5 * 60 * 1000) return\n    formatBlockedAt.set(store.dir, Date.now())\n    // 文案按原因三分：future=升级出口；corrupt=文件内容问题（可行动：改回 1）；\n    // unreadable=读不到（多为环境未就绪——shell/subprocess 在宿主启动早期不可用，\n    // 2026-09-30 实弹：headless 宿主预热期即命中）。三分而不是合并成\n    // 「不可读或内容非法」的原因：把环境抖动说成「标记损坏」会让用户去翻一个\n    // 根本没有问题的文件（误导），且它其实每次调用都会重试、下一条消息自愈。\n    // 文案纪律同前：≤140 字符、不嵌长路径。\n    const detail = verdict.reason === 'future'\n      ? '磁盘格式标记为 v' + verdict.v + '（本插件支持 v' + SUPPORTED_FORMAT + '）：写入已暂停（快照/撤回/清理），列表仍可查看；请升级插件'\n      : verdict.reason === 'corrupt'\n        ? '磁盘格式标记内容非法（应为 ' + SUPPORTED_FORMAT + '）：写入已暂停（快照/撤回/清理）；请检查该 store 目录下的 format 文件'\n        : '读不到快照库的磁盘格式标记（环境未就绪或文件不可读）：本次写入已暂停，下一条消息自动重试；持续出现请检查该 store 目录权限'\n    rt.recordError('recall store format blocked: ' + detail)\n  }\n\n  // 写路径守卫（A3）：返回 false 即拒写（已按节流 recordError 告警）。\n  async function guardStoreFormat(store: StoreInfo): Promise<boolean> {\n    const verdict = await storeFormatVerdict(store)\n    if (verdict.ok) return true\n    formatBlockedThrottled(store, verdict)\n    return false\n  }\n\n  // marker 补戳（挂在 saveIndex 写入路径）：缺席才写，稳态零额外进程——\n  // 建库（ensureGit）后的首次 index 写入自然覆盖新 store，老 store 在下次\n  // 写索引时自愈补齐；在 index 落盘前补戳（先立格式再落内容，中途崩溃时\n  // marker 已在，老索引 + v1 marker 无害）。写失败不阻断（索引照常落盘），\n  // 因未缓存确认而在下一条消息重试。\n  async function stampStoreFormat(store: StoreInfo, verdict: StoreFormatVerdict): Promise<void> {\n    if (!verdict.ok || verdict.reason !== 'absent') return\n    try {\n      await rt.writeTextViaShell(formatFile(store), String(SUPPORTED_FORMAT))\n      formatOkAt.set(store.dir, Date.now())\n    } catch (error) {\n      // 补戳失败已告警、不阻断；下条消息重试\n      rt.recordError('recall format stamp failed: ' + String(error))\n    }\n  }\n\n  // 索引落盘：任意长度文本统一走 rt.writeTextViaShell（win32 base64\n  // 分块 / POSIX stdin，实现见 store.js）——saveIndex 与 writeExclude\n  // 曾逐字重复这套平台分叉，改一处漏一处的风险随合并消失。\n  async function saveIndex(root: string, sessionId: string | null): Promise<void> {\n    const store = state.stores.get(root)\n    if (!store) return\n    // A3：格式守卫——高版本/损坏时索引写整体短路（tag/内存删除侧在各自\n    // 入口先行守卫，见 maintenance 与 routes-manage 的调用点）\n    const verdict = await storeFormatVerdict(store)\n    if (!verdict.ok) {\n      formatBlockedThrottled(store, verdict)\n      return\n    }\n    await stampStoreFormat(store, verdict)\n    // 每条带 root：设置页「快照管理」要跨工作区展示列表，而 store 目录名\n    // 是 root 的单向哈希、反解不了——index.json 是唯一能持久「哈希↔工作区\n    // 路径」对应关系的地方。loadIndex 忽略 entry.root（以参数为准），\n    // 旧版本插件读新索引也只取已知字段，双向兼容。\n    // feedback 落盘（P1-2）：只对「需要解释」的消息写 feedback 字段（失败/\n    // 有跳过），正常快照不带——省空间；重启后 snapshot-info 仍能解释\n    // 「这条消息为什么没有/缺了快照」。与 root 字段当年的兼容策略一致：\n    // 老版本插件读新索引忽略未知字段。\n    const entries: IndexEntry[] = Array.from(state.snapshots.entries())\n      .filter(([, s]) => s.root === root)\n      .map(([id, s]) => {\n        const rec: IndexEntry = { id, time: s.time, root: s.root, sessionId: s.sessionId }\n        // issue #31：只在「仅消息」时落字段——旧索引与有文件树的条目都不写，\n        // 缺省即 true，读侧零迁移\n        if (s.files === false) rec.files = false\n        const fb = state.snapFeedback.get(id)\n        if (fb && (fb.failed || (Array.isArray(fb.skipped) && fb.skipped.length))) rec.feedback = fb\n        return rec\n      })\n    try {\n      await rt.writeTextViaShell(store.dir + (rt.isWin ? '\\\\' : '/') + 'index.json', JSON.stringify(entries))\n    } catch (error) {\n      // 写失败已告警；索引丢失可从 tag 反推重建（rebuildOrphans），不阻断主链\n      rt.recordError('recall saveIndex failed: ' + String(error))\n    }\n  }\n\n  async function loadIndex(root: string, sessionId: string | null): Promise<void> {\n    if (state.indexLoaded.has(root)) return\n    const store = state.stores.get(root)\n    if (!store) return\n    // A3：格式守卫——拒写态下不载入（隔离改名是写操作，也一并免掉）；\n    // 不标记 indexLoaded，下次 init/预热自然重试\n    if (!(await guardStoreFormat(store))) return\n    let raw = ''\n    let truncated = false\n    try {\n      const meta = await rt.runShellMeta(S.indexReadCmd(store.dir), { stdoutMaxBytes: 4194304 })\n      raw = S.stripBom(meta.text).trim()\n      truncated = Boolean(meta.truncated)\n    } catch (error) {\n      // 读索引失败（shell 未就绪等）：不标记已载入，下次自然重试（既有语义）\n      return\n    }\n    if (truncated) {\n      // F-G3：读截断 ≠ 索引损坏。stdout 超 4MB 上限时官方 shell 只回传流\n      // 尾部（runShellMeta 暴露的 CollectedOutput.truncated 可判定），JSON\n      // 头已丢，parse 必失败——若走下方损坏分支会把好文件改名 .corrupt，\n      // 索引记录（time/sessionId/feedback）全丢、rebuild 后变 time=0 条目\n      // 又触发清理链。改为：不隔离、原文件原样保留，按空索引继续（标记\n      // indexLoaded 防止重试循环刷错误环），本次绝不写回（防用残缺内存\n      // 覆盖好文件）；下一次自然写索引时按当下内存状态覆盖，tag 是真相源，\n      // 孤儿重建随时可反推兜底。4MB ≈ 每条约 100B × 4 万条，\n      // maxSnapshotsPerWorkspace=0（不限）的长期工作区可能触达——上限即\n      // 天花板的取舍记录于此。\n      // PF-5：同时记 indexTruncated——init/预热紧接的 rebuildOrphans 若不\n      // 知情，会把全部 tag 判成孤儿（内存为空）并全量重写索引，用残缺孤\n      // 儿集覆盖完好的大索引（现有代码的真实隐患）。rebuildOrphans 对该\n      // root 整体跳过。\n      rt.recordError('recall index read truncated: ' + root + ' 的 index.json 超过读取上限，按空索引继续（原文件未改动，下次写索引自然覆盖）')\n      state.indexLoaded.add(root)\n      state.indexTruncated.add(root)\n      return\n    }\n    if (!raw) { state.indexLoaded.add(root); return }\n    let entries: IndexEntry[] | null = null\n    try {\n      entries = JSON.parse(raw)\n    } catch (error) {\n      // H2：索引损坏 fail-loud——坏文件改名 .corrupt-<ts> 保留现场 + 记错误，\n      // 按空索引继续（rebuildOrphans 从 tag 名反推重建，数据不丢），不再静默当空。\n      if (await quarantineCorruptIndex(store)) state.indexLoaded.add(root)\n      return\n    }\n    if (!Array.isArray(entries)) {\n      // H2：整体形状非法（非数组）同样按损坏处理，保留现场。\n      if (await quarantineCorruptIndex(store)) state.indexLoaded.add(root)\n      return\n    }\n    let invalid = 0\n    for (const entry of entries) {\n      // H2：逐条过滤非法条目（非对象 / 缺 string id / 空 id——A6：空串 id\n      // 是垃圾条目，进索引会让 snapshot-info 与回退按空主键查找）并计数告警，\n      // 整体不判死；root/time 的宽松兼容保留（root 以参数为准、time 缺省回退\n      // now）——那是旧索引双向兼容策略，不属「损坏」。\n      if (!entry || typeof entry !== 'object' || typeof entry.id !== 'string' || !entry.id) { invalid++; continue }\n      const info: SnapshotInfo = {\n        root,\n        time: typeof entry.time === 'number' ? entry.time : Date.now(),\n        sessionId: entry.sessionId || sessionId || ''\n      }\n      // issue #31：旧索引没有该字段 → 视为有文件树（缺省 true）\n      if (entry.files === false) info.files = false\n      state.snapshots.set(entry.id, info)\n      // feedback 回填（P1-2）：重启后仍能解释「这条消息为什么没有/缺了\n      // 快照」。复用 setFeedback 落内存（保持 FIFO 上限），只回填「需要\n      // 解释」的记录；旧版索引无 feedback 字段时天然跳过。kind（M1 环境错误\n      // 分类）随对象保留——序列化是整体对象，但这里的重建是字段白名单，\n      // 漏 kind 会让重启后的失败条目丢失分类、status hint 失效。\n      const fb = entry.feedback\n      if (fb && typeof fb === 'object') {\n        // 重建 feedback 记录：字段白名单逐项回填（failed 分支与 skipped 分支\n        // 互斥），rec 以宽松形状声明，落 setFeedback 时由守卫保证形状落入\n        // SnapshotFeedback 联合（至少含 failed 或非空 skipped，不会空对象）\n        const rec: { failed?: boolean; error?: string; kind?: string; skipped?: string[] } = {}\n        if (fb.failed) {\n          rec.failed = true\n          if (typeof fb.error === 'string') rec.error = fb.error\n          if (typeof fb.kind === 'string') rec.kind = fb.kind\n        }\n        if (Array.isArray(fb.skipped)) rec.skipped = fb.skipped.filter((p) => typeof p === 'string')\n        if (rec.failed || (Array.isArray(rec.skipped) && rec.skipped.length)) setFeedback(entry.id, rec as SnapshotFeedback)\n      }\n    }\n    if (invalid > 0) rt.recordError('recall index has ' + invalid + ' invalid entries for: ' + root)\n    // 只在读取链路全部走通后才标记已载入：若在 try 前抢先标记，\n    // runShell 失败（shell 未就绪等）被吞后该 root 本次进程内被永久\n    // 视为「已载入」，索引永远为空、撤回按钮消失直到重启 DSH。\n    // PF-5：healthy 单独标记（≠indexLoaded）——只有「磁盘索引确实在场且\n    // 解析成功」才允许 rebuildOrphans 跳过；空索引/损坏隔离/读失败都不标。\n    state.indexLoaded.add(root)\n    state.indexHealthy.add(root)\n  }\n\n  // A5：quarantine 失败告警节流（每 store 5 分钟最多一条）。rename 失败时\n  // indexLoaded 不标记 → 下次 loadIndex 重试 → 再失败会再告警，同一环境性\n  // 故障（权限/磁盘）会把最近错误环（20 条）瞬间刷满；节流保留告警存在性\n  // 同时防刷屏。Map 挂工厂闭包而非模块级（HMR 假设）。\n  const quarantineThrottle = new Map()\n  function quarantineErrorThrottled(store: StoreInfo, text: string): void {\n    const last = quarantineThrottle.get(store.dir) || 0\n    if (Date.now() - last < 5 * 60 * 1000) return\n    quarantineThrottle.set(store.dir, Date.now())\n    rt.recordError(text)\n  }\n\n  // H2：损坏索引现场保留——改名 index.json.corrupt-<ts> 而非删除，供排障；\n  // 改完名原路径即空，下次 loadIndex 读到空按「无索引」处理，不重复告警。\n  // 返回是否改名成功：失败时不标记 indexLoaded，下次重试而非让坏文件被跳过。\n  async function quarantineCorruptIndex(store: StoreInfo): Promise<boolean> {\n    const sep = rt.isWin ? '\\\\' : '/'\n    const corrupt = store.dir + sep + 'index.json.corrupt-' + Date.now()\n    try {\n      await rt.runShell(S.renameFileCmd(store.dir + sep + 'index.json', corrupt), { stdoutMaxBytes: 4096 })\n      rt.recordError('recall index corrupt: 已按空索引继续，坏文件保留为 ' + corrupt)\n      return true\n    } catch (error) {\n      // 隔离失败已告警（带节流）；返回 false 让 loadIndex 不标记已载入、下次重试\n      quarantineErrorThrottled(store, 'recall index quarantine failed: ' + String(error))\n      return false\n    }\n  }\n\n  // ---- F1 fork lineage 持久化 ----\n  // 撤回多次产生 A→B→C 链，但中间版本归档后从 sessions.list 隐藏，client 侧\n  // 拿不到完整父链——Host 在 client fork 上报时记录 childId↔parentId 到\n  // store 目录的 lineage.json（原子写），快照管理树据此聚族展示「版本家族」。\n  // lineage.json 损坏不致命（与 index.json 损坏 fail-loud 语义区分）：按无\n  // lineage 处理，快照树退化为现有「工作区 → 会话」分组。\n  async function loadLineage(root: string): Promise<LineageEntry[]> {\n    const store = state.stores.get(root)\n    if (!store) return []\n    try {\n      const raw = S.stripBom(await rt.runShell(S.lineageReadCmd(store.dir), { stdoutMaxBytes: 1048576 })).trim()\n      if (!raw) return []\n      const arr = JSON.parse(raw)\n      return Array.isArray(arr)\n        ? arr.filter((e) => e && typeof e.childId === 'string' && typeof e.parentId === 'string')\n        : []\n    } catch (error) {\n      // 损坏/不可读按「无 lineage」继续（不隔离不告警，语义区分见函数头注释）\n      return []\n    }\n  }\n\n  async function recordLineage(root: string, childId: string, parentId: string): Promise<void> {\n    const store = state.stores.get(root)\n    if (!store) return\n    // A3：格式守卫——拒写态下不落 lineage（纯增量 UI 数据，静默跳过）\n    if (!(await guardStoreFormat(store))) return\n    const sep = rt.isWin ? '\\\\' : '/'\n    const existing = await loadLineage(root)\n    // 去重：同一 (childId, parentId) 只记一次（fork 幂等）\n    if (!existing.some((e) => e.childId === childId && e.parentId === parentId)) {\n      existing.push({ childId, parentId, time: Date.now() })\n      try {\n        await rt.writeTextViaShell(store.dir + sep + 'lineage.json', JSON.stringify(existing))\n      } catch (error) {\n        // 已告警；lineage 只是展示增强，写失败不影响快照/回退主链\n        rt.recordError('recall recordLineage failed: ' + String(error))\n      }\n    }\n  }\n\n  // exclude.txt 原文读取（设置页编辑用）：stripBom 剥掉 PS 5.1 Set-Content\n  // 写入的 UTF-8 BOM，避免设置页首行出现不可见的 \\uFEFF；两套模板对缺失\n  // 文件都输出空串，这里不用区分「没配过」和「配了空」。\n  async function readExclude(store: StoreInfo): Promise<string> {\n    return S.stripBom(await rt.runShell(S.excludeReadCmd(store.excludeFile), { stdoutMaxBytes: 1048576 }))\n  }\n\n  // exclude.txt 原文写入（设置页保存）：先 mkdir 父目录兜底（home 根目录\n  // /降级 store 目录被用户手滑删掉时，保存不该因此失败），写本体统一走\n  // rt.writeTextViaShell，与 saveIndex 共用同一套平台分叉原语。\n  async function writeExclude(store: StoreInfo, text: string): Promise<void> {\n    const body = String(text == null ? '' : text)\n    const sep = rt.isWin ? '\\\\' : '/'\n    const parent = store.excludeFile.slice(0, store.excludeFile.lastIndexOf(sep))\n    await rt.runShell(S.mkdirScript(parent), { stdoutMaxBytes: 4096 })\n    await rt.writeTextViaShell(store.excludeFile, body)\n  }\n\n  // 索引丢失时从仓库 tag 重建：tag 名 snap-<messageId> 本身就是快照主键\n  // PF-5 四档守卫（init/预热提速，每 root 省 1+N 条进程）：\n  // - truncated → 整体跳过且不写盘：内存是残缺视图，rebuild 会把全部 tag\n  //   判成孤儿并用残缺孤儿集覆盖完好的大索引（F-G3 隐患，本守卫根治）；\n  // - healthy 且该 root 条目 > 0 → 跳过：索引确实在场，tag↔index 脱节的\n  //   窗口只在 saveIndex 落盘失败时出现，该失败本身走 recordError 且下次\n  //   saveIndex 自然补写（文档语义安全论证）；条目为 0 的 healthy 不跳\n  //   （合法「磁盘有 tag、索引为空」态仍需重建）；\n  // - empty/quarantined/读失败（都不标 healthy）→ 照跑，自愈链路完整。\n  async function rebuildOrphans(root: string, sessionId: string): Promise<void> {\n    if (state.indexTruncated.has(root)) return\n    if (state.indexHealthy.has(root)) {\n      let count = 0\n      for (const s of state.snapshots.values()) {\n        if (s && s.root === root) count++\n      }\n      if (count > 0) return\n    }\n    const store = state.stores.get(root)\n    const gitExe = await rt.resolveGit()\n    if (!store || !gitExe) return\n    try {\n      // 带时间戳清单（listTagsWithTimeScript）：重建条目从 tag 的\n      // creatordate 恢复 time——此前只列 tag 名，重建条目一律 time=0，\n      // 管理列表时间前缀缺失、retention/limits 按「最旧」误清真实快照。\n      const listing = S.stripBom(await rt.runShell(S.listTagsWithTimeScript(store, gitExe), { stdoutMaxBytes: 4194304 })).trim()\n      if (!listing) return\n      for (const { name, time } of parseTagsWithTime(listing)) {\n        const id = name.replace(/^snap-/, '')\n        // F-G1：安全 tag（snap-pre-rollback-<ts>）只作救援锚点，不进索引——\n        // 否则被 rebuild 成 time=0 条目后会进快照管理列表、占\n        // maxSnapshotsPerWorkspace 配额、被 retention/limits 当「最旧」优先\n        // 清掉，H1 的救援点在重度使用下会随 purge 消失（与 routes-core.js\n        // execute「不进 index.json、列表不展示」的设计承诺对齐）。\n        if (!id || isSafetySnapshotId(id) || state.snapshots.has(id)) continue\n        state.snapshots.set(id, { root, time: time || 0, sessionId })\n      }\n      await saveIndex(root, sessionId)\n    } catch (error) {\n      // 已告警；孤立重建失败不致命——快照本体在 tag 上，下次启动会再试\n      rt.recordError('recall rebuildOrphans failed: ' + String(error))\n    }\n  }\n\n  // issue #31：只登记撤回记录，不碰文件树。两处短路刻意绕开：\n  // - snapFailures / snapLimits 描述的是「文件快照失败 / 超限」，开启本模式\n  //   正是为了绕开它们，不应再阻断消息登记；\n  // - buildArtifactRootSegment 早退（issue #18）的理由是产物根快照成本高且\n  //   没有回退价值，而仅消息登记零成本，dist/target 里撤回对话仍有价值。\n  // guardStoreFormat 保留（索引写入同受磁盘格式守卫约束）。ensureGit 仍跑一次\n  // （gitReady 命中的话零进程）——store 布局完整才能复用 gc/枚举/清理全链；\n  // 失败走与完整快照相同的反馈通道，不登记（避免同会话按钮时有时无）。\n  async function captureMessageOnly(root: string, sessionId: string, messageId: string, time?: number): Promise<void> {\n    let store: StoreInfo | null = await rt.resolveStore(root)\n    store = (await rt.tryUpgradeToHome(root))!\n    if (!(await guardStoreFormat(store))) return\n    const g = await rt.ensureGit(root, store)\n    if (!g.ok) {\n      setFeedback(messageId, { failed: true, ...buildFeedbackError(g.error || '未知原因') })\n      return\n    }\n    await loadIndex(root, sessionId)\n    state.snapshots.set(String(messageId), { root, time: time || Date.now(), sessionId, files: false })\n    await saveIndex(root, sessionId)\n    // 与完整快照成功同款：清掉该消息的旧反馈（失败后重试成功要能自愈）\n    setFeedback(messageId, { skipped: [] })\n  }\n\n  async function captureSnapshot(sessionId: string, messageId: string, time?: number): Promise<void> {\n    const root = await rt.resolveRoot(sessionId)\n    if (!root) return\n    // issue #31：只回退消息在熔断/限流短路之前分流——那两个标记是文件快照\n    // 的失败态，不该阻断消息登记（用户开这个模式正是为了绕开它们）\n    if (config.messageOnly) {\n      await captureMessageOnly(root, sessionId, messageId, time)\n      return\n    }\n    // 熔断检查要在任何解析/建仓动作之前：冷却期内连 resolveStore 都\n    // 不必跑，把失败重试的开销也一并止住\n    const fused = snapFailures.get(root)\n    if (fused && Date.now() < fused.skipUntil) return\n    // issue #24：护栏停用期同样在解析之前短路（理由见 snapLimits 声明处）\n    const limited = snapLimits.get(root)\n    if (limited\n      && limited.maxWorkspaceBytes === config.maxWorkspaceBytes\n      && limited.scanBudgetMs === config.scanBudgetMs\n      && Date.now() - limited.at < SNAP_LIMIT_RETRY_MS) return\n    // issue #18：root 自身就是构建产物目录（…/target/debug、dist）时不建快照——\n    // baseExcludes 是相对 root 的模式，匹配不到 root 自己，整个目录会被全量快照\n    // （实测 7000 个产物全进 index、对象库 GB 级），而这类目录没有回退价值。\n    // 位置在 resolveStore 之前：连空仓库都不建。不写 feedback、不进熔断——这是\n    // 设计行为而非失败，原因由 init / snapshot-info 的 notice 告知用户。\n    if (buildArtifactRootSegment(root, BASE(), rt.isWin)) return\n    let store: StoreInfo | null = await rt.resolveStore(root)\n    // tryUpgradeToHome 对刚 resolveStore 的 root 恒返回非空（缓存已写入）；\n    // 断言仅为类型收口，运行语义与迁移前一致（原代码直接透传返回值）\n    store = (await rt.tryUpgradeToHome(root))!\n    // A3：格式守卫（fail-closed）——高版本/损坏 store 拒建快照（写操作）\n    if (!(await guardStoreFormat(store))) return\n    // ensureGit 失败（issue #11 主线缺口）：原先静默 return，不进\n    // snapFeedback，客户端空轮询 20 次后放弃、用户零感知。现在走与\n    // snapshotScript 失败相同的反馈通道——buildFeedbackError 把原始\n    // stderr 分类成可行动提示（锁冲突/磁盘满等），客户端轮询到 failed\n    // 即弹「快照失败：<提示>」并停止轮询。不接熔断：环境类失败常可自愈\n    // （清磁盘/退锁后下一条消息即恢复），保持按消息重试，刷屏由\n    // recordError 尾部去重与 toast 10min 节流缓解。\n    const g = await rt.ensureGit(root, store)\n    if (!g.ok) {\n      setFeedback(messageId, { failed: true, ...buildFeedbackError(g.error || '未知原因') })\n      return\n    }\n    await loadIndex(root, sessionId)\n    // issue #29：失败耗时是「昂贵失败」的判定依据（见 EXPENSIVE_FAIL_MS）\n    const captureStartedAt = Date.now()\n    try {\n      // 整条快照脚本的兜底时限（0 = 不限制；runShell 的 timeoutMs 是必达的\n      // kill 计时器，「不限」只能用一个足够大的数表达）\n      const budget = config.snapshotBudgetMs > 0 ? config.snapshotBudgetMs : 86400000\n      const out = await rt.runShell(S.snapshotScript(root, store, state.gitExe || '', messageId, BASE()), { timeoutMs: budget, stdoutMaxBytes: 65536 })\n      // issue #24：前置扫描判定超限——本次不建快照，并按停用语义走反馈\n      //（不是失败：不 prune、不进熔断），后续快照由上方短路跳过\n      const limit = parseSnapshotLimit(out)\n      if (limit) {\n        markSnapshotLimited(root, limit)\n        const notice = buildSnapshotLimitNotice(limit)\n        noteSnapshotBlocked(root, 'recall snapshot disabled for ' + root + ': ' + notice)\n        setFeedback(messageId, { failed: true, kind: 'workspaceLimit', error: notice })\n        return\n      }\n      // issue #29：统计失败 = 规模未知，同样停用该工作区（不 prune、不进熔断：\n      // 脚本在 add 之前就退出了，没有残骸要清）。stderr 原文只进「最近错误」\n      const scanFail = parseScanFail(out)\n      if (scanFail) {\n        const pseudo: SnapshotLimit = { kind: 'scan', value: scanFail.rc, limit: 0 }\n        markSnapshotLimited(root, pseudo)\n        const notice = buildSnapshotLimitNotice(pseudo)\n        noteSnapshotBlocked(root, 'recall snapshot scan failed for ' + root + ': rc=' + scanFail.rc + ' ' + scanFail.message)\n        setFeedback(messageId, { failed: true, kind: 'scanFail', error: notice })\n        return\n      }\n      snapFailures.delete(root)\n      state.snapshots.set(String(messageId), { root, time: time || Date.now(), sessionId })\n      await saveIndex(root, sessionId)\n      setFeedback(messageId, { skipped: parseSkipped(out) })\n    } catch (error) {\n      // 已告警并回传失败反馈（客户端轮询到即弹提示）；handleSnapshotFailure 走 prune+熔断善后\n      rt.recordError('recall snapshot failed: ' + String(error))\n      // 分类后的提示替代原始 stderr 直传（M1-D4）：识别为环境错误时给\n      // 可行动文案，未识别时 buildFeedbackError 内部回落原文截断（保现状）\n      setFeedback(messageId, { failed: true, ...buildFeedbackError(String(error)) })\n      await handleSnapshotFailure(root, store, Date.now() - captureStartedAt)\n    }\n  }\n\n  // 逐消息反馈写入（issue #7 失败可见性）：成功无跳过 → 清除（重试成功\n  // 自愈）；失败/有跳过 → 记录。上限防泄漏：交替成功失败的长会话可以无限\n  // 积累，Map 保插入序做 FIFO 淘汰。\n  function setFeedback(messageId: string | number, rec: SnapshotFeedback): void {\n    const id = String(messageId)\n    const keep = rec && ((rec.failed) || (Array.isArray(rec.skipped) && rec.skipped.length))\n    if (keep) state.snapFeedback.set(id, rec)\n    else state.snapFeedback.delete(id)\n    // 环形上限超出即删最旧项（Map 迭代序 = 插入序）；取值判空替代 `!` 断言（A6）\n    if (state.snapFeedback.size > 200) {\n      const oldest = state.snapFeedback.keys().next().value\n      if (oldest !== undefined) state.snapFeedback.delete(oldest)\n    }\n  }\n\n  // snapshot-info 端点的反馈查询：优先逐消息记录；无记录但该 root 熔断中\n  // 时反馈熔断状态（冷却期内的消息快照被静默跳过，客户端需要知道「不是\n  // 还没好，是暂停了」）。客户端只对近 5 分钟的消息弹提示，历史消息查询\n  // 不受影响。\n  async function feedbackFor(sessionId: string | null | undefined, messageId: string): Promise<SnapshotFeedback | {}> {\n    const rec = state.snapFeedback.get(String(messageId || ''))\n    if (rec) return rec\n    if (!sessionId) return {}\n    const root = await rt.resolveRoot(sessionId)\n    if (root) {\n      const f = snapFailures.get(root)\n      if (f && Date.now() < f.skipUntil) {\n        return { failed: true, error: '快照连续失败已暂停（熔断），约 ' + Math.ceil((f.skipUntil - Date.now()) / 60000) + ' 分钟后自动重试，详情见设置 · 插件配置 · 最近错误' }\n      }\n    }\n    return {}\n  }\n\n  // 失败善后 = 清残骸 + 推进熔断。captureSnapshot 的调用方就是串行队列\n  // （见 index.js 事件接线），这两个动作留在 catch 里顺势排队执行，\n  // 与下一次快照天然互斥，无 git 锁竞态；自身整体 best-effort，\n  // 清理失败不该让队列任务以异常收场。\n  async function handleSnapshotFailure(root: string, store: StoreInfo | null, elapsedMs = 0): Promise<void> {\n    if (store && state.gitExe) {\n      try {\n        await rt.runShell(S.pruneScript(store, state.gitExe), { timeoutMs: 600000, stdoutMaxBytes: 4096 })\n      } catch (error) {\n        // prune 失败已告警；善后整体 best-effort（理由见函数头注释）\n        rt.recordError('recall prune after snapshot failure failed: ' + String(error))\n      }\n    }\n    const f = snapFailures.get(root) || { count: 0, skipUntil: 0 }\n    f.count++\n    const expensive = elapsedMs >= EXPENSIVE_FAIL_MS\n    // issue #29：昂贵失败跳过前两次免费重试——否则 600 秒超时要连付三轮才退避\n    if (expensive && f.count < FUSE_AFTER) f.count = FUSE_AFTER\n    if (f.count >= FUSE_AFTER) {\n      const backoff = Math.min(FUSE_BACKOFF_BASE_MS * 2 ** (f.count - FUSE_AFTER), FUSE_BACKOFF_CAP_MS)\n      const wasFused = Date.now() < f.skipUntil\n      f.skipUntil = Date.now() + backoff\n      // 只在「未熔断→熔断」的跳变沿记录：熔断期间每条消息都会走上面的\n      // 静默跳过分支，逐条记录会把最近错误环形缓冲刷成同一条目\n      if (!wasFused) {\n        rt.recordError('recall snapshot fused after ' + f.count + ' consecutive failures, backoff ' + Math.round(backoff / 60000) + 'min for: ' + root + (expensive ? ' (last failure took ' + Math.round(elapsedMs / 1000) + 's)' : ''))\n      }\n    }\n    snapFailures.set(root, f)\n  }\n\n  // 变更清单截断上限：防止超大工作区（几千个文件）把 DOM 与 JSON\n  // 双双撑爆。清单对用户的价值集中在前若干条，其余以 truncated 计数\n  // 汇总展示；total 保留完整计数让面板文案仍准确。\n  const MAX_CHANGES = 500\n\n  async function diffFor(messageId: string): Promise<DiffResult | null> {\n    const snap = state.snapshots.get(String(messageId))\n    if (!snap) return null\n    // issue #31：仅消息条目没有 tag，跑 diffScript 只会失败——直接空清单\n    if (snap.files === false) return { changes: [], total: 0, truncated: false, treeId: null, counts: { modified: 0, restored: 0, added: 0 } }\n    const store = state.stores.get(snap.root)\n    if (!store) return null\n    // 8MB 上限：按平均每条 60 字节估算可容纳十余万条，正常项目远够；\n    // 真超限时报错文案与「JSON 半截解析失败」的真实原因脱节，需显式检测\n    const text = S.stripBom(await rt.runShell(S.diffScript(snap.root, store, state.gitExe || '', 'snap-' + messageId, BASE(), MAX_CHANGES), { timeoutMs: 600000, stdoutMaxBytes: 8388608 }))\n    const trimmed = text.trim()\n    if (!trimmed) return { changes: [], total: 0, truncated: false, treeId: null, counts: { modified: 0, restored: 0, added: 0 } }\n    // PF-1：解析下沉到 parseDiffOutput（标记行剥离 + 截断 + 树指纹），纯函数单测钉住\n    return parseDiffOutput(trimmed, rt.isWin, MAX_CHANGES)\n  }\n\n  async function rollbackFor(messageId: string): Promise<RollbackResult> {\n    const snap = state.snapshots.get(String(messageId))\n    if (!snap) return { ok: false, error: '该消息没有可用的项目快照' }\n    const store = state.stores.get(snap.root)\n    if (!store) return { ok: false, error: '快照存储不可用' }\n    try {\n      const text = S.stripBom(await rt.runShell(S.rollbackScript(snap.root, store, state.gitExe || '', 'snap-' + messageId, BASE()), { timeoutMs: 600000, stdoutMaxBytes: 65536 }))\n      const m = text.trim().match(/^ROLLBACK_OK\\s+(\\d+)\\s+(\\d+)/)\n      if (!m) {\n        // 无 ROLLBACK_OK 哨兵：脚本在输出哨兵前终止，工作区状态不可知——\n        // 一律按「可能半回退」处理，交给 execute 侧救援（H1）。\n        return { ok: false, partial: true, error: '回退脚本未正常完成（工作区可能处于半回退状态）：' + text.slice(0, 300) }\n      }\n      // 捕获组缺席时 parseInt 得 NaN，由下方 Number.isNaN 兜零（与旧行为一致）\n      const deleted = parseInt(m[1] ?? '', 10)\n      const restored = parseInt(m[2] ?? '', 10)\n      return { ok: true, count: (Number.isNaN(deleted) ? 0 : deleted) + (Number.isNaN(restored) ? 0 : restored) }\n    } catch (error) {\n      // runShell 抛错（脚本异常终止）：工作区同样可能半回退，交 execute 救援。\n      const re = error as { message?: string } | null | undefined\n      const msg = String(re && re.message ? re.message : error)\n      return { ok: false, partial: true, error: msg }\n    }\n  }\n\n  // 解析“整段回退”的会话切点：优先读 live 会话的内存事件（零 IO、毫秒级），\n  // 冷会话走 sessionQuery；结果按 (会话, 消息) 缓存——消息一旦入日志，其之前的\n  // turn/end 永不变化，缓存终身有效。\n  //\n  // 读取面降级链（0.1.5-rc.2 实测，I33）：readSession 对 seeded 会话（本插件每次\n  // 撤回 fork 出的子会话即此类）恒抛——官方内部用 Session.create 校验，快照模式\n  // 要求 seed 恰等于 fork 继承前缀，而读取侧交给它的是全量日志（继承前缀 + 自身\n  // 事件），inheritedEventCount ≠ log.length 直接报错。此前 catch 把异常静默折成\n  // null，与“真首条”不可分——子会话里点任何消息都显示“该消息是本会话中第一条\n  // 用户消息”（误报）。降级改用 observeSession：它经 Session.fromRestore 恢复\n  //（restore 模式不设该约束），租约的 events 是全量逻辑日志、继承前缀可见，切点\n  // 沿用原 seq 空间，对 fork(atSeq) 仍然有效。\n  async function resolveCutSeq(sessionId: string | null, messageId: string | null): Promise<number | null> {\n    if (!sessionId || !messageId) return null\n    const cacheKey = String(sessionId) + '\\u0000' + String(messageId)\n    if (state.cutSeqCache.has(cacheKey)) return state.cutSeqCache.get(cacheKey) || null\n    let result: number | null = null\n    const live = sessions.get(sessionId)\n    if (live && Array.isArray(live.events)) {\n      result = scanCutSeq(live.events, messageId)\n    } else {\n      const query = ctx.get<SessionQueryEngine>('sessionQuery')\n      if (query) {\n        // 第一跳：readSession。抛错、或消息根本没出现在它给的事件里（读取面缺\n        // 继承前缀的版本差异）时都换下一跳——只有「消息在、其前无 turn/end」\n        // 才是可信的“首条”结论。\n        let fallback = false\n        try {\n          const log = await query.readSession(sessionId)\n          const detail = scanCutSeqDetail(Array.isArray(log && log.events) ? log.events : [], messageId)\n          result = detail.cut\n          fallback = !detail.found\n        } catch (error) {\n          // readSession 抛错（seeded 会话恒抛，I33）换 observeSession 跳\n          fallback = true\n        }\n        // 第二跳：observeSession（契约可选——旧版 dsh 无此 API 时维持原行为）。\n        // 租约必须显式释放；两跳都失败才落到 null。\n        if (fallback && typeof query.observeSession === 'function') {\n          try {\n            const lease = await query.observeSession(sessionId)\n            try {\n              result = scanCutSeq(lease && Array.isArray(lease.events) ? lease.events : [], messageId)\n            } finally {\n              disposeLease(lease)\n            }\n          } catch (error) {\n            // 两跳都失败落 null：保守降级——文件回退不受影响，面板不出对话选项\n            result = null\n          }\n        }\n      }\n    }\n    state.cutSeqCache.set(cacheKey, result)\n    return result\n  }\n\n  // fork 残留排队项的 id 解析：优先读 live 会话的内存事件（零 IO、毫秒级），\n  // 退到 sessionQuery 的 observeSession（restore 模式，事件含继承前缀，覆盖\n  // seeded 父会话——撤回链的父会话本身可能是上一次撤回 fork 出的子会话），\n  // 最后才用 readSession（快照模式对 seeded 会话恒抛）。这里一旦返回空数组，\n  // Client 侧的自动清理就永不触发，所以顺序按「内存 → restore → 磁盘」排，\n  // 且内存读取同时探 snapshotEvents()（0.1.5-rc.1 的会话对象）与 events\n  // （旧版字段）。三跳都失败才返回空数组（= 不清理），残留项可在 QueueDock\n  // 手动删除，绝不阻断撤回主流程。\n  async function resolveStaleQueueItemIds(sessionId: string | null, cutSeq: number | null): Promise<string[]> {\n    if (!sessionId || typeof cutSeq !== 'number' || !Number.isFinite(cutSeq)) return []\n    const live = liveEventsOf(sessions.get(sessionId))\n    if (live) return scanStaleQueueItemIds(live, cutSeq)\n    const query = ctx.get<SessionQueryEngine>('sessionQuery')\n    if (!query) return []\n    if (typeof query.observeSession === 'function') {\n      try {\n        const lease = await query.observeSession(sessionId)\n        try {\n          return lease && Array.isArray(lease.events) ? scanStaleQueueItemIds(lease.events, cutSeq) : []\n        } finally {\n          disposeLease(lease)\n        }\n      } catch (error) { /* restore 失败（旧版无此 API / 会话不可观测）：换磁盘跳 */ }\n    }\n    try {\n      const log = await query.readSession(sessionId)\n      return log && Array.isArray(log.events) ? scanStaleQueueItemIds(log.events, cutSeq) : []\n    } catch (error) {\n      // 三跳都失败按空数组（= 不清理，残留项可手动删；见函数头注释）\n      return []\n    }\n  }\n\n  return { saveIndex, loadIndex, readExclude, writeExclude, rebuildOrphans, captureSnapshot, diffFor, rollbackFor, resolveCutSeq, resolveStaleQueueItemIds, feedbackFor, loadLineage, recordLineage, guardStoreFormat }\n}\n"
    },
    {
      "path": "src/host/store.ts",
      "content": "/**\n * dsh-recall-plugin — 执行与存储层（ctx 绑定的工厂，无模块级副作用）\n *\n * 职责：提供 runShell（宿主身份执行 + 统一编码保证）、会话根目录解析、\n * git 可执行文件探测、home/降级存储解析与迁移、影子仓库初始化（ensureGit）。\n * 按 process.platform 选择脚本模板（scripts.pwsh.js / scripts.posix.js），\n * 两套模板导出同名接口，本文件用 rt.scripts 统一下发。\n * 产出共享 state（各 Map 缓存）供 snapshots.js / maintenance.js 复用；\n * 由 lib/index.js 在 apply(ctx) 里装配，插件卸载时随 Fiber 一起丢弃。\n */\n\nimport os from 'node:os'\nimport crypto from 'node:crypto'\nimport { spawn as childSpawn } from 'node:child_process'\nimport * as pwshScripts from './scripts.pwsh.js'\nimport * as posixScripts from './scripts.posix.js'\nimport { classifyEnvError } from './diagnostics.js'\nimport type { Runtime, SharedState, StoreInfo, ShellRunOptions, ErrorRecord, ShellDialect } from '../types/state.js'\nimport type { PwshScripts, PosixScripts } from '../types/scripts.js'\nimport type { HostContext, SessionQueryEngine, ShellExecutor, ShellExecRequest, ShellRunResult } from '../types/dsh-contract.js'\nimport type { ResolvedConfig } from '../types/config.js'\n\n// home 不可写时迁移重试的节流间隔：避免每条消息都白试一次注定失败的迁移\nconst HOME_RETRY_MS = 300000\n\n// 最近错误环形缓冲容量：设置页排障用，20 条足够回溯一轮快照/gc 的失败\nconst ERROR_BUFFER_MAX = 20\n\n// ---- POSIX home 基底解析（模块级纯逻辑，单测直测；工厂内 posixHomeBaseResolve\n// 委托到这里）。放模块级而非工厂闭包：分支行为要在 win32 CI 上可测，而\n// posixHomeBaseResolve 只在 POSIX 运行时被触达。----\n\n// 三档回退选择：bash env $DSH_HOME → Node 主进程 DSH_HOME → os.homedir()。\n// 第三档必须补 /.dsh 子目录（I24）：win32 版第三档是 Join-Path USERPROFILE .dsh\n// （scripts.pwsh.js homeDirScript），POSIX 版曾直接用裸 homedir，快照落\n// ~/dsh-recall-snapshots 而非 ~/.dsh/dsh-recall-snapshots（issue #11 实证）。\n// 返回 third 标记是否走了第三档——只有第三档才涉及旧容器迁移（存量用户\n// 的数据在旧位，改 base 前要先搬）。\nexport interface PosixHomeInputs {\n  probed: string\n  envHome: string\n  homedir: string\n}\nexport function selectPosixHomeBase({ probed, envHome, homedir }: PosixHomeInputs): { base: string; third: boolean } {\n  if (probed) return { base: probed, third: false }\n  if (envHome) return { base: envHome, third: false }\n  return { base: homedir + '/.dsh', third: true }\n}\n\n// 第三档命中时的一次性旧容器迁移编排（best-effort，数据安全优先）：\n// legacyHomeMigrateScript 只在「旧容器存在且新容器不存在」时整容器 mv，\n// 输出四态由这里裁决——MIGRATE_OK / OLD_ABSENT 落规范位置（~/.dsh/…）；\n// BOTH_PRESENT（双容器并存）/ MIGRATE_FAIL（mv 失败）沿用旧位并 recordError，\n// 与 tryUpgradeToHome 的非致命迁移哲学一致：数据不丢永远优先于路径规范。\n// 探测命令自身失败按同策略回落旧位——此刻无法判断旧容器是否存在，选新位\n// 会让存量用户「看不到」历史快照，选旧位对新装机只是维持修复前的行为。\nexport async function resolvePosixHomeBase(\n  deps: { runShell(cmd: string, opts?: ShellRunOptions): Promise<string>; scripts: PosixScripts; recordError(text: string): void },\n  inputs: PosixHomeInputs\n): Promise<string> {\n  const { probed, envHome, homedir } = inputs\n  const sel = selectPosixHomeBase({ probed, envHome, homedir })\n  if (!sel.third) return sel.base\n  try {\n    const out = String(await deps.runShell(deps.scripts.legacyHomeMigrateScript(homedir), { timeoutMs: 300000, stdoutMaxBytes: 4096 })).trim()\n    if (out === 'MIGRATE_OK' || out === 'OLD_ABSENT') return sel.base\n    deps.recordError(\n      out === 'BOTH_PRESENT'\n        ? 'recall home store 新旧容器并存（' + homedir + '/dsh-recall-snapshots 与 ' + homedir + '/.dsh/dsh-recall-snapshots），沿用旧位，未做任何改动'\n        : 'recall 旧快照容器迁移失败（MIGRATE_FAIL），沿用旧位 ' + homedir + '/dsh-recall-snapshots'\n    )\n    return homedir\n  } catch (error) {\n    // 迁移探测失败不阻断启动：沿用旧位继续（已 recordError 告警）\n    deps.recordError('recall 旧快照容器迁移探测失败，沿用旧位: ' + String(error))\n    return homedir\n  }\n}\n\n// 失败清扫脚本输出解读（M3 纯逻辑，供单测；cleanupAfterGitFailure 消费）。\n// killOrphansScript 的三级出口：CLEANUP_OTHER_INSTANCE <pid> = 检测到另一个\n// 活实例正在使用同一快照库（心跳有效且进程存活），清扫已让路；\n// CLEANUP_SKIPPED_FRESH_LOCK = 存在 5 分钟内的新锁（疑似 git 操作进行中），\n// 清扫未触碰；CLEANUP_DONE = 原有清扫路径执行完毕。解析按标记行匹配，\n// 与模板输出逐字对应（改标记必须两侧同步）。\nexport function parseCleanupResult(out: unknown): { otherPid: number | null; skippedFresh: boolean } {\n  const m = String(out || '').match(/CLEANUP_OTHER_INSTANCE\\s+(\\d+)/)\n  if (m) return { otherPid: parseInt(m[1] ?? '', 10), skippedFresh: false }\n  if (String(out || '').indexOf('CLEANUP_SKIPPED_FRESH_LOCK') >= 0) return { otherPid: null, skippedFresh: true }\n  return { otherPid: null, skippedFresh: false }\n}\n\n// rename 步 ENOENT 判定（模块级纯逻辑，单测直接覆盖）：POSIX mv 与\n// pwsh Move-Item 的「目标不存在」文案集合，且错误必须提到 tmp 文件名\n//（basename）——只认 rename 步的错误形态，误吞面最小。\nexport function isTmpConsumedError(error: unknown, basename: string): boolean {\n  const s = String(error || '')\n  if (!basename || s.indexOf(basename) < 0) return false\n  return /No such file/i.test(s) || /does not exist/i.test(s) || /cannot find path/i.test(s)\n}\n\n// ---- win32 直连执行通道（issue #15）----\n// 官方 shell 是「提供方注册制」：一个 composition 恰好一个 ctx.shell 实现，宿主\n// profile 可以在 win32 上把它配成 bash（如只启用 bash-sandbox）。此时 pwsh 模板\n// 被 bash 执行，第一行编码前导即语法错误，快照从未成功、撤回按钮全死。官方\n// ShellExecutor 公开面（resolve/run/start + sandboxMode）没有任何方言标识——不能\n// 查询，只能行为探测；判成 bash 才改走 Node spawn 直连 powershell.exe，模板与\n// 其余语义原样保留，只换执行通道。\n\n// 探针命令：Write-Output 是 pwsh 语法，bash 下 command-not-found（exit 127）。\n// 哨兵取罕见 ASCII 串防巧合命中。命令内联在本文件而不做成 scripts.pwsh.ts 新\n// 导出——两套模板的「同名导出」契约（types/scripts.ts + scripts-contract 单测）\n// 会因单侧新增导出而红，而探针只服务 win32 分流、不属于跨平台模板面。\nexport const SHELL_PROBE_SENTINEL = 'RCL_DIALECT_PROBE_9f4a2e'\nexport const SHELL_PROBE_COMMAND = 'Write-Output ' + SHELL_PROBE_SENTINEL\n\n// 探针判定（模块级纯函数，单测直测）：exit 0 且回显哨兵 → pwsh；其余一律 bash\n// （非零退出 / 无输出 / 未回显 / 探测 reject 折成的 null）。误判代价不对称但都低：\n// 判成 pwsh 走官方通道（本就正确），判成 bash 走直连通道（pwsh 模板同样能跑）。\nexport function judgeShellDialect(res: ShellRunResult | null | undefined): ShellDialect {\n  if (!res || res.exitCode !== 0) return 'bash'\n  const text = (res.stdout && res.stdout.text) || ''\n  return text.indexOf(SHELL_PROBE_SENTINEL) >= 0 ? 'pwsh' : 'bash'\n}\n\n// 凭证形状 env 名（与官方 dsh-subprocess SENSITIVE_ENV_PATTERN 同式）\nconst SENSITIVE_ENV = /KEY|PASSWORD|SECRET|TOKEN/i\n\n// stderr 保留字节（错误消息只取尾部 1500 字符，留一个宽裕窗口避免多字节截断）\nconst STDERR_KEEP_BYTES = 65536\n\n// 子进程 env 复刻官方清洗（dsh-subprocess scrubbedParentEnv + pwsh-local\n// ENV_OVERRIDES）：剥掉凭证形状名与全部 DSH_*（不区分大小写——Windows 环境名\n// 大小写不敏感，不等同处理会让父进程的 dsh_* 条目在子进程里读回成 $env:DSH_*），\n// 再叠加 NO_COLOR/PAGER/GIT_PAGER。为什么值得：官方通道本就不把宿主凭证交给\n// 子进程，直连通道原样继承就破了「安全模型不变」；而剥掉 DSH_* 后 homeDirScript\n// 的 $env:DSH_HOME 分支在两通道恒为空、统一走 Node 侧传入的 envHome 字面量，\n// 两条通道收敛到同一 store 根——存量快照库不会撕裂。\nexport function scrubChildEnv(env: Record<string, string | undefined>): Record<string, string> {\n  const out: Record<string, string> = {}\n  for (const key of Object.keys(env)) {\n    const value = env[key]\n    if (value === undefined) continue\n    if (SENSITIVE_ENV.test(key) || key.toUpperCase().indexOf('DSH_') === 0) continue\n    out[key] = value\n  }\n  out.NO_COLOR = '1'\n  out.PAGER = 'cat'\n  out.GIT_PAGER = 'cat'\n  return out\n}\n\n// stdout 收集（模块级纯函数，单测直测）：超 stdoutMaxBytes 保留尾部并置 truncated\n// ——对齐官方 CollectedOutput 语义（F-G3：loadIndex 靠 truncated 区分「读截断」与\n// 「内容损坏」，误判会把完好大索引当损坏覆盖）；恰等阈值不算截断。按字节切尾，\n// 与官方一致：截断处落在多字节字符中间时由 utf8 解码兜底成替换字符。\nexport function collectStdout(chunks: Buffer[], maxBytes: number): { text: string; truncated: boolean } {\n  const total = chunks.reduce((n, c) => n + c.length, 0)\n  if (total <= maxBytes) return { text: Buffer.concat(chunks).toString('utf8'), truncated: false }\n  const all = Buffer.concat(chunks)\n  return { text: all.subarray(all.length - maxBytes).toString('utf8'), truncated: true }\n}\n\n// 直连 spawn 的依赖注入面（默认 child_process.spawn）：单测以假 child 覆盖 stdin\n// 字节透传与超时 kill 分支，无需真起进程，CI（ubuntu）也能覆盖全部分支。\nexport interface DirectChildLike {\n  stdin: NodeJS.WritableStream | null\n  stdout: NodeJS.ReadableStream | null\n  stderr: NodeJS.ReadableStream | null\n  on(event: 'error', listener: (error: Error) => void): unknown\n  on(event: 'close', listener: (code: number | null) => void): unknown\n  kill(): unknown\n}\nexport type SpawnLike = (\n  exe: string,\n  argv: string[],\n  options: { cwd: string; env: Record<string, string>; windowsHide: boolean }\n) => DirectChildLike\n\nexport interface DirectShellRequest {\n  command: string\n  timeoutMs: number\n  stdoutMaxBytes: number\n  stdin?: string\n  cwd: string\n}\n\nexport interface DirectShellResult {\n  text: string\n  truncated: boolean\n  exitCode: number | null\n  stderr: string\n  timedOut: boolean\n}\n\n// 直连可执行文件：PS 5.1 全平台自带（不赌 PS7 存在；插件模板本就按 5.1 兼容写，\n// I14/I27 探针已钉），路径与官方 pwsh-local 的候选链末档同一处。\nexport function directPwshPath(env: Record<string, string | undefined>): string {\n  return (env.SystemRoot || env.windir || 'C:\\\\Windows') + '\\\\System32\\\\WindowsPowerShell\\\\v1.0\\\\powershell.exe'\n}\n\n// 直连执行（模块级，spawn 由调用方注入）：四项官方语义一项不少——stdin 字节\n// 透传（I27：PS 5.1 的 Console.In 按输入代码页解码，必须写原始字节）、stdout\n// 截断标记、超时 kill、非零退出交回调用方走失败清扫。windowsHide：桌面端宿主是\n// GUI 进程，不设会让每条快照闪一次控制台窗口。spawn 失败（如可执行文件缺失）\n// reject，与官方通道「run 只对基础设施故障 reject」的语义一致。\nexport async function runViaSpawn(spawn: SpawnLike, req: DirectShellRequest): Promise<DirectShellResult> {\n  const child = spawn(directPwshPath(process.env), ['-NoProfile', '-NonInteractive', '-Command', req.command], {\n    cwd: req.cwd,\n    env: scrubChildEnv(process.env),\n    windowsHide: true,\n  })\n  return await new Promise<DirectShellResult>((resolve, reject) => {\n    // 输出 sink：超预算即时丢头部（命令异常刷屏也不让宿主内存无界增长）。丢弃\n    // 只在「剩余仍大于预算」时发生，故最终 total 要么是真总量（未丢过），要么\n    // 大于预算（丢过）——collectStdout 的截断判定两种情形都正确。\n    const sink = (maxBytes: number) => {\n      const chunks: Buffer[] = []\n      let total = 0\n      return {\n        push(chunk: unknown) {\n          const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk))\n          chunks.push(buf)\n          total += buf.length\n          // 头块长度落局部再判空（A6）：循环条件里的索引读取在类型层可能\n          // undefined，先取头再一并校验「头存在且仍超预算」。\n          while (chunks.length > 1) {\n            const head = chunks[0]\n            if (!head || total - head.length <= maxBytes) break\n            total -= head.length\n            chunks.shift()\n          }\n        },\n        take() { return collectStdout(chunks, maxBytes) },\n      }\n    }\n    const outSink = sink(req.stdoutMaxBytes)\n    const errSink = sink(STDERR_KEEP_BYTES)\n    let timedOut = false\n    let settled = false\n    const timer = setTimeout(() => {\n      timedOut = true\n      try { child.kill() } catch (error) { /* 已退出或无权终止：交给 close 事件收口 */ }\n    }, Math.max(1, req.timeoutMs))\n    const finish = (code: number | null) => {\n      if (settled) return\n      settled = true\n      clearTimeout(timer)\n      const stdout = outSink.take()\n      resolve({ text: stdout.text, truncated: stdout.truncated, exitCode: code, stderr: errSink.take().text, timedOut })\n    }\n    if (child.stdout) child.stdout.on('data', (chunk) => outSink.push(chunk))\n    if (child.stderr) child.stderr.on('data', (chunk) => errSink.push(chunk))\n    child.on('error', (error) => {\n      if (settled) return\n      settled = true\n      clearTimeout(timer)\n      reject(error)\n    })\n    child.on('close', (code) => finish(code === undefined ? null : code))\n    if (child.stdin) {\n      // 子进程已退出时的 EPIPE 不该冒成未捕获异常：写失败与否由退出码裁决\n      child.stdin.on('error', () => {})\n      child.stdin.end(Buffer.from(req.stdin === undefined ? '' : req.stdin, 'utf8'))\n    }\n  })\n}\n\n// ---- 官方执行通道的双代分流（0.1.7 shell 接缝）----\n// 0.1.7 删掉了 ShellExecutor 的 run/start，改为 resolve + execute(spec) 返回\n// 句柄、前台结果走 handle.result()。peer 保留 0.1.2–0.1.6 各线段（老用户仍可能\n// 装），所以按**运行时方法探测**分流而非按包版本：宿主注入的是它自己的执行器\n// 实例，插件 node_modules 里的 dsh-shell 版本与运行时无关。两分支共用同一 spec\n// 构造与同一失败分级（result() 与 run() 的返回形状一致、失败语义一致）。\n// 判据顺序先 run 后 execute：0.1.7 官方执行器已无 run，风险只在第三方执行器\n// 同时提供两者时拿到旧语义——探针锚点（M3-1）绑定了这一判据，官方回退会先红。\nexport async function runViaExecutor(shell: ShellExecutor, spec: ShellExecRequest): Promise<ShellRunResult> {\n  if (typeof shell.run === 'function') return await shell.run(spec)\n  if (typeof shell.execute === 'function') {\n    const handle = await shell.execute(spec)\n    // result() 只在基础设施失败（spawn 未产出进程）时 reject；非零退出、超时\n    // kill、abort kill 一律 resolve 并以 first-cause 标记回显（C1 语义）。\n    // reject 原样上抛——与旧通道 run reject 的语义保持一致（失败分级只服务\n    // resolve 出来的失败结果）。\n    return await handle.result()\n  }\n  throw new Error('recall: ctx.shell 未提供 run 也未提供 execute，无法执行命令（dsh 执行接缝不兼容）')\n}\n\nexport function createRuntime(ctx: HostContext, config: ResolvedConfig, deps?: { spawn?: SpawnLike }): Runtime {\n  const shell = ctx.shell\n  const sessions = ctx.sessions\n  // 直连通道的 spawn（默认 Node 原生）：单测注入假 child 覆盖字节透传与超时分支\n  const spawn: SpawnLike = (deps && deps.spawn) || (childSpawn as unknown as SpawnLike)\n\n  const isWin = process.platform === 'win32'\n  const SEP = isWin ? '\\\\' : '/'\n  const scripts: PwshScripts | PosixScripts = isWin ? pwshScripts : posixScripts\n\n  const state: SharedState = {\n    roots: new Map(),\n    stores: new Map(),\n    snapshots: new Map(),\n    indexLoaded: new Set(),\n    // PF-5 索引终态三/四档标记（rebuildOrphans 守卫的数据源）：\n    // - indexHealthy：磁盘索引解析成功且在场（loadIndex 正常载入分支）——\n    //   rebuildOrphans 对 healthy 且条目非空的 root 整体跳过（省 1+N 条进程）\n    // - indexTruncated：读截断（F-G3，内存是残缺视图）——rebuildOrphans\n    //   必须跳过：否则全部 tag 被判孤儿、用残缺孤儿集覆盖完好的大索引\n    //   （feedback 全丢、数万条索引按 win32 分块写下是数百条进程的灾难）\n    // empty（无索引文件）/quarantined（损坏隔离）不标记 → rebuild 照跑，\n    // 自愈链路完整\n    indexHealthy: new Set(),\n    indexTruncated: new Set(),\n    gitReady: new Set(),\n    cutSeqCache: new Map(),\n    homeRetryAt: new Map(),\n    gcLastAt: new Map(),\n    gcCount: new Map(),\n    gitExe: null,\n    posixHomeBase: null,\n    // win32 方言探针缓存（issue #15）：判定结果 + in-flight promise（并发首调\n    // 只跑一次探针）；POSIX 不探测，两字段恒为 null\n    shellDialect: null,\n    shellDialectProbe: null,\n    homeContainer: null,\n    errors: [],\n    // 逐消息的快照反馈（issue #7 失败可见性）：失败 {failed,error} 或\n    // fail-open 跳过 {skipped:[...]}，由 snapshot-info 端点下发给客户端\n    // 弹 toast。放共享 state 而非 snapshots.js 闭包：端点在 index.js，\n    // 与索引/根缓存同层取用。\n    snapFeedback: new Map()\n  }\n\n  // 最近错误环形缓冲：Host 侧所有失败原本只进 console.error（宿主进程\n  // 日志，用户在页面上不可见），这里留最近 20 条经 /api/recall/status\n  // 下发给设置页展示。同时转发 console.error 保持原有宿主日志不变。\n  // 尾部去重（issue #11）：环境性错误随每条消息重复抛出，逐条 push 会把\n  // 20 条环形缓冲刷成同一条目、console.error 同步刷屏，其他诊断信息全被\n  // 挤掉。相邻重复只更新 time/count——间隔其他错误的重复仍新建条目，错误\n  // 时序不丢；kind 随条目富集（classifyEnvError），供 status 端点机器分流。\n  function recordError(text: string) {\n    const message = String(text)\n    const last = state.errors[state.errors.length - 1]\n    if (last && last.message === message) {\n      last.time = Date.now()\n      last.count += 1\n      return\n    }\n    const rec: ErrorRecord = { time: Date.now(), message, count: 1, kind: classifyEnvError(message) }\n    state.errors.push(rec)\n    if (state.errors.length > ERROR_BUFFER_MAX) state.errors.splice(0, state.errors.length - ERROR_BUFFER_MAX)\n    console.error(message)\n  }\n\n  // 两套脚本模板的「命令函数」同名导出是跨平台正确性的硬约束（store.js\n  // 按平台单选 rt.scripts，调用方统一 S.*）：单侧漏导出只会在另一平台\n  // 用户机器上以「不是函数」的怪异方式暴雷。装配时比对一次。豁免项：\n  // 平台专属导出（homeDirScript 的 $h 链只在 pwsh 侧需要——POSIX 的 home\n  // 基底走 probeHomeScript + Node 侧推导；常量与转义工具不承载命令）。\n  ;(function checkScriptParity() {\n    // fileWriteStdinCmd 两平台同名（PF-2 起两平台统一走 stdin 单进程落盘，\n    // 编码行为由探针钉死）；legacyHomeMigrateScript 仅 posix 版存在：\n    // 旧容器迁移是 POSIX 漂移（I24）专属的存量数据兜底，win32 无此问题\n    const SKIP = new Set(['homeDirScript', 'probeHomeScript', 'legacyHomeMigrateScript'])\n    // 豁免集事实源：src/types/scripts.ts 平台专属接口（PwshScripts/PosixScripts\n    // extends 差分）；本集合是它的运行时镜像，M5 起由 tests/types satisfies 编译期锁死\n    const pwshKeys = Object.keys(pwshScripts).filter((k) => !SKIP.has(k) && typeof (pwshScripts as Record<string, unknown>)[k] === 'function')\n    const posixKeys = Object.keys(posixScripts).filter((k) => !SKIP.has(k) && typeof (posixScripts as Record<string, unknown>)[k] === 'function')\n    const missing = pwshKeys.filter((k) => posixKeys.indexOf(k) < 0)\n    if (missing.length) recordError('recall script parity: posix 缺少导出 ' + missing.join(', '))\n  })()\n\n  // 方言探针（issue #15；惰性 + 缓存 + in-flight 去重）：session/event 突发时\n  // runShellMeta 会并发首调，探针本身只许跑一次。探测走独立路径（直调\n  // ctx.shell.resolve/run，不经 runShellMeta）——既避免递归，也让探测失败\n  // （判据本身，不是 git 失败）不触发 cleanupAfterGitFailure；不带 UTF8_PRELUDE\n  // （探的是执行器方言，不是前导兼容性），30s 短超时（官方 clampTimeout 只 cap\n  // 上限、不抬下限，卡住的探针不该拖住首条消息的快照）。reject 折成 null 判\n  // bash：直连通道对 pwsh 模板同样兼容，误判不致命。\n  function resolveShellDialect(): Promise<ShellDialect> {\n    if (state.shellDialect) return Promise.resolve(state.shellDialect)\n    if (!state.shellDialectProbe) {\n      state.shellDialectProbe = (async () => {\n        let res: ShellRunResult | null = null\n        try {\n          const sp = ctx.get<{ workspaceRoot?: string }>('sandboxPolicy')\n          res = await runViaExecutor(shell, shell.resolve({\n            command: SHELL_PROBE_COMMAND,\n            timeoutMs: 30000,\n            stdoutMaxBytes: 4096,\n            sandboxPolicy: { mode: 'danger-full-access', workspaceRoot: (sp && sp.workspaceRoot) || process.cwd() },\n          }))\n        } catch (error) {\n          // 探针失败折 null → judgeShellDialect 判 bash 走直连通道（对 pwsh\n          // 模板同样兼容、误判不致命，论证见上方注释）\n          res = null\n        }\n        const dialect = judgeShellDialect(res)\n        state.shellDialect = dialect\n        // 一行启动期日志：冒烟验收靠它确认默认路径「从未触达 spawn 通道」，\n        // 也是用户排障时唯一能看见方言判定的地方\n        console.error('recall shell dialect probe: ' + dialect + (dialect === 'bash' ? '（ctx.shell 非 pwsh，改用直连 powershell.exe 通道）' : ''))\n        return dialect\n      })()\n    }\n    return state.shellDialectProbe\n  }\n\n  // 命令视角的方言（分流入口）：清扫脚本（RECALL_CLEANUP 哨兵）不触发探针、只用\n  // 缓存。为什么：清扫只在一条真实命令失败后被调用——那条命令必然已跑过\n  // runShellMeta 首调、方言早判定完，这里不需要再判；善后路径本已脆弱（残留锁/\n  // 孤儿进程），再叠一条探测进程只会让它更重。缓存未判定时按 pwsh 走官方通道，\n  // 判定责任留给后续真实命令（不在这里缓存，避免 stub/残缺执行器把假结论钉死）。\n  async function shellDialectFor(command: string): Promise<ShellDialect> {\n    if (command.indexOf('RECALL_CLEANUP') >= 0) return state.shellDialect || 'pwsh'\n    return await resolveShellDialect()\n  }\n\n  // 失败收口（两个执行通道共用，错误形态与语义保持一致）：先 best-effort 清扫\n  // （超时/失败的 git 命令可能留下孤儿进程与 stale 锁，见下方 runShellMeta 注释）\n  // 再抛原始错误，清扫自身的失败不得掩盖它；stderr 截 1500 字符（设置页\n  // 「最近错误」展示用）。\n  async function throwShellFailure(command: string, stderr: string, exitCode: number | null | undefined): Promise<never> {\n    await cleanupAfterGitFailure(command)\n    const detail = String(stderr || '').trim() || ('exit ' + String(exitCode))\n    throw new Error(detail.slice(0, 1500))\n  }\n\n  // 直连通道收口：保留官方四项语义（stdin 字节透传 / stdout 截断标记 / 超时\n  // kill / 非零退出走失败清扫）。超时与非零退出都走 throwShellFailure——官方\n  // 通道的 timeout 同样以非零结果返回并触发清扫，两条通道失败语义一致。\n  async function runShellDirect(command: string, req: DirectShellRequest): Promise<{ text: string; truncated: boolean }> {\n    const res = await runViaSpawn(spawn, req)\n    if (res.timedOut) {\n      await throwShellFailure(command, res.stderr + '\\n直连 powershell.exe 超时（' + String(req.timeoutMs) + 'ms）', null)\n    }\n    if (res.exitCode !== 0) await throwShellFailure(command, res.stderr, res.exitCode)\n    return { text: res.text, truncated: res.truncated }\n  }\n\n  // 所有 shell 调用都以宿主身份（danger-full-access）执行，不借用会话沙箱。\n  // 为什么安全：DSH 沙箱约束的是「模型驱动」的文件效果，而本插件的命令全部\n  // 是宿主侧固定模板（建仓/快照/索引/回退），命令串里唯一变量是插件自己\n  // 推导的路径（会话 cwd、哈希出的 store 路径、消息 ID），模型无法注入任何\n  // 内容；快照落盘的也只是会话本就有权读取的工作区文件副本，不扩大能力。\n  // 为什么必须如此：若按会话解析策略，workspace-write/read-only 会话写不了\n  // home，快照被迫降级进项目目录（污染）；read-only 会话连项目都写不了，\n  // 回退恢复直接失败。pwsh-sandbox / bash-sandbox 对 danger-full-access\n  // 直接不约束（等价本地执行器），无沙箱后端的部署则忽略该字段，两边都成立。\n  // F-G3：runShell 的元数据变体——stdout 截断可判定（官方 ShellRunResult.stdout\n  // 是 CollectedOutput{text, truncated, spillPath?}，见 dsh-shell 与\n  // dsh-subprocess 的 lib/types/types.d.ts；截断时 text 只剩流尾部）。需要\n  // 「解析完整 stdout」的调用方（loadIndex）用它区分「读截断」与「内容损坏」；\n  // 其余调用方继续用 runShell 拿纯文本，签名不变。\n  async function runShellMeta(command: string, opts?: ShellRunOptions): Promise<{ text: string; truncated: boolean }> {\n    const sp = ctx.get<{ workspaceRoot?: string }>('sandboxPolicy')\n    const workspaceRoot = (sp && sp.workspaceRoot) || process.cwd()\n    const timeoutMs = (opts && opts.timeoutMs) || 300000\n    const stdoutMaxBytes = (opts && opts.stdoutMaxBytes) || 4194304\n    // 编码前导：pwsh 侧统一 UTF-8 输出（中文机器 GBK 代码页不再乱码）；\n    // bash 侧 LC_ALL=C 确定序。各模板自带，这里统一前置注入。\n    const fullCommand = scripts.UTF8_PRELUDE + '\\n' + command\n    // 方言分流（issue #15）：win32 且 ctx.shell 是 bash 时官方通道跑不了 pwsh\n    // 模板（第一行前导即语法错误），改走 spawn 直连；默认路径（ctx.shell 即\n    // pwsh）与 POSIX 都不探测、不触达 spawn——这是「默认零回归」的第一性保证。\n    if (isWin && (await shellDialectFor(command)) === 'bash') {\n      return await runShellDirect(command, { command: fullCommand, timeoutMs, stdoutMaxBytes, cwd: workspaceRoot, stdin: opts && opts.stdin })\n    }\n    const spec = shell.resolve({\n      command: fullCommand,\n      timeoutMs,\n      stdoutMaxBytes,\n      // stdin 是官方 ShellExecRequest 契约字段（bash-local/pwsh 均实现），\n      // POSIX 侧用它传 index.json 全文，绕开 argv 长度上限\n      ...((opts && opts.stdin !== undefined) ? { stdin: opts.stdin } : {}),\n      sandboxPolicy: { mode: 'danger-full-access', workspaceRoot }\n    })\n    const res = await runViaExecutor(shell, spec)\n    if (res && res.exitCode !== 0) {\n      // 失败分级：0.1.7 起 exitCode 可为 null（准备期超时 / 信号终止），旧的\n      // `'exit ' + exitCode` 兜底文案对用户不可读、也命不中 diagnostics 的分类。\n      // 准备期超时无法与「无输出的 abort」用 exitCode 区分，故只在无 stderr 时\n      // 判超时（first-cause 标记 timedOut 在场时直接采用，它是强判据）；有\n      // stderr 则按非零退出处理并回显 stderr 原文。超时文案含「超时」二字，\n      // 非零退出文案含退出码，两类各自可读（验收由 M1-3 ④ 断言）。\n      const stderr = (res && res.stderr && res.stderr.text) || ''\n      const timedOut = res.timedOut === true || (res.exitCode === null && !String(stderr).trim())\n      const detail = timedOut\n        ? '命令准备期超时（' + String(timeoutMs) + 'ms，执行器未产出输出）'\n        : stderr\n      await throwShellFailure(command, detail, res.exitCode)\n    }\n    return {\n      text: (res && res.stdout && res.stdout.text) || '',\n      truncated: Boolean(res && res.stdout && res.stdout.truncated),\n    }\n  }\n\n  async function runShell(command: string, opts?: ShellRunOptions): Promise<string> {\n    return (await runShellMeta(command, opts)).text\n  }\n\n  // 从脚本文本提取影子仓库 git-dir：两套模板的 git 命令脚本都以\n  // `$g = '<store.git>'` / `g='<store.git>'` 开头（凡带 store 的脚本全遵守\n  // 此约定），取首个带引号字面量赋值即得。resolveGitScript 等对 $g 的\n  // 非字面量赋值天然不匹配；含单引号的罕见路径会让 psq 的 '' 转义截断\n  // 提取结果——清扫脚本对错误路径只是 no-op（杀不到进程、删不到锁），\n  // 安全降级为本兜底加入前的行为。\n  function extractGitDir(command: string): string | null {\n    const m = String(command).match(/(?:^|\\n)[ \\t]*(?:\\$g|g)[ \\t]*=[ \\t]*'([^']+)/)\n    return m ? (m[1] ?? null) : null\n  }\n\n  async function cleanupAfterGitFailure(command: string): Promise<void> {\n    // 哨兵识别清扫脚本自身：它也定义 $g 且可能失败（如 taskkill 缺失），\n    // 不拦住会「清扫失败 → 再清扫」无限递归\n    if (!command || String(command).indexOf('RECALL_CLEANUP') >= 0) return\n    const gitDir = extractGitDir(command)\n    if (!gitDir) return\n    try {\n      const out = await runShell(scripts.killOrphansScript(gitDir), { timeoutMs: 60000, stdoutMaxBytes: 4096 })\n      // M3：清扫让路的两种情形都值得一条记录——前者把 issue #11 的「疑似\n      // 多实例」升级为「确认」（点名 PID），后者解释了环境为何没有被自动\n      // 清理。recordError 的尾部去重保证逐消息重复失败不会刷屏。\n      const r = parseCleanupResult(out)\n      if (r.otherPid !== null) recordError('recall 检测到另一个 DSH 实例（PID ' + r.otherPid + '）正在使用此快照库，失败清扫已让路：未杀进程、未动锁')\n      else if (r.skippedFresh) recordError('recall 检测到 5 分钟内的新锁文件，疑似 git 操作正在进行，失败清扫已让路（锁陈旧后会自动清理）')\n    } catch (error) { /* best-effort：清扫失败不影响原始错误的抛出 */ }\n  }\n\n  async function resolveRoot(sessionId: string | null): Promise<string | null> {\n    const key = sessionId ? String(sessionId) : 'fallback'\n    const cached = state.roots.get(key)\n    if (cached) return cached\n    let root = null\n    // 是否为「真实会话来源」的解析结果（live header / 持久化 header）：\n    // 只有这类结果才允许进缓存。回退到 sandboxPolicy.workspaceRoot 的临时\n    // 结果不缓存——它通常是 harness 启动目录而非会话真实 cwd，一旦缓存，\n    // 会话稍后变 live/持久化后仍被旧错误根遮蔽，撤回按钮永不出现。\n    let authoritative = false\n    if (sessionId) {\n      const session = sessions.get(sessionId)\n      if (session && session.header && session.header.cwd) {\n        root = session.header.cwd\n        authoritative = true\n      }\n    }\n    if (!root && sessionId) {\n      // 冷会话（尚未 live，如页面先于会话注册就绪加载）从持久化 header\n      // 解析真实 cwd，避免回退 workspaceRoot（harness 启动目录）查错\n      // store。listSessions 是目录级 header 枚举，不触碰全量日志；解析\n      // 失败静默走回退，不阻断主流程。\n      try {\n        const query = ctx.get<SessionQueryEngine>('sessionQuery')\n        if (query && typeof query.listSessions === 'function') {\n          const records = await query.listSessions()\n          const rec = (records || []).find((r) => r && r.header && r.header.id === sessionId)\n          if (rec && rec.header && rec.header.cwd) {\n            root = rec.header.cwd\n            authoritative = true\n          }\n        }\n      } catch (error) { /* 冷元数据不可用则走回退 */ }\n    }\n    if (!root) {\n      const sp = ctx.get<{ workspaceRoot?: string }>('sandboxPolicy')\n      if (sp && sp.workspaceRoot) root = sp.workspaceRoot\n    }\n    if (root) {\n      // 尾分隔符归一（win32 保 \"D:\\\" 三字符盘根；POSIX 保 \"/\" 根）：\n      // cwd 是否带尾斜杠由上游决定，不归一会让哈希输入不一致（换 store\n      // 目录），也会让排除扫描的 ${f#\"$root\"/} 前缀剥离错一位。\n      root = root.replace(/[\\\\/]+$/, '') || (isWin ? root : '/')\n      if (isWin && root.length === 2) root += '\\\\'\n      if (authoritative) state.roots.set(key, root)\n    }\n    return root\n  }\n\n  // 解析 git 可执行文件路径：求值一次并缓存，脚本里用绝对路径调用，\n  // 避免每条命令依赖 PATH（DSH 进程 PATH 可能不含 git）。\n  async function resolveGit(): Promise<string> {\n    if (state.gitExe !== null) return state.gitExe\n    try {\n      const path = scripts.stripBom(await runShell(scripts.resolveGitScript(), { stdoutMaxBytes: 4096 })).trim()\n      state.gitExe = path || ''\n    } catch (error) {\n      // 解析失败缓存空串：脚本侧 $git 回退裸 git 走 PATH，真正失败在执行时暴露\n      state.gitExe = ''\n    }\n    return state.gitExe\n  }\n\n  // win32：哈希在 PowerShell 里算（SHA256 Create 兼容 PS 5.1），连带\n  // $env:DSH_HOME / $env:USERPROFILE 的解析都在 shell 侧完成。\n  // scripts 是按平台二选一的联合，homeDirScript 仅 pwsh 侧存在——本方法\n  // 只在 isWin 分支被触达，显式断言到 PwshScripts（豁免集事实源见 types/scripts.ts）\n  async function homeDirForWin(root: string): Promise<string | null> {\n    const envHome = (process.env && process.env.DSH_HOME) || ''\n    const text = scripts.stripBom(await runShell((scripts as PwshScripts).homeDirScript(root, envHome), { stdoutMaxBytes: 4096 })).trim()\n    if (!text) return null\n    // 折叠 Join-Path 可能带出的连续反斜杠；开头的双反斜杠是 UNC 前缀\n    // （DSH_HOME/主目录指到网络盘），折叠掉会把 \\\\server\\share 变成无效\n    // 的 \\server\\share，必须原样保留。\n    if (/^\\\\\\\\/.test(text)) return '\\\\\\\\' + text.slice(2).replace(/\\\\{2,}/g, '\\\\')\n    return text.replace(/\\\\{2,}/g, '\\\\')\n  }\n\n  // POSIX：shell 侧只探 bash env 里显式的 $DSH_HOME（DSH 执行器洗刷\n  // DSH_* 变量后通常为空）；为空时依次回退 Node 主进程的 DSH_HOME\n  // （宿主进程 env，用户导出可见）与 os.homedir()（补 /.dsh 层，见\n  // selectPosixHomeBase 的 I24 注释）。哈希用 Node crypto 统一算，规避\n  // Linux sha256sum / macOS shasum 的二选一移植成本。三档选择与旧容器\n  // 迁移编排都委托模块级纯函数（resolvePosixHomeBase），本方法只负责探测\n  // 输入与结果缓存（迁移随缓存每进程至多跑一次）。\n  async function posixHomeBaseResolve(): Promise<string> {\n    if (state.posixHomeBase === null) {\n      let probed = ''\n      try {\n        // probeHomeScript 仅 posix 侧存在，本方法只在 POSIX 运行时被触达\n        probed = (await runShell((scripts as PosixScripts).probeHomeScript(), { stdoutMaxBytes: 4096 })).trim()\n      } catch (error) {\n        // 探测失败按空串继续：三档选择退到进程 env/homedir（resolvePosixHomeBase）\n        probed = ''\n      }\n      state.posixHomeBase = await resolvePosixHomeBase(\n        { runShell, scripts: scripts as PosixScripts, recordError },\n        { probed, envHome: (process.env && process.env.DSH_HOME) || '', homedir: os.homedir() }\n      )\n    }\n    return state.posixHomeBase\n  }\n\n  async function homeDirForPosix(root: string): Promise<string> {\n    const base = await posixHomeBaseResolve()\n    const hash = crypto.createHash('sha256').update(root, 'utf8').digest('hex')\n    return base.replace(/\\/+$/, '') + '/dsh-recall-snapshots/' + hash\n  }\n\n  async function homeDirFor(root: string): Promise<string | null> {\n    return isWin ? homeDirForWin(root) : homeDirForPosix(root)\n  }\n\n  // 快照容器目录（<homeBase>/dsh-recall-snapshots，不含哈希子目录）：\n  // 设置页 exclude-get 的磁盘兜底用——冷启动时会话注册表为空（惰性\n  // 载入），但容器目录可能早已存在，此时共享 exclude.txt 仍应可编辑。\n  // 目录结构固定 <base>/dsh-recall-snapshots/<hash>，所以容器就是\n  // homeDirFor 结果的父目录：JS 侧 slice 推导，不再走第二条 shell 解析链\n  // （旧实现里 homeDirScript 与 homeContainerScript 的 $h 链靠注释人工\n  // 对齐，存在漂移风险）。失败返回 null 且不缓存，下次调用自然重试。\n  async function resolveHomeContainer() {\n    if (state.homeContainer) return state.homeContainer\n    let container = null\n    try {\n      const probeRoot = Array.from(state.roots.values())[0] || process.cwd()\n      const homeDir = await homeDirFor(probeRoot)\n      if (homeDir) container = homeDir.slice(0, homeDir.length - 65)\n    } catch (error) {\n      // 推导失败返回 null 且不缓存（下次调用自然重试，见函数头注释）\n      container = null\n    }\n    if (container) state.homeContainer = container\n    return container\n  }\n\n  // store 形态装配：exclude.txt 是用户自定义排除文件，home 存储时放在\n  // dsh-recall-snapshots 根（所有项目共享一份全局配置）；降级存储时放\n  // store 目录内部——降级目录本身已被排除规则覆盖，不再往项目根塞文件。\n  // git init <dir> 会把真实 git-dir 建在 <dir>/.git，所以 repo 是仓库\n  // 工作目录、git 是真实 git-dir——冒烟测试踩过的坑。\n  // maxFileBytes 从 config 注入 store：脚本模板（snapshot/diff/rollback\n  // 的超大文件剔除）按调用时从 store 读取，用户改 config 后下一条命令\n  // 即生效，无需重启——因此用 getter 跟随 config 热更新，而不是创建时\n  // 快照（settings 卡片改 maxFileBytes 后 store 缓存不重建）。\n  function makeStore(dir: string, home: boolean): StoreInfo {\n    const excludeFile = home\n      ? dir.slice(0, dir.lastIndexOf(SEP)) + SEP + 'exclude.txt'\n      : dir + SEP + 'exclude.txt'\n    return {\n      dir,\n      repo: dir + SEP + 'git',\n      git: dir + SEP + 'git' + SEP + '.git',\n      home,\n      excludeFile,\n      get maxFileBytes() { return config.maxFileBytes },\n      // issue #24 快照护栏：与 maxFileBytes 同款 getter——设置页改完上限，\n      // 下一次快照立即按新值判定，无需重启或重建 store 缓存\n      get maxWorkspaceBytes() { return config.maxWorkspaceBytes },\n      get scanBudgetMs() { return config.scanBudgetMs },\n    }\n  }\n\n  // 将磁盘枚举出的 store 目录临时包装成 store 对象。全部删除必须覆盖\n  // `root.txt`/`index.json` 已失步的历史仓库：这时无法安全地用 root 调\n  // `resolveStore`（它可能新建另一个目录），所以直接以已枚举的 dir 为准。\n  // home 参数只影响 excludeFile；删除 tag/index 不依赖它，因而未知时用\n  // false 也安全。\n  function storeFromDir(dir: string, home: boolean): StoreInfo {\n    return makeStore(dir, Boolean(home))\n  }\n\n  // store 级元数据 root.txt：内容为工作区绝对路径。store 目录名是 root 的\n  // 单向 SHA256，反解不了——「快照管理」跨工作区展示时靠它把哈希目录映射\n  // 回工作区名。best-effort（失败不阻断主流程），旧 store 在 resolveStore\n  // 再次被调用（重启后首个 init/快照/管理列表）时自然补写，存量自愈。\n  function persistRootHint(store: StoreInfo, root: string): void {\n    // best-effort：root.txt 只是展示元数据，写失败不阻断主链（下次 resolveStore 自愈重写）\n    writeTextViaShell(store.dir + SEP + 'root.txt', root).catch(() => {})\n  }\n\n  // 存储根：优先放 DSH home（保持项目目录干净）。shell 以宿主身份执行，\n  // 受限会话（workspace-write/read-only）也能写 home；只有 home 本身不可写\n  // （如 DSH_HOME 指向只读/网络盘）才降级到项目内（功能优先于干净）。\n  async function resolveStore(root: string): Promise<StoreInfo> {\n    const cached = state.stores.get(root)\n    if (cached) return cached\n    let homeDir: string | null = null\n    try {\n      homeDir = await homeDirFor(root)\n    } catch (error) {\n      // 解析失败按「无 home」处理：直接走项目内降级 store（功能优先）\n      homeDir = null\n    }\n    if (homeDir) {\n      try {\n        await runShell(scripts.mkdirScript(homeDir), { stdoutMaxBytes: 4096 })\n        const store = makeStore(homeDir, true)\n        state.stores.set(root, store)\n        persistRootHint(store, root)\n        return store\n      } catch (error) {\n        // 已 recordError 告警，落回项目内降级 store 继续（见函数头注释）\n        recordError('recall home store unavailable, falling back to workspace: ' + String(error))\n      }\n    }\n    const fallback = root + SEP + '.dsh-recall-snapshots'\n    await runShell(scripts.mkdirScript(fallback), { stdoutMaxBytes: 4096 })\n    const store = makeStore(fallback, false)\n    state.stores.set(root, store)\n    persistRootHint(store, root)\n    return store\n  }\n\n  // 旧版迁移：宿主身份执行前的版本在受限会话里会把影子仓库降级到项目内，\n  // 这里在下一条消息快照前把它整体迁回 home 并删除项目内目录，恢复\n  // 「项目目录干净」。失败节流 5 分钟，避免 home 不可写时每条消息白试。\n  async function tryUpgradeToHome(root: string): Promise<StoreInfo | null> {\n    const store = state.stores.get(root)\n    if (!store || store.home) return store || null\n    const now = Date.now()\n    const last = state.homeRetryAt.get(root) || 0\n    if (now - last < HOME_RETRY_MS) return store\n    state.homeRetryAt.set(root, now)\n    let homeDir: string | null = null\n    try {\n      homeDir = await homeDirFor(root)\n    } catch (error) {\n      // 解析失败按无 home：沿用降级 store，下轮重试（节流已记）\n      homeDir = null\n    }\n    if (!homeDir) return store\n    try {\n      await runShell(scripts.mkdirScript(homeDir), { stdoutMaxBytes: 4096 })\n      await runShell(scripts.migrateScript(store.dir, homeDir), { timeoutMs: 300000, stdoutMaxBytes: 4096 })\n      const upgraded = makeStore(homeDir, true)\n      state.stores.set(root, upgraded)\n      persistRootHint(upgraded, root)\n      state.gitReady.delete(store.git)\n      // 旧 store 的 gc 节流凭据随之作废，清掉避免新 store 误读\n      state.gcLastAt.delete(store.git)\n      state.gcCount.delete(store.git)\n      console.error('recall store upgraded to home:', root)\n      return upgraded\n    } catch (error) {\n      // 迁移失败保留降级 store 继续服务；5min 节流（HOME_RETRY_MS）避免白试\n      recordError('recall home upgrade failed: ' + String(error))\n      return store\n    }\n  }\n\n  // 任意长度文本落盘（index.json / exclude.txt / lineage.json / root.txt\n  // 共用），原子写（H2）：先写 <file>.tmp 再 rename 替换目标——写中途崩溃\n  // 最多留一个无害的 .tmp 残留（下次写覆盖），绝不会留下截断 JSON。\n  // PF-2：两平台统一「stdin 传全文 + 单进程落盘」（fileWriteStdinCmd，同名\n  // 导出纪律）。win32 曾按 base64 20000 字符分块——每块一条 PowerShell 进程，\n  // 索引几百条时 saveIndex = 6+ 条进程，而它在每条消息快照后、每次删除、\n  // 每次 init 都全量重写；POSIX 的 cat > tmp 内联命令一并迁进模板。stdin\n  // 不经命令行，argv 32767 上限与编码坑天然消失；pwsh 侧读取手法由探针\n  // 钉死（OpenStandardInput 字节流——Console.In 在 PS 5.1 按 GBK 解码必挂，\n  // 见 tests/probe/stdin-write.test.js 与 plan-performance.md 实施记录）。\n  // 空内容也落一次写（清空配置/空索引是合法状态），stdin 空串照常发送。\n  // rename 是同卷 O(1) 元数据操作，索引写频率为每消息一次，额外开销可忽略。\n  // rename 步的 ENOENT 容忍（WSL 双实例实弹发现）：每实例写同一个\n  // <file>.tmp 路径，并发时一方 rename 把 tmp 消费掉，另一方 rename 报\n  // 「No such file / does not exist」。容忍是安全的，因为能走到 rename\n  // 的前提是写侧（stdin 写）已完整成功——任一写步失败都在写侧直接抛\n  // （POSIX set -e 对 cat 失败终止 / pwsh EAP=Stop 对 WriteAllText 抛），\n  // 进不到这里；所以此刻 tmp 消失只可能是同伴先把完整内容 rename 到了\n  // 目标——本侧写语义已被达成。Windows 侧「偶发一次 Move-Item:\n  // index.json.tmp does not exist」即同根。不进 recordError（用户错误列表\n  // 刷屏正是要消除的症状），console.error 留诊断痕迹；其余错误原样抛出。\n  async function renameTmpQuietly(tmp: string, file: string): Promise<void> {\n    try {\n      await runShell(scripts.renameFileCmd(tmp, file), { stdoutMaxBytes: 4096 })\n    } catch (error) {\n      // ENOENT 容忍的安全论证见函数头注释（tmp 被并发写者消费 = 写语义已达成）\n      const basename = tmp.slice(tmp.lastIndexOf(SEP) + 1)\n      if (isTmpConsumedError(error, basename)) {\n        console.error('recall writeTextViaShell: ' + basename + ' 已被并发写者 rename 消费，视同成功')\n        return\n      }\n      throw error\n    }\n  }\n\n  async function writeTextViaShell(file: string, text: string): Promise<void> {\n    const body = String(text == null ? '' : text)\n    const tmp = file + '.tmp'\n    await runShell(scripts.fileWriteStdinCmd(tmp), { stdin: body, stdoutMaxBytes: 4096 })\n    await renameTmpQuietly(tmp, file)\n  }\n\n  // 建立影子仓库（幂等：gitReady 命中后直接跳过，省掉每条消息一次的\n  // config/exclude 重写）。同时回读 gc.stamp 种子化 gc 节流：让「上次 gc\n  // 时间」跨重启续存，避免天天重启的机器每开机都来一次全量 gc。\n  // 返回 {ok, error}（M1-D2）：失败原因必须传出——captureSnapshot 要把它\n  // 分类成 snapFeedback 的可行动提示（此前吞成布尔，客户端空轮询 20 次、\n  // 用户零感知，issue #11 主线缺口）；init/预热调用方忽略返回值，不受形状\n  // 变化影响。\n  async function ensureGit(root: string, store: StoreInfo): Promise<{ ok: boolean; error?: string }> {\n    if (state.gitReady.has(store.git)) return { ok: true }\n    const gitExe = await resolveGit()\n    if (!gitExe) {\n      // git 缺失分支：